export default "lue here would incorrectly reset the model selection whenever a\\n    # non-model field (like api_key) is cleared or set to a global variable.\\n    # An explicit model-field update carrying an empty value must NOT be\\n    # auto-filled: ``options`` spans every enabled provider, so ``options[0]``\\n    # would silently substitute a model from whichever provider iterates\\n    # first \u2014 one the node was never configured for.\\n    explicit_model_clear = field_name == model_field_name and not field_value\\n    current_model_value = build_config.get(model_field_name, {}).get(\\\"value\\\")\\n    if not current_model_value and not explicit_model_clear:\\n        options = visible_options\\n        if options:\\n            # Determine model type based on cache_key_prefix\\n            model_type = \\\"embeddings\\\" if cache_key_prefix == \\\"embedding_model_options\\\" else \\\"language\\\"\\n\\n            # Try to get user's default model from the variable service\\n            default_model_name = None\\n            default_model_provider = None\\n            try:\\n\\n                async def _get_default_model():\\n                    async with session_scope() as session:\\n                        variable_service = get_variable_service()\\n                        if variable_service is None:\\n                            return None, None\\n                        from langflow.services.variable.service import (\\n                            DatabaseVariableService,\\n                        )\\n\\n                        if not isinstance(variable_service, DatabaseVariableService):\\n                            return None, None\\n\\n                        # Variable names match those in the API\\n                        var_name = (\\n                            \\\"__default_embedding_model__\\\"\\n                            if model_type == \\\"embeddings\\\"\\n                            else \\\"__default_language_model__\\\"\\n                        )\\n\\n                        try:\\n                            var = await variable_service.get_variable_object(\\n                                user_id=(\\n                                    UUID(component.user_id) if isinstance(component.user_id, str) else component.user_id\\n                                ),\\n                                name=var_name,\\n                                session=session,\\n                            )\\n                            if var and var.value:\\n                                parsed_value = json.loads(var.value)\\n                                if isinstance(parsed_value, dict):\\n                                    return parsed_value.get(\\\"model_name\\\"), parsed_value.get(\\\"provider\\\")\\n                        except (ValueError, json.JSONDecodeError, TypeError):\\n                            # Variable not found or invalid format\\n                            logger.info(\\n                                \\\"Variable not found or invalid format: var_name=%s, user_id=%s, model_type=%s\\\",\\n                                var_name,\\n                                component.user_id,\\n                                model_type,\\n                                exc_info=True,\\n                            )\\n                        return None, None\\n\\n                default_model_name, default_model_provider = run_until_complete(_get_default_model())\\n            except Exception:  # noqa: BLE001\\n                # If we can't get default model, continue without it\\n                logger.info(\\\"Failed to get default model, continue without it\\\", exc_info=True)\\n\\n            # Find the default model in options\\n            default_model = None\\n            if default_model_name and default_model_provider:\\n                # Look for the user's preferred default model\\n                for opt in options:\\n                    if opt.get(\\\"name\\\") == default_model_name and opt.get(\\\"provider\\\") == default_model_provider:\\n                        default_model = opt\\n                        break\\n\\n            # A bare initial load is not a configuration act, and an unvalidated credential\\n            # harvested from the environment already marks a provider enabled, so falling\\n            # back to ``options[0]`` there pre-selects a provider the user never set up\\n            # (LE-2168). A user-triggered update or a just-replaced selection still fills.\\n            user_triggered = field_name is not None\\n            if not default_model and options and (user_triggered or replaced_unusable_selection):\\n                default_model = options[0]\\n\\n            if default_model:\\n                build_config[model_field_name][\\\"value\\\"] = [default_model]\\n\\n    # Handle visibility of the model input handle based on selection\\n    if cache_key_prefix == \\\"embedding_model_options\\\":\\n        build_config[model_field_name][\\\"input_types\\\"] = [\\\"Embeddings\\\"]\\n    else:\\n        build_config[model_field_name][\\\"input_types\\\"] = [\\\"LanguageModel\\\"]\\n\\n    return build_config\\n\\n\\n@lru_cache(maxsize=1)\\ndef _get_all_provider_mapped_fields() -> set[str]:\\n    \\\"\\\"\\\"Backward-compatible alias for provider mapped field names.\\\"\\\"\\\"\\n    return _get_all_provider_specific_field_names()\\n\\n\\ndef _is_model_name_only(value: Any) -> bool:\\n    \\\"\\\"\\\"True when ``value`` is a non-empty model name (or list of names).\\n\\n    ModelInput accepts a bare model name; the list-of-dicts shape is what\\n    the rest of the lifecycle expects. An empty/falsy value is NOT a name\\n    (it must keep its existing reset-to-default behavior).\\n    \\\"\\\"\\\"\\n    if isinstance(value, str):\\n        return bool(value.strip())\\n    return isinstance(value, list) and bool(value) and all(isinstance(item, str) for item in value)\\n\\n\\ndef handle_model_input_update(\\n    component: Any,\\n    build_config: dict,\\n    field_value: Any,\\n    field_name: str | None = None,\\n    *,\\n    cache_key_prefix: str = \\\"language_model_options\\\",\\n    get_options_func=None,\\n    model_field_name: str = \\\"model\\\",\\n) -> dict:\\n    \\\"\\\"\\\"Full update_build_config lifecycle for any component with a ModelInput.\\\"\\\"\\\"\\n    from lfx.base.models import unified_models as unified_models_module\\n\\n    def _selected_provider() -> str | None:\\n        selection = build_config.get(model_field_name, {}).get(\\\"value\\\")\\n        if isinstance(selection, list) and selection and isinstance(selection[0], dict):\\n            provider = selection[0].get(\\\"provider\\\")\\n            return provider if isinstance(provider, str) and provider else None\\n        return None\\n\\n    selected_provider_before_refresh = _selected_provider()\\n\\n    # If get_options_func is not provided, derive one from the declarative\\n    # ``filters`` dict on the ModelInput (e.g. Agent declares\\n    # ``filters={\\\"tool_calling\\\": True}``). The cache prefix is namespaced by\\n    # the sorted filter key/value pairs so different filter configurations\\n    # don't poison each other's caches. ``_resolve_filters`` reads the\\n    # class-level declaration as the canonical source so saved flows that\\n    # were persisted before the filter shipped (and therefore don't carry\\n    # ``filters`` in their stored template) still get the constraint applied.\\n    filters = _resolve_filters(component, build_config, model_field_name)\\n    if get_options_func is None:\\n        if filters:\\n            cache_key_prefix = _augmented_cache_key_prefix(cache_key_prefix, filters)\\n\\n            def get_options_func(user_id=None, _filters=filters):\\n                return unified_models_module.get_language_model_options(user_id=user_id, filters=_filters)\\n        else:\\n            get_options_func = unified_models_module.get_language_model_options\\n\\n    # ModelInput documents that a single model name / list of names is\\n    # auto-converted to the list-of-dicts shape. Honor that contract here\\n    # (e.g. the assistant's configure_component can persist a bare model\\n    # name like \\\"gpt-5.4\\\") so the rest of the lifecycle never indexes a\\n    # str as a dict \u2014 TypeError: string indices must be integers.\\n    if _is_model_name_only(field_value):\\n        from .model_catalog import normalize_model_names_to_dicts\\n\\n        field_value = normalize_model_names_to_dicts(field_value)\\n        if field_name == model_field_name and isinstance(build_config.get(model_field_name), dict):\\n            build_config[model_field_name][\\\"value\\\"] = field_value\\n\\n    # Step 1: Refresh/cache model options, set defaults and input_types\\n    build_config = update_model_options_in_build_config(\\n        component=component,\\n        build_config=build_config,\\n        cache_key_prefix=cache_key_prefix,\\n        get_options_func=get_options_func,\\n        field_name=field_name,\\n        field_value=field_value,\\n        model_field_name=model_field_name,\\n    )\\n    selected_provider_after_refresh = _selected_provider()\\n    provider_changed_during_refresh = selected_provider_before_refresh != selected_provider_after_refresh\\n    provider_auto_selected_during_refresh = (\\n        selected_provider_before_refresh is None and selected_provider_after_refresh is not None\\n    )\\n\\n    # When the user directly edits a provider-specific field (e.g. api_key),\\n    # skip the provider reset/re-population so their value is preserved.\\n    provider_mapped_fields = _get_all_provider_mapped_fields()\\n    edited_provider_field_state: tuple[str, dict[str, Any]] | None = None\\n    if (\\n        provider_auto_selected_during_refresh\\n        and field_name is not None\\n        and field_name in provider_mapped_fields\\n        and field_name in build_config\\n    ):\\n        field_config = build_config[field_name]\\n        edited_provider_field_state = (\\n            field_name,\\n            {key: field_config[key] for key in (\\\"value\\\", \\\"load_from_db\\\") if key in field_config},\\n        )\\n    if field_name in provider_mapped_fields and not provider_changed_during_refresh:\\n        return build_config\\n\\n    # If the model field is in connection mode (user chose \\\"Connect other models\\\"),\\n    # skip auto-selection and provider re-population so credentials stay cleared.\\n    if build_config.get(model_field_name, {}).get(\\\"_connection_mode\\\"):\\n        return build_config\\n\\n    # When the user changes the model selection, we need to reset/hide fields that may no longer apply\\n    if field_name == model_field_name:\\n        options = build_config[model_field_name].get(\\\"options\\\", [])\\n        build_config[model_field_name][\\\"options\\\"] = options\\n\\n        value_missing = not field_value or field_value[0] not in options\\n        if value_missing:\\n            # If the current value is not in the options (e.g. user switched to a model that\\n            # is no longer available), reset to avoid confusion so the user can pick a valid one.\\n            value_is_valid = bool(field_value) and any(\\n                option.get(\\\"name\\\") == field_value[0].get(\\\"name\\\")\\n                and option.get(\\\"provider\\\") == field_value[0].get(\\\"provider\\\")\\n                for option in options\\n            )\\n\\n            if value_is_valid:\\n                build_config[model_field_name][\\\"value\\\"] = field_value\\n            elif not field_value:\\n                # Explicitly cleared: stay empty. ``options`` is one flat list\\n                # across every enabled provider, so ``options[0]`` would pick a\\n                # model from an arbitrary provider the node never selected.\\n                build_config[model_field_name][\\\"value\\\"] = []\\n            else:\\n                # A non-empty invalid value resets to the first option so the\\n                # user can pick a valid one (e.g. the Agent filters flow that\\n                # drops a tool-incompatible model for a compatible default).\\n                build_config[model_field_name][\\\"value\\\"] = [options[0]] if options else \\\"\\\"\\n            field_value = build_config[model_field_name][\\\"value\\\"]\\n\\n    # Step 2: Reset provider-specific visibility without changing values.\\n    # Step 3 shows and configures the fields for the selected provider while\\n    # preserving every explicit raw value or global-variable assignment.\\n    for field in provider_mapped_fields:\\n        if field in build_config:\\n            field_config = build_config[field]\\n            field_config[\\\"show\\\"] = False\\n            field_config[\\\"required\\\"] = False\\n            if provider_changed_during_refresh:\\n                field_config[\\\"value\\\"] = \\\"\\\"\\n                field_config[\\\"load_from_db\\\"] = False\\n\\n    # Step 3: Show/configure the right fields for the selected provider\\n    # Use field_value when the user actively changed the model selection;\\n    # otherwise (initial load with empty field_value, or other field changes)\\n    # fall back to the value in build_config (which Step 1 may have set to the default model).\\n    current_model_value = (\\n        field_value\\n        if field_name == model_field_name and field_value\\n        else build_config.get(model_field_name, {}).get(\\\"value\\\")\\n    )\\n    if isinstance(current_model_value, list) and len(current_model_value) > 0:\\n        provider = current_model_value[0].get(\\\"provider\\\", \\\"\\\")\\n        if provider:\\n            build_config = unified_models_module.apply_provider_variable_config_to_build_config(build_config, provider)\\n\\n            # Resolve DropdownInput field values from the provider's configured\\n            # variables.  load_from_db doesn't work for dropdowns because the\\n            # variable key name isn't a valid dropdown option.\\n            if hasattr(component, \\\"user_id\\\") and component.user_id:\\n                _resolve_dropdown_provider_values(component.user_id, build_config, provider)\\n\\n        # Also handle WatsonX-specific embedding fields that are not in provider metadata\\n        if cache_key_prefix == \\\"embedding_model_options\\\":\\n            is_watsonx = provider == \\\"IBM WatsonX\\\"\\n            if \\\"truncate_input_tokens\\\" in build_config:\\n                build_config[\\\"truncate_input_tokens\\\"][\\\"show\\\"] = is_watsonx\\n            if \\\"input_text\\\" in build_config:\\n                build_config[\\\"input_text\\\"][\\\"show\\\"] = is_watsonx\\n\\n    # A cache refresh can auto-select a default provider while processing the\\n    # provider field the user just edited. Restore that field only when the\\n    # selected provider actually uses it; unrelated fields stay cleared.\\n    if edited_provider_field_state is not None:\\n        edited_field_name, edited_field_state = edited_provider_field_state\\n        edited_field_config = build_config[edited_field_name]\\n        if edited_field_config.get(\\\"show\\\", False):\\n            edited_field_config.update(edited_field_state)\\n\\n    # Hide and clear the API key field when the selected provider doesn't use one\\n    # (e.g. Ollama). ``apply_provider_variable_config_to_build_config`` already\\n    # sets ``show=True`` for providers whose metadata maps a variable to the\\n    # ``api_key`` field; if it wasn't shown, the provider has no api_key\\n    # variable and the previous provider's credential must not leak across\\n    # the switch.\\n    if \\\"api_key\\\" in build_config and not build_config[\\\"api_key\\\"].get(\\\"show\\\", False):\\n        build_config[\\\"api_key\\\"][\\\"value\\\"] = \\\"\\\"\\n        build_config[\\\"api_key\\\"][\\\"load_from_db\\\"] = False\\n\\n    return build_config\\n\\n\\ndef _resolve_dropdown_provider_values(\\n    user_id,\\n    build_config: dict,\\n    provider: str,\\n) -> None:\\n    \\\"\\\"\\\"Resolve actual values for DropdownInput fields from provider variables.\\n\\n    DropdownInput fields cannot use the load_from_db mechanism because the\\n    variable key name (e.g. ``WATSONX_URL``) is not a valid dropdown option.\\n    Instead, we resolve the stored value from the database/environment and\\n    set it directly on the field.\\n    \\\"\\\"\\\"\\n    from lfx.base.models import unified_models as unified_models_module\\n\\n    provider_vars = unified_models_module.get_provider_all_variables(provider)\\n\\n    # Collect dropdown fields that need resolution\\n    dropdown_var_keys: dict[str, str] = {}  # var_key -> mapping_field\\n    for var_info in provider_vars:\\n        component_meta = var_info.get(\\\"component_metadata\\\", {})\\n        mapping_field = component_meta.get(\\\"mapping_field\\\")\\n        if not mapping_field or mapping_field not in build_config:\\n            continue\\n\\n        field_config = build_config[mapping_field]\\n        if field_config.get(\\\"_input_type\\\") != \\\"DropdownInput\\\":\\n            continue\\n\\n        var_key = var_info.get(\\\"variable_key\\\")\\n        if var_key:\\n            dropdown_var_keys[var_key] = mapping_field\\n\\n    if not dropdown_var_keys:\\n        return\\n\\n    # Resolve all provider variables at once\\n    all_vars = unified_models_module.get_all_variables_for_provider(user_id, provider)\\n\\n    for var_key, field_name in dropdown_var_keys.items():\\n        field_config = build_config[field_name]\\n        resolved_value = all_vars.get(var_key)\\n        if resolved_value:\\n            field_config[\\\"value\\\"] = resolved_value\\n            field_config[\\\"load_from_db\\\"] = False\\n            logger.debug(\\n                \\\"Resolved DropdownInput field %s to %s\\\",\\n                field_name,\\n                resolved_value,\\n            )\\n        else:\\n            # If we can't resolve, fall back to the first dropdown option\\n            options = field_config.get(\\\"options\\\", [])\\n            if options:\\n                field_config[\\\"value\\\"] = options[0]\\n            field_config[\\\"load_from_db\\\"] = False\\n            logger.debug(\\n                \\\"Could not resolve variable %s for DropdownInput field %s, using default\\\",\\n                var_key,\\n                field_name,\\n            )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/models/unified_models/class_registry.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f2ccd4f340a1cb4209b6342d83a51f404cebdab4b93bf240ad7a048d3077e963\",\"content\":\"\\\"\\\"\\\"Lazy-import registry for model and embedding provider classes.\\n\\nKeeps import tables and caching logic for provider classes (e.g. ChatOpenAI,\\nOpenAIEmbeddings) so that only the package actually needed gets imported at\\nruntime.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport importlib\\n\\n# ---------------------------------------------------------------------------\\n# Import registries\\n# Mapping from class name to (module_path, attribute_name, install_hint | None).\\n# ---------------------------------------------------------------------------\\n\\n_MODEL_CLASS_IMPORTS: dict[str, tuple[str, str, str | None]] = {\\n    \\\"ChatOpenAI\\\": (\\\"langchain_openai\\\", \\\"ChatOpenAI\\\", None),\\n    \\\"ChatAnthropic\\\": (\\n        \\\"lfx.base.models.anthropic_chat_model\\\",\\n        \\\"ChatAnthropicThinkingCompat\\\",\\n        \\\"langchain-anthropic\\\",\\n    ),\\n    \\\"ChatGoogleGenerativeAIFixed\\\": (\\n        \\\"lfx.base.models.google_generative_ai_model\\\",\\n        \\\"ChatGoogleGenerativeAIFixed\\\",\\n        \\\"langchain-google-genai\\\",\\n    ),\\n    # AzureChatOpenAI ships in langchain_openai (already a dependency).\\n    \\\"AzureChatOpenAI\\\": (\\\"langchain_openai\\\", \\\"AzureChatOpenAI\\\", None),\\n    \\\"AzureAIOpenAIApiChatModel\\\": (\\n        \\\"langchain_azure_ai.chat_models\\\",\\n        \\\"AzureAIOpenAIApiChatModel\\\",\\n        \\\"langchain-azure-ai\\\",\\n    ),\\n    # ChatGroq needs the optional langchain-groq package \u2014 keep the install\\n    # hint so an unconfigured environment gets an actionable error instead of\\n    # an opaque \\\"Unknown model class: ChatGroq\\\". Both class names appear in\\n    # MODEL_PROVIDER_METADATA but were missing here, so selecting a Groq /\\n    # Azure model died with \\\"Unknown model class\\\".\\n    \\\"ChatGroq\\\": (\\\"langchain_groq\\\", \\\"ChatGroq\\\", \\\"langchain-groq\\\"),\\n    \\\"ChatOllama\\\": (\\\"langchain_ollama\\\", \\\"ChatOllama\\\", None),\\n    \\\"ChatWatsonx\\\": (\\\"langchain_ibm\\\", \\\"ChatWatsonx\\\", None),\\n}\\n\\n_EMBEDDING_CLASS_IMPORTS: dict[str, tuple[str, str, str | None]] = {\\n    \\\"OpenAIEmbeddings\\\": (\\\"langchain_openai\\\", \\\"OpenAIEmbeddings\\\", None),\\n    \\\"GoogleGenerativeAIEmbeddings\\\": (\\n        \\\"langchain_google_genai\\\",\\n        \\\"GoogleGenerativeAIEmbeddings\\\",\\n        None,\\n    ),\\n    \\\"OllamaEmbeddings\\\": (\\\"langchain_ollama\\\", \\\"OllamaEmbeddings\\\", None),\\n    \\\"WatsonxEmbeddings\\\": (\\\"langchain_ibm\\\", \\\"WatsonxEmbeddings\\\", None),\\n}\\n\\n# Canonical mapping of provider name \u2192 embedding class name.\\n# Used by EmbeddingModelComponent and by flow_requirements to resolve\\n# which PyPI package a given embedding provider needs at runtime.\\nEMBEDDING_PROVIDER_CLASS_MAPPING: dict[str, str] = {\\n    \\\"OpenAI\\\": \\\"OpenAIEmbeddings\\\",\\n    \\\"Google Generative AI\\\": \\\"GoogleGenerativeAIEmbeddings\\\",\\n    \\\"Ollama\\\": \\\"OllamaEmbeddings\\\",\\n    \\\"IBM WatsonX\\\": \\\"WatsonxEmbeddings\\\",\\n    \\\"IBM watsonx.ai\\\": \\\"WatsonxEmbeddings\\\",  # Alias used by MODEL_PROVIDERS_DICT\\n    # Foundry: OpenAI-compatible embeddings; deployment name is ``model``.\\n    \\\"Azure AI Foundry\\\": \\\"OpenAIEmbeddings\\\",\\n}\\n\\n# Provider \u2192 param-name mapping for embedding-model instantiation.\\n# Keys are abstract slots (\\\"model\\\", \\\"api_key\\\", \u2026); values are the actual\\n# kwarg names each LangChain embedding class expects. Used both when\\n# enriching catalog options and as the fallback inside\\n# ``_instantiate_embeddings`` when the persisted ``model_selection``\\n# was saved without the enriched metadata (e.g. picked via the generic\\n# ``/models`` endpoint instead of ``get_embedding_model_options``).\\nEMBEDDING_PARAM_MAPPINGS: dict[str, dict[str, str]] = {\\n    \\\"OpenAI\\\": {\\n        \\\"model\\\": \\\"model\\\",\\n        \\\"api_key\\\": \\\"api_key\\\",\\n        \\\"api_base\\\": \\\"base_url\\\",\\n        \\\"dimensions\\\": \\\"dimensions\\\",\\n        \\\"chunk_size\\\": \\\"chunk_size\\\",\\n        \\\"request_timeout\\\": \\\"timeout\\\",\\n        \\\"max_retries\\\": \\\"max_retries\\\",\\n        \\\"show_progress_bar\\\": \\\"show_progress_bar\\\",\\n        \\\"model_kwargs\\\": \\\"model_kwargs\\\",\\n    },\\n    \\\"Google Generative AI\\\": {\\n        \\\"model\\\": \\\"model\\\",\\n        \\\"api_key\\\": \\\"google_api_key\\\",\\n        \\\"dimensions\\\": \\\"output_dimensionality\\\",\\n        \\\"request_timeout\\\": \\\"request_options\\\",\\n        \\\"model_kwargs\\\": \\\"client_options\\\",\\n    },\\n    \\\"Ollama\\\": {\\n        \\\"model\\\": \\\"model\\\",\\n        \\\"base_url\\\": \\\"base_url\\\",\\n        \\\"num_ctx\\\": \\\"num_ctx\\\",\\n        \\\"request_timeout\\\": \\\"request_timeout\\\",\\n        \\\"model_kwargs\\\": \\\"model_kwargs\\\",\\n    },\\n    \\\"IBM WatsonX\\\": {\\n        \\\"model_id\\\": \\\"model_id\\\",\\n        \\\"url\\\": \\\"url\\\",\\n        \\\"api_key\\\": \\\"apikey\\\",\\n        \\\"project_id\\\": \\\"project_id\\\",\\n        \\\"space_id\\\": \\\"space_id\\\",\\n        \\\"request_timeout\\\": \\\"request_timeout\\\",\\n    },\\n    \\\"Azure AI Foundry\\\": {\\n        \\\"model\\\": \\\"model\\\",\\n        \\\"api_key\\\": \\\"api_key\\\",\\n        \\\"api_base\\\": \\\"base_url\\\",\\n        \\\"dimensions\\\": \\\"dimensions\\\",\\n        \\\"chunk_size\\\": \\\"chunk_size\\\",\\n        \\\"request_timeout\\\": \\\"timeout\\\",\\n        \\\"max_retries\\\": \\\"max_retries\\\",\\n    },\\n}\\n\\n# NOTE: These module-level caches are never invalidated.  This is intentional\\n# for production, but tests that need to swap model/embedding classes should\\n# patch `get_model_class` / `get_embedding_class` at the *call site* rather\\n# than mutating these dicts, to avoid cross-test pollution.\\n_model_class_cache: dict[str, type] = {}\\n_embedding_class_cache: dict[str, type] = {}\\n\\n\\n# ---------------------------------------------------------------------------\\n# Shared helper\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _import_class(\\n    class_name: str,\\n    registry: dict[str, tuple[str, str, str | None]],\\n    cache: dict[str, type],\\n    kind: str,\\n) -> type:\\n    \\\"\\\"\\\"Import and return a single class by name from *registry*.\\n\\n    Parameters\\n    ----------\\n    class_name:\\n        Key into *registry*.\\n    registry:\\n        One of ``_MODEL_CLASS_IMPORTS`` / ``_EMBEDDING_CLASS_IMPORTS``.\\n    cache:\\n        One of ``_model_class_cache`` / ``_embedding_class_cache``.\\n    kind:\\n        Human-readable label (``\\\"model\\\"`` or ``\\\"embedding\\\"``) for error messages.\\n    \\\"\\\"\\\"\\n    if class_name in cache:\\n        return cache[class_name]\\n\\n    import_info = registry.get(class_name)\\n    if import_info is None:\\n        msg = f\\\"Unknown {kind} class: {class_name}\\\"\\n        raise ValueError(msg)\\n\\n    module_path, attr_name, install_hint = import_info\\n    pkg_hint = install_hint or module_path.split(\\\".\\\")[0].replace(\\\"_\\\", \\\"-\\\")\\n    try:\\n        module = importlib.import_module(module_path)\\n    except ImportError as exc:\\n        msg = (\\n            f\\\"Could not import '{module_path}' for {kind} class '{class_name}'. \\\"\\n            f\\\"Install the missing package (e.g. uv pip install {pkg_hint}).\\\"\\n        )\\n        raise ImportError(msg) from exc\\n    try:\\n        cls = getattr(module, attr_name)\\n    except AttributeError as exc:\\n        msg = (\\n            f\\\"Module '{module_path}' was imported but does not have attribute '{attr_name}'. \\\"\\n            f\\\"This may indicate a version mismatch. \\\"\\n        )\\n        raise AttributeError(msg) from exc\\n    cache[class_name] = cls\\n    return cls\\n\\n\\n# ---------------------------------------------------------------------------\\n# Public API\\n# ---------------------------------------------------------------------------\\n\\n\\ndef get_model_class(class_name: str) -> type:\\n    \\\"\\\"\\\"Import and return a single model class by name.\\n\\n    Only imports the provider package that is actually needed.\\n    \\\"\\\"\\\"\\n    return _import_class(class_name, _MODEL_CLASS_IMPORTS, _model_class_cache, \\\"model\\\")\\n\\n\\ndef get_embedding_class(class_name: str) -> type:\\n    \\\"\\\"\\\"Import and return a single embedding class by name.\\n\\n    Only imports the provider package that is actually needed.\\n    \\\"\\\"\\\"\\n    return _import_class(class_name, _EMBEDDING_CLASS_IMPORTS, _embedding_class_cache, \\\"embedding\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/models/unified_models/credentials.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"10ebc76e8ad7f66842fd322e7af8d32ceefc43df6b71c85519566ee3862f5ec3\",\"content\":\"\\\"\\\"\\\"Credential resolution and provider validation helpers.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nimport json\\nimport os\\nimport re\\nfrom typing import TYPE_CHECKING, Any\\nfrom uuid import UUID\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.deps import get_variable_service, session_scope\\nfrom lfx.services.variable import VariableNotFoundError\\nfrom lfx.services.variable.request_scope import is_env_fallback_disabled\\nfrom lfx.utils.async_helpers import run_until_complete\\nfrom lfx.utils.env_var_security import safe_getenv\\nfrom lfx.utils.secrets import secret_value_to_str\\nfrom lfx.utils.ssrf_protection import validate_connector_url_for_ssrf\\n\\nfrom .provider_queries import (\\n    get_model_provider_variable_mapping,\\n    get_model_providers,\\n    get_provider_all_variables,\\n    get_provider_secret_variable_key,\\n)\\n\\nif TYPE_CHECKING:\\n    from lfx.services.model_provider_policy import ModelProviderPolicySnapshot\\n\\nMODEL_STATUS_KEY_SEPARATOR = \\\"::\\\"\\nMODEL_STATUS_TYPES = (\\\"llm\\\", \\\"embeddings\\\")\\n\\n\\ndef model_status_key(provider: str, model_name: str, model_type: str | None = None) -> str:\\n    \\\"\\\"\\\"Return the stable identity used in persisted model-status variables.\\\"\\\"\\\"\\n    if model_type is not None:\\n        if model_type not in MODEL_STATUS_TYPES:\\n            msg = f\\\"Unsupported model status type: {model_type}\\\"\\n            raise ValueError(msg)\\n        return f\\\"{provider}{MODEL_STATUS_KEY_SEPARATOR}{model_type}{MODEL_STATUS_KEY_SEPARATOR}{model_name}\\\"\\n    return f\\\"{provider}{MODEL_STATUS_KEY_SEPARATOR}{model_name}\\\"\\n\\n\\ndef parse_model_status_key(entry: str) -> tuple[str | None, str, str | None]:\\n    \\\"\\\"\\\"Parse a bare, provider-qualified, or typed model-status identity.\\n\\n    The split is deliberately bounded so deployment names containing ``::``\\n    survive intact. Legacy provider-qualified entries have no type; only the\\n    canonical ``llm`` and ``embeddings`` second segments identify typed keys.\\n    \\\"\\\"\\\"\\n    parts = entry.split(MODEL_STATUS_KEY_SEPARATOR, 2)\\n    match parts:\\n        case [bare_name]:\\n            return None, bare_name, None\\n        case [provider, model_name]:\\n            return provider, model_name, None\\n        case [provider, possible_type, remainder]:\\n            if possible_type in MODEL_STATUS_TYPES:\\n                return provider, remainder, possible_type\\n            return provider, f\\\"{possible_type}{MODEL_STATUS_KEY_SEPARATOR}{remainder}\\\", None\\n    msg = \\\"Model status key could not be parsed\\\"\\n    raise ValueError(msg)\\n\\n\\ndef model_status_contains(\\n    entries: set[str],\\n    provider: str,\\n    model_name: str,\\n    model_type: str | None = None,\\n) -> bool:\\n    \\\"\\\"\\\"Check typed status while honoring provider-qualified and bare legacy entries.\\\"\\\"\\\"\\n    if model_status_key(provider, model_name) in entries or model_name in entries:\\n        return True\\n    if model_type is not None:\\n        return model_status_key(provider, model_name, model_type) in entries\\n    return any(\\n        model_status_key(provider, model_name, candidate_type) in entries for candidate_type in MODEL_STATUS_TYPES\\n    )\\n\\n\\ndef get_api_key_for_provider(user_id: UUID | str | None, provider: str, api_key: Any = None) -> str | None:\\n    \\\"\\\"\\\"Get API key from component input or global variables.\\n\\n    When api_key is set to an environment variable name (e.g. ANTHROPIC_API_KEY),\\n    that name is resolved from os.environ or global variables so imported flows\\n    can reference credentials without storing the raw key.\\n    \\\"\\\"\\\"\\n    # SecretStrInput-backed fields arrive as SecretStr to prevent leakage through\\n    # stringification. Unwrap here because provider clients need the raw value.\\n    api_key = secret_value_to_str(api_key, strip=True)\\n\\n    # Resolve variable name (canonical or custom e.g. MY_OPENAI_API_KEY) from\\n    # global vars or env. The user's per-user, encrypted DB global variable is\\n    # the source of truth (it's what the Agent component resolves via\\n    # load_from_db) and MUST win over a process-wide ``.env`` value \u2014 otherwise\\n    # a stale/revoked .env key silently shadows the key the user configured in\\n    # the UI (and, in multi-tenant deploys, every user shares a server-wide env\\n    # key). Env is the fallback for the no-user (lfx run) / no-DB-value case.\\n    def _resolve_var_name(var_name: str) -> str | None:\\n        if user_id and not (isinstance(user_id, str) and user_id == \\\"None\\\"):\\n\\n            async def _get_by_var_name():\\n                async with session_scope() as session:\\n                    variable_service = get_variable_service()\\n                    if variable_service is None:\\n                        return None\\n                    try:\\n                        return await variable_service.get_variable(\\n                            user_id=(UUID(user_id) if isinstance(user_id, str) else user_id),\\n                            name=var_name,\\n                            field=\\\"\\\",\\n                            session=session,\\n                        )\\n                    except VariableNotFoundError:\\n                        return None\\n\\n            value = run_until_complete(_get_by_var_name())\\n            value = secret_value_to_str(value, strip=True)\\n            if value:\\n                return value\\n        # Honor the request's no-env-fallback contract: skip os.environ when disabled so a\\n        # served flow stays isolated from process-wide credentials (matches VariableService).\\n        if not is_env_fallback_disabled():\\n            # safe_getenv denies reserved names (LANGFLOW_SECRET_KEY, DATABASE_URL, ...) so a\\n            # tenant-supplied api_key field cannot exfiltrate the server's own secrets via the\\n            # env fallback (the resolved value is otherwise used as a live provider key).\\n            env_value = safe_getenv(var_name)\\n            if env_value and env_value.strip():\\n                return env_value.strip()\\n        return None\\n\\n    if api_key and api_key.strip():\\n        var_name = api_key.strip()\\n        # A malformed or legacy component can point its api_key field at any\\n        # global variable name. Never reinterpret declared non-secret provider\\n        # configuration (for example, a base URL) as bearer credentials.\\n        if any(\\n            variable.get(\\\"variable_key\\\") == var_name and not variable.get(\\\"is_secret\\\")\\n            for variable in get_provider_all_variables(provider)\\n        ):\\n            return None\\n        # Names that look like env/global variables (e.g. MY_OPENAI_API_KEY): resolve from env/DB\\n        if var_name.replace(\\\"_\\\", \\\"\\\").isalnum() and var_name[0].isalpha():\\n            resolved = _resolve_var_name(var_name)\\n            if resolved:\\n                return resolved\\n            # Unresolved variable name: don't use as literal key\\n            if re.match(r\\\"^[A-Z][A-Z0-9_]*$\\\", var_name):\\n                return None\\n        # Literal API key (e.g. sk-...)\\n        return var_name\\n\\n    # Get primary variable (first required secret) from provider metadata\\n    variable_name = get_provider_secret_variable_key(provider)\\n    if not variable_name:\\n        return None\\n\\n    # Try the database-backed variable service first when a user_id is available.\\n    # Fall through to os.environ regardless so lfx run (no user_id) can still pick\\n    # up canonical credentials from the shell.\\n    has_user = user_id is not None and not (isinstance(user_id, str) and user_id == \\\"None\\\")\\n    api_key = None\\n    if has_user:\\n\\n        async def _get_variable():\\n            async with session_scope() as session:\\n                variable_service = get_variable_service()\\n                if variable_service is None:\\n                    return None\\n                try:\\n                    return await variable_service.get_variable(\\n                        user_id=UUID(user_id) if isinstance(user_id, str) else user_id,\\n                        name=variable_name,\\n                        field=\\\"\\\",\\n                        session=session,\\n                    )\\n                except VariableNotFoundError:\\n                    return None\\n\\n        api_key = run_until_complete(_get_variable())\\n\\n    api_key = secret_value_to_str(api_key, strip=True)\\n    if api_key:\\n        return api_key\\n\\n    if is_env_fallback_disabled():\\n        return None\\n    env_value = safe_getenv(variable_name)\\n    return env_value.strip() if env_value and env_value.strip() else None\\n\\n\\ndef provider_variable_from_env(var_key: str) -> str | None:\\n    \\\"\\\"\\\"Read a provider variable from the environment, accepting a LANGFLOW_ alias.\\n\\n    The single answer to \\\"what is this provider variable's environment value\\\".\\n    Live model discovery resolves the same variables, so it shares this helper\\n    rather than reading ``os.environ`` directly \u2014 two readers that disagreed on\\n    accepted name shapes would leave a provider enabled but undiscoverable.\\n\\n    Provider keys are conventionally bare (``GOOGLE_API_KEY``), but some .env\\n    templates prefix everything with ``LANGFLOW_`` (matching how Langflow reads\\n    its own settings). Accept ``LANGFLOW_<VAR>`` as a fallback so e.g.\\n    ``LANGFLOW_GOOGLE_API_KEY`` enables Gemini exactly like ``GOOGLE_API_KEY``.\\n    The bare name keeps precedence \u2014 no behavior change when it is set. The\\n    resolved value is always stored under the bare canonical key by callers, so\\n    downstream detection (available_model_providers, get_llm) is unaffected.\\n    \\\"\\\"\\\"\\n    value = os.environ.get(var_key)\\n    if value and value.strip():\\n        return value\\n    prefixed = os.environ.get(f\\\"LANGFLOW_{var_key}\\\")\\n    if prefixed and prefixed.strip():\\n        return prefixed\\n    return None\\n\\n\\ndef get_all_variables_for_provider(user_id: UUID | str | None, provider: str) -> dict[str, str]:\\n    \\\"\\\"\\\"Get all configured variables for a provider from database or environment.\\\"\\\"\\\"\\n    result: dict[str, str] = {}\\n\\n    # Get all variable definitions for this provider\\n    provider_vars = get_provider_all_variables(provider)\\n    if not provider_vars:\\n        return result\\n\\n    # If no user_id, only check environment variables. Honor the request's no-env-fallback\\n    # contract: a served flow under no_env_fallback stays isolated from process-wide\\n    # credentials, so return nothing rather than leaking os.environ into provider_vars\\n    # (which would defeat the _env_if_allowed guards in instantiation.py).\\n    if user_id is None or (isinstance(user_id, str) and user_id == \\\"None\\\"):\\n        if is_env_fallback_disabled():\\n            return result\\n        for var_info in provider_vars:\\n            var_key = var_info.get(\\\"variable_key\\\")\\n            if var_key:\\n                env_value = provider_variable_from_env(var_key)\\n                if env_value:\\n                    result[var_key] = env_value\\n        return result\\n\\n    # Try to get from global variables (database)\\n    async def _get_all_variables():\\n        async with session_scope() as session:\\n            variable_service = get_variable_service()\\n            if variable_service is None:\\n                return {}\\n\\n            values = {}\\n            user_id_uuid = UUID(user_id) if isinstance(user_id, str) else user_id\\n\\n            for var_info in provider_vars:\\n                var_key = var_info.get(\\\"variable_key\\\")\\n                if not var_key:\\n                    continue\\n\\n                try:\\n                    value = await variable_service.get_variable(\\n                        user_id=user_id_uuid,\\n                        name=var_key,\\n                        field=\\\"\\\",\\n                        session=session,\\n                    )\\n                    value = secret_value_to_str(value, strip=True)\\n                    if value:\\n                        values[var_key] = value\\n                except VariableNotFoundError:\\n                    # Variable not found - check environment, unless the request disables\\n                    # env fallback (keeps served flows isolated from process-wide credentials).\\n                    if is_env_fallback_disabled():\\n                        continue\\n                    env_value = provider_variable_from_env(var_key)\\n                    if env_value:\\n                        values[var_key] = env_value\\n\\n            return values\\n\\n    db_values = run_until_complete(_get_all_variables())\\n\\n    # decrypt_api_key swallows Fernet InvalidToken silently and returns \\\"\\\",\\n    # so a SECRET_KEY rotation leaves required keys missing from db_values\\n    # even when the env var is set. Mirror get_api_key_for_provider's\\n    # post-async env fallback so the assistant doesn't reject the request\\n    # with \\\"Missing required configuration\\\" while the env var is present.\\n    for var_info in provider_vars:\\n        var_key = var_info.get(\\\"variable_key\\\")\\n        if not var_key or db_values.get(var_key):\\n            continue\\n        # Honor the request's no-env-fallback contract: a served flow under\\n        # no_env_fallback must stay isolated from process-wide credentials even on\\n        # this post-DB-miss rotation fallback.\\n        if is_env_fallback_disabled():\\n            continue\\n        env_value = provider_variable_from_env(var_key)\\n        if env_value:\\n            db_values[var_key] = env_value\\n\\n    return db_values\\n\\n\\ndef _validate_and_get_enabled_providers(\\n    all_variables: dict[str, Any],\\n    provider_variable_map: dict[str, str],\\n    *,\\n    skip_validation: bool = True,\\n) -> set[str]:\\n    \\\"\\\"\\\"Return set of enabled providers based on credential existence.\\\"\\\"\\\"\\n    from langflow.services.auth import utils as auth_utils\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    enabled = set()\\n    from lfx.base.models.provider_registry import is_api_key_optional\\n\\n    for provider in provider_variable_map:\\n        provider_vars = get_provider_all_variables(provider)\\n\\n        collected_values: dict[str, str] = {}\\n        all_required_present = True\\n\\n        for var_info in provider_vars:\\n            var_key = var_info.get(\\\"variable_key\\\")\\n            if not var_key:\\n                continue\\n\\n            is_required = bool(var_info.get(\\\"required\\\", False))\\n            value = None\\n\\n            if var_key in all_variables:\\n                variable = all_variables[var_key]\\n                if variable.value is not None:\\n                    try:\\n                        decrypted_value = auth_utils.decrypt_api_key(variable.value, settings_service=settings_service)\\n                        if decrypted_value and decrypted_value.strip():\\n                            value = decrypted_value\\n                    except Exception as e:  # noqa: BLE001\\n                        raw_value = variable.value\\n                        if raw_value is not None and str(raw_value).strip():\\n                            value = str(raw_value)\\n                        else:\\n                            logger.debug(\\n                                \\\"Failed to decrypt variable %s for provider %s: %s\\\",\\n                                var_key,\\n                                provider,\\n                                e,\\n                            )\\n\\n            if value is None:\\n                env_value = os.environ.get(var_key)\\n                if env_value and env_value.strip() and env_value.strip() != \\\"dummy\\\":\\n                    value = env_value\\n                    logger.debug(\\n                        \\\"Using environment variable %s for provider %s\\\",\\n                        var_key,\\n                        provider,\\n                    )\\n\\n            if value:\\n                collected_values[var_key] = value\\n            elif is_required:\\n                all_required_present = False\\n\\n        if not provider_vars:\\n            if is_api_key_optional(provider):\\n                enabled.add(provider)\\n        elif all_required_present and (collected_values or is_api_key_optional(provider)):\\n            if skip_validation or not collected_values:\\n                # Just check existence - validation was done on save\\n                enabled.add(provider)\\n            else:\\n                try:\\n                    validate_model_provider_key(provider, collected_values)\\n                    enabled.add(provider)\\n                except (ValueError, Exception) as e:  # noqa: BLE001\\n                    logger.debug(\\\"Provider %s validation failed: %s\\\", provider, e)\\n\\n    return enabled\\n\\n\\nclass _VarWithValue:\\n    \\\"\\\"\\\"Simple wrapper for passing raw variable values to _validate_and_get_enabled_providers.\\\"\\\"\\\"\\n\\n    __slots__ = (\\\"value\\\",)\\n\\n    def __init__(self, value):\\n        self.value = value\\n\\n\\nasync def _get_model_status(user_id: UUID | str) -> tuple[set[str], set[str]]:\\n    \\\"\\\"\\\"Fetch disabled and explicitly enabled model sets for a user.\\n\\n    Returns:\\n        A tuple of (disabled_models, explicitly_enabled_models).\\n    \\\"\\\"\\\"\\n    async with session_scope() as session:\\n        variable_service = get_variable_service()\\n        if variable_service is None:\\n            return set(), set()\\n        from langflow.services.variable.service import DatabaseVariableService\\n\\n        if not isinstance(variable_service, DatabaseVariableService):\\n            return set(), set()\\n        all_vars = await variable_service.get_all(\\n            user_id=UUID(user_id) if isinstance(user_id, str) else user_id,\\n            session=session,\\n        )\\n        disabled: set[str] = set()\\n        enabled: set[str] = set()\\n        for var in all_vars:\\n            if var.name == \\\"__disabled_models__\\\" and var.value:\\n                with contextlib.suppress(json.JSONDecodeError, TypeError):\\n                    disabled = set(json.loads(var.value))\\n            elif var.name == \\\"__enabled_models__\\\" and var.value:\\n                with contextlib.suppress(json.JSONDecodeError, TypeError):\\n                    enabled = set(json.loads(var.value))\\n        return disabled, enabled\\n\\n\\nasync def _fetch_enabled_providers_for_user(\\n    user_id: UUID | str,\\n    *,\\n    provider_policy: ModelProviderPolicySnapshot | None = None,\\n) -> set[str]:\\n    \\\"\\\"\\\"Return credential-enabled providers allowed for configuration and by the caller.\\\"\\\"\\\"\\n    variable_service = get_variable_service()\\n    if variable_service is None:\\n        return set()\\n\\n    from langflow.services.variable.service import DatabaseVariableService\\n\\n    if not isinstance(variable_service, DatabaseVariableService):\\n        return set()\\n\\n    provider_variable_map = get_model_provider_variable_mapping()\\n    providers = get_model_providers()\\n    from lfx.services.model_provider_policy import ModelProviderPolicyPurpose, aresolve_model_provider_policy\\n\\n    configuration_policy = await aresolve_model_provider_policy(\\n        user_id=user_id,\\n        providers=providers,\\n        purpose=ModelProviderPolicyPurpose.CONFIGURE,\\n        attributes=provider_policy.context.attributes if provider_policy is not None else None,\\n    )\\n    from lfx.base.models.provider_registry import is_api_key_optional\\n\\n    provider_candidates = {\\n        **provider_variable_map,\\n        **{\\n            provider: \\\"\\\"\\n            for provider in providers\\n            if provider not in provider_variable_map and is_api_key_optional(provider)\\n        },\\n    }\\n    provider_candidates = {\\n        provider: variable\\n        for provider, variable in provider_candidates.items()\\n        if configuration_policy.allows(provider) and (provider_policy is None or provider_policy.allows(provider))\\n    }\\n    if not provider_candidates:\\n        return set()\\n\\n    async with session_scope() as session:\\n        # Get all variable names (VariableRead has value=None for credentials)\\n        all_vars = await variable_service.get_all(\\n            user_id=UUID(user_id) if isinstance(user_id, str) else user_id,\\n            session=session,\\n        )\\n        all_var_names = {var.name for var in all_vars}\\n\\n        # Build dict with raw Variable values (encrypted for secrets, plaintext for others)\\n        # We need to fetch raw Variable objects because VariableRead has value=None for credentials\\n        all_provider_variables = {}\\n        user_id_uuid = UUID(user_id) if isinstance(user_id, str) else user_id\\n\\n        for provider in provider_candidates:\\n            # Get ALL variables for this provider (not just the primary one)\\n            provider_vars = get_provider_all_variables(provider)\\n\\n            for var_info in provider_vars:\\n                var_name = var_info.get(\\\"variable_key\\\")\\n                if not var_name or var_name not in all_var_names:\\n                    # Variable not configured by user\\n                    continue\\n\\n                if var_name in all_provider_variables:\\n                    # Already fetched\\n                    continue\\n\\n                try:\\n                    # Get the raw Variable object to access the actual value\\n                    variable_obj = await variable_service.get_variable_object(\\n                        user_id=user_id_uuid, name=var_name, session=session\\n                    )\\n                    if variable_obj and variable_obj.value:\\n                        all_provider_variables[var_name] = _VarWithValue(variable_obj.value)\\n                except Exception as e:  # noqa: BLE001\\n                    # Variable not found or error accessing it - skip\\n                    logger.error(f\\\"Error accessing variable {var_name} for provider {provider}: {e}\\\")\\n                    continue\\n\\n        # Use shared helper to validate and get enabled providers\\n        return _validate_and_get_enabled_providers(all_provider_variables, provider_candidates)\\n\\n\\ndef validate_model_provider_key(provider: str, variables: dict[str, str], model_name: str | None = None) -> None:\\n    \\\"\\\"\\\"Validate a model provider by making a minimal test call.\\\"\\\"\\\"\\n    if not provider:\\n        return\\n\\n    first_model = None\\n    provider_models: list[dict[str, Any]] = []\\n    try:\\n        from .model_catalog import get_unified_models_detailed\\n\\n        models = get_unified_models_detailed(providers=[provider])\\n        if models and models[0].get(\\\"models\\\"):\\n            provider_models = models[0][\\\"models\\\"]\\n            first_model = provider_models[0][\\\"model_name\\\"]\\n    except Exception as e:  # noqa: BLE001\\n        logger.error(f\\\"Error getting unified models for provider {provider}: {e}\\\")\\n\\n    validation_model = model_name or first_model\\n    validation_metadata = next(\\n        (model.get(\\\"metadata\\\", {}) for model in provider_models if model.get(\\\"model_name\\\") == validation_model),\\n        {},\\n    )\\n    is_reasoning_model = validation_metadata.get(\\\"reasoning\\\", False) is True\\n\\n    # Providers contributed by extension bundles validate through their own\\n    # callable (registered via provider_registry; imported lazily to avoid an\\n    # import cycle). A registered provider that ships no validator falls through\\n    # to a no-op generic pass. The callable raises ValueError on failure, which\\n    # matches this function's contract.\\n    from lfx.base.models.provider_registry import is_registered, validator_for\\n\\n    if is_registered(provider):\\n        bundle_validator = validator_for(provider)\\n        if bundle_validator is not None:\\n            try:\\n                bundle_validator(provider, variables, validation_model)\\n            except ValueError:\\n                raise\\n            except Exception as exc:\\n                # Normalize bundle/transport errors to this function's ValueError contract.\\n                msg = f\\\"Could not validate credentials for {provider}: {exc}\\\"\\n                logger.warning(msg)\\n                raise ValueError(msg) from exc\\n        return\\n\\n    # For providers that need a model to test credentials\\n    if not validation_model and provider in [\\n        \\\"OpenAI\\\",\\n        \\\"Anthropic\\\",\\n        \\\"Google Generative AI\\\",\\n    ]:\\n        return\\n\\n    try:\\n        if provider == \\\"OpenAI\\\":\\n            from langchain_openai import ChatOpenAI  # type: ignore  # noqa: PGH003\\n\\n            api_key = variables.get(\\\"OPENAI_API_KEY\\\")\\n            if not api_key:\\n                return\\n            llm_kwargs = {\\\"api_key\\\": api_key, \\\"model_name\\\": validation_model}\\n            if not is_reasoning_model:\\n                llm_kwargs[\\\"max_tokens\\\"] = 1\\n            base_url = variables.get(\\\"OPENAI_BASE_URL\\\")\\n            if base_url:\\n                from lfx.utils.util import transform_localhost_url\\n\\n                transformed_base_url = transform_localhost_url(base_url)\\n                validate_connector_url_for_ssrf(transformed_base_url)\\n                llm_kwargs[\\\"base_url\\\"] = transformed_base_url\\n            llm = ChatOpenAI(**llm_kwargs)\\n            llm.invoke(\\\"test\\\")\\n\\n        elif provider == \\\"Anthropic\\\":\\n            from langchain_anthropic import ChatAnthropic  # type: ignore  # noqa: PGH003\\n\\n            api_key = variables.get(\\\"ANTHROPIC_API_KEY\\\")\\n            if not api_key:\\n                return\\n            llm = ChatAnthropic(anthropic_api_key=api_key, model=validation_model, max_tokens=1)\\n            llm.invoke(\\\"test\\\")\\n\\n        elif provider == \\\"Google Generative AI\\\":\\n            from langchain_google_genai import ChatGoogleGenerativeAI  # type: ignore  # noqa: PGH003\\n\\n            api_key = variables.get(\\\"GOOGLE_API_KEY\\\")\\n            if not api_key:\\n                return\\n            llm = ChatGoogleGenerativeAI(google_api_key=api_key, model=validation_model, max_tokens=1)\\n            llm.invoke(\\\"test\\\")\\n\\n        elif provider == \\\"IBM WatsonX\\\":\\n            api_key = variables.get(\\\"WATSONX_APIKEY\\\")\\n            project_id = variables.get(\\\"WATSONX_PROJECT_ID\\\")\\n            url = variables.get(\\\"WATSONX_URL\\\") or \\\"https://us-south.ml.cloud.ibm.com\\\"\\n            if not api_key or not project_id:\\n                return\\n            validate_connector_url_for_ssrf(url)\\n\\n            if not validation_model:\\n                from lfx.base.models.model_utils import get_watsonx_llm_models\\n\\n                # Static WatsonX seeds may all be deprecated and filtered out.\\n                # Use a current regional chat model instead of skipping validation.\\n                live_models = get_watsonx_llm_models(url, default_models=[])\\n                if not live_models:\\n                    msg = \\\"No IBM WatsonX chat model is available to validate credentials\\\"\\n                    logger.warning(msg)\\n                    raise ValueError(msg)\\n                validation_model = live_models[0]\\n\\n            from langchain_ibm import ChatWatsonx\\n\\n            llm = ChatWatsonx(\\n                apikey=api_key,\\n                url=url,\\n                model_id=validation_model,\\n                project_id=project_id,\\n                params={\\\"max_new_tokens\\\": 1},\\n            )\\n            llm.invoke(\\\"test\\\")\\n\\n        elif provider == \\\"OpenRouter\\\":\\n            from http import HTTPStatus\\n\\n            import requests\\n\\n            api_key = variables.get(\\\"OPENROUTER_API_KEY\\\")\\n            if not api_key:\\n                return\\n\\n            # ``/api/v1/models`` is a public OpenRouter endpoint (200 for any\\n            # bearer, including missing/invalid). Use ``/api/v1/auth/key``\\n            # instead \u2014 it's documented for key validation, returns 401 on\\n            # invalid keys, and only costs a tiny metadata round-trip.\\n            try:\\n                response = requests.get(\\n                    \\\"https://openrouter.ai/api/v1/auth/key\\\",\\n                    headers={\\\"Authorization\\\": f\\\"Bearer {api_key}\\\"},\\n                    timeout=5,\\n                )\\n                if response.status_code == HTTPStatus.UNAUTHORIZED:\\n                    msg = \\\"Invalid OpenRouter API key\\\"\\n                    logger.error(msg)\\n                    raise ValueError(msg)\\n                response.raise_for_status()\\n            except ValueError:\\n                raise\\n            except requests.RequestException as e:\\n                # Network/timeout/5xx during validation: surface as ValueError so\\n                # the variable API returns a user-facing 400 instead of an\\n                # unhandled 500 (api/v1/variable.py only catches ValueError).\\n                msg = f\\\"Could not reach OpenRouter to validate the API key: {e}\\\"\\n                logger.warning(msg)\\n                raise ValueError(msg) from e\\n\\n        elif provider == \\\"Azure AI Foundry\\\":\\n            try:\\n                from langchain_azure_ai.chat_models import AzureAIOpenAIApiChatModel\\n            except ImportError as e:\\n                msg = (\\n                    \\\"Azure AI Foundry credential validation requires the \\\"\\n                    \\\"'langchain-azure-ai' package, but it is not installed.\\\"\\n                )\\n                raise ValueError(msg) from e\\n\\n            if AzureAIOpenAIApiChatModel is None:\\n                msg = \\\"Azure AI Foundry model support is unavailable.\\\"\\n                raise ValueError(msg)\\n\\n            from lfx.base.models.model_utils import request_azure_ai_foundry_model_entries\\n\\n            api_key = variables.get(\\\"AZURE_AI_FOUNDRY_API_KEY\\\")\\n            endpoint = variables.get(\\\"AZURE_AI_FOUNDRY_ENDPOINT\\\")\\n            api_version = variables.get(\\\"AZURE_AI_FOUNDRY_API_VERSION\\\")\\n            if not api_key or not endpoint:\\n                return\\n            try:\\n                # Validate connection without requiring a seed catalog model name.\\n                request_azure_ai_foundry_model_entries(endpoint, api_key, api_version)\\n            except Exception as e:  # noqa: BLE001 - normalize provider/network failures for the UI\\n                msg = \\\"Could not validate Azure AI Foundry credentials. Check the endpoint, API key, and network.\\\"\\n                logger.warning(f\\\"{msg} Error type: {type(e).__name__}\\\")\\n                raise ValueError(msg) from None\\n\\n        elif provider == \\\"Ollama\\\":\\n            import requests\\n\\n            base_url = variables.get(\\\"OLLAMA_BASE_URL\\\")\\n            if not base_url:\\n                msg = \\\"Invalid Ollama base URL\\\"\\n                logger.error(msg)\\n                raise ValueError(msg)\\n\\n            base_url = base_url.rstrip(\\\"/\\\")\\n            tags_url = f\\\"{base_url}/api/tags\\\"\\n            # OLLAMA_BASE_URL is tenant-controlled: block SSRF to internal/cloud-metadata hosts.\\n            validate_connector_url_for_ssrf(tags_url)\\n            response = requests.get(tags_url, timeout=5, allow_redirects=False)\\n            response.raise_for_status()\\n\\n            data = response.json()\\n            if not isinstance(data, dict) or \\\"models\\\" not in data:\\n                msg = \\\"Invalid Ollama base URL\\\"\\n                logger.error(msg)\\n                raise ValueError(msg)\\n\\n            if model_name:\\n                available_models = [m.get(\\\"name\\\") for m in data[\\\"models\\\"]]\\n                # Exact match or match with :latest\\n                if model_name not in available_models and f\\\"{model_name}:latest\\\" not in available_models:\\n                    # Lenient check for missing tag\\n                    if \\\":\\\" not in model_name:\\n                        if not any(m.startswith(f\\\"{model_name}:\\\") for m in available_models):\\n                            available_str = \\\", \\\".join(available_models[:3])\\n                            msg = f\\\"Model '{model_name}' not found on Ollama server. Available: {available_str}\\\"\\n                            logger.error(msg)\\n                            raise ValueError(msg)\\n                    else:\\n                        available_str = \\\", \\\".join(available_models[:3])\\n                        msg = f\\\"Model '{model_name}' not found on Ollama server. Available: {available_str}\\\"\\n                        logger.error(msg)\\n                        raise ValueError(msg)\\n\\n    except ValueError:\\n        raise\\n    except Exception as e:\\n        if provider == \\\"IBM WatsonX\\\":\\n            msg = f\\\"Could not validate IBM WatsonX credentials: {e}\\\"\\n            logger.warning(msg)\\n            raise ValueError(msg) from e\\n\\n        error_msg = str(e).lower()\\n        if any(word in error_msg for word in [\\\"401\\\", \\\"authentication\\\", \\\"api key\\\"]):\\n            msg = f\\\"Invalid API key for {provider}\\\"\\n            logger.error(f\\\"Invalid API key for {provider}: {e}\\\")\\n            raise ValueError(msg) from e\\n\\n        # Rethrow specific Ollama errors with a user-facing message\\n        if provider == \\\"Ollama\\\":\\n            msg = \\\"Invalid Ollama base URL\\\"\\n            logger.error(msg)\\n            raise ValueError(msg) from e\\n\\n        # For others, log and return (allow saving despite minor errors)\\n        return\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/models/unified_models/instantiation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eceebdab82e7b7f9d32bc1b19dd6605eb69890b1924810f631c26b086e1e8cdc\",\"content\":\"\\\"\\\"\\\"Model instantiation helpers (LLM + embeddings).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nimport os\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.base.embeddings.embeddings_class import EmbeddingsWithModels\\nfrom lfx.base.models.model_utils import _to_str, inject_custom_enabled_models, replace_with_live_models\\nfrom lfx.log.logger import logger\\nfrom lfx.services.variable.request_scope import is_env_fallback_disabled\\nfrom lfx.utils.async_helpers import run_until_complete\\nfrom lfx.utils.ssrf_httpx import (\\n    ssrf_protected_httpx_client_kwargs_for_url,\\n    ssrf_protected_openai_clients_for_url,\\n    validate_url_for_ssrf_or_raise,\\n)\\n\\nfrom .class_registry import EMBEDDING_PARAM_MAPPINGS, EMBEDDING_PROVIDER_CLASS_MAPPING\\nfrom .credentials import _fetch_enabled_providers_for_user, _get_model_status, model_status_contains\\nfrom .model_catalog import get_unified_models_detailed\\nfrom .provider_queries import model_provider_metadata\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from langchain_core.embeddings import Embeddings\\n\\n    from lfx.services.model_provider_policy import ModelProviderPolicySnapshot\\n\\n\\ndef _env_if_allowed(key: str) -> str | None:\\n    \\\"\\\"\\\"Return ``os.environ.get(key)`` unless the active request disables env fallback.\\n\\n    Connection config (provider URLs, project IDs, attribution headers) falls back to\\n    process env only when env fallback is allowed, so a served flow under\\n    ``no_env_fallback`` stays isolated from process-wide environment.\\n    \\\"\\\"\\\"\\n    if is_env_fallback_disabled():\\n        return None\\n    return os.environ.get(key)\\n\\n\\ndef _apply_registered_provider_connection(provider: str, user_id: UUID | str | None, kwargs: dict[str, Any]) -> None:\\n    \\\"\\\"\\\"Apply a bundle-registered provider's non-secret connection variables to ``kwargs``.\\n\\n    Core providers keep their explicit per-provider branches in ``get_llm`` /\\n    ``get_embeddings``; this generic path covers providers contributed via\\n    ``provider_registry``. Each non-secret metadata variable is resolved\\n    (database value, then process env when allowed) and applied to its declared\\n    ``langchain_param`` -- or forwarded as an HTTP header when ``is_header`` is\\n    set, mirroring the OpenRouter attribution-header handling. ``base_url`` is\\n    localhost-rewritten so a Dockerised backend can still reach a host-side\\n    server (e.g. a local vLLM endpoint). API keys / secrets are intentionally\\n    skipped: they are resolved through the dedicated api-key path.\\n    \\\"\\\"\\\"\\n    from lfx.base.models import unified_models as unified_models_module\\n    from lfx.utils.util import transform_localhost_url\\n\\n    provider_meta = model_provider_metadata.get(provider, {})\\n    provider_vars = unified_models_module.get_all_variables_for_provider(user_id, provider)\\n    default_headers: dict[str, str] = {}\\n    for var in provider_meta.get(\\\"variables\\\", []):\\n        if var.get(\\\"is_secret\\\"):\\n            continue\\n        variable_key = var.get(\\\"variable_key\\\")\\n        value = provider_vars.get(variable_key) or _env_if_allowed(variable_key)\\n        if not value:\\n            continue\\n        if var.get(\\\"is_header\\\"):\\n            header_name = var.get(\\\"header_name\\\")\\n            if header_name:\\n                default_headers[header_name] = value\\n            continue\\n        langchain_param = var.get(\\\"langchain_param\\\")\\n        if not langchain_param or kwargs.get(langchain_param):\\n            continue\\n        if langchain_param == \\\"base_url\\\":\\n            value = transform_localhost_url(value)\\n            base_url_suffix = var.get(\\\"base_url_suffix\\\")\\n            if isinstance(base_url_suffix, str) and base_url_suffix:\\n                normalized_suffix = f\\\"/{base_url_suffix.strip('/')}\\\"\\n                value = value.rstrip(\\\"/\\\")\\n                if not value.endswith(normalized_suffix):\\n                    value = f\\\"{value}{normalized_suffix}\\\"\\n        kwargs[langchain_param] = value\\n    if default_headers:\\n        kwargs.setdefault(\\\"default_headers\\\", {}).update(default_headers)\\n\\n\\ndef _protect_model_connection(\\n    kwargs: dict[str, Any],\\n    *,\\n    model_class_name: str,\\n    url_param: str | None,\\n) -> None:\\n    \\\"\\\"\\\"Enforce connector SSRF policy on the final provider endpoint.\\n\\n    OpenAI-compatible and Ollama clients expose HTTP-client hooks, so use the\\n    repository's DNS-pinned transports for those classes. Other provider SDKs\\n    do not expose a compatible transport seam; validate their effective URL\\n    before constructing the SDK client.\\n    \\\"\\\"\\\"\\n    effective_url = _to_str(kwargs.get(url_param)) if url_param else None\\n    if not effective_url:\\n        return\\n\\n    if model_class_name in {\\\"ChatOpenAI\\\", \\\"OpenAIEmbeddings\\\"}:\\n        kwargs.update(ssrf_protected_openai_clients_for_url(effective_url))\\n        return\\n\\n    if model_class_name in {\\\"ChatOllama\\\", \\\"OllamaEmbeddings\\\"}:\\n        sync_client_kwargs, async_client_kwargs = ssrf_protected_httpx_client_kwargs_for_url(effective_url)\\n        if sync_client_kwargs:\\n            kwargs[\\\"sync_client_kwargs\\\"] = sync_client_kwargs\\n        if async_client_kwargs:\\n            kwargs[\\\"async_client_kwargs\\\"] = async_client_kwargs\\n        return\\n\\n    validate_url_for_ssrf_or_raise(effective_url)\\n\\n\\ndef get_llm(\\n    model,\\n    user_id: UUID | str | None,\\n    api_key=None,\\n    temperature=None,\\n    *,\\n    stream=False,\\n    max_tokens=None,\\n    watsonx_url=None,\\n    watsonx_project_id=None,\\n    ollama_base_url=None,\\n    overrides: dict[str, Any] | None = None,\\n    provider_policy: ModelProviderPolicySnapshot | None = None,\\n) -> Any:\\n    # Coerce provider-specific string params (Message/Data may leak through StrInput)\\n    ollama_base_url = _to_str(ollama_base_url)\\n    watsonx_url = _to_str(watsonx_url)\\n    watsonx_project_id = _to_str(watsonx_project_id)\\n\\n    # List-shaped selections carry the provider identity needed for policy\\n    # enforcement. Gate that common runtime path before importing even the\\n    # LangChain base class, provider SDKs, or credential-resolution helpers.\\n    if isinstance(model, list):\\n        if not model:\\n            msg = \\\"A model selection is required\\\"\\n            raise ValueError(msg)\\n        model = model[0]\\n    else:\\n        # Preserve the existing connection-object passthrough. Only this\\n        # identity-free path needs the LangChain base-class import up front.\\n        try:\\n            from langchain_core.language_models import BaseLanguageModel\\n\\n            if isinstance(model, BaseLanguageModel):\\n                return model\\n        except ImportError:\\n            pass\\n        msg = \\\"A model selection is required\\\"\\n        raise ValueError(msg)\\n\\n    # Extract model configuration from metadata\\n    model_name = model.get(\\\"name\\\")\\n    provider = model.get(\\\"provider\\\")\\n    metadata = model.get(\\\"metadata\\\", {})\\n\\n    if not isinstance(provider, str) or not provider.strip():\\n        msg = (\\n            \\\"The selected model is missing a provider. Please reselect a model from the dropdown \\\"\\n            \\\"so the component knows which provider to use.\\\"\\n        )\\n        raise ValueError(msg)\\n    if provider_policy is None:\\n        from lfx.base.models.provider_registry import get_registry_snapshot\\n        from lfx.services.model_provider_policy import ModelProviderPolicyPurpose, resolve_model_provider_policy\\n\\n        provider_policy = resolve_model_provider_policy(\\n            user_id=user_id,\\n            providers=(*get_registry_snapshot().provider_ids, provider),\\n            purpose=ModelProviderPolicyPurpose.USE,\\n        )\\n    provider_policy.require(provider)\\n    if isinstance(model_name, str) and model_name:\\n        provider_policy.require_model(provider, model_name, model_type=\\\"llm\\\")\\n\\n    # Resolve helpers through the package namespace only after policy passes so\\n    # tests can patch lfx.base.models.unified_models.<name> and denied requests\\n    # cannot trigger runtime integration imports.\\n    from lfx.base.models import unified_models as unified_models_module\\n\\n    # Policy is evaluated against the submitted identity, then all runtime\\n    # wiring for a known provider is resolved from its canonical registry\\n    # entry. Stored flow metadata is not authoritative for class or parameter\\n    # names: trusting it would let an allowed provider instantiate a denied\\n    # provider's client. Unknown legacy providers retain the historical\\n    # metadata fallback under the OSS allow-all policy.\\n    from lfx.base.models.provider_registry import provider_name_for_id, resolve_provider_id\\n\\n    provider_id = resolve_provider_id(provider)\\n    canonical_provider = provider_name_for_id(provider_id)\\n    provider_is_known = canonical_provider is not None\\n    provider = canonical_provider or provider\\n\\n    # Stored selections sourced from ``get_unified_models_detailed`` (e.g. the\\n    # ``GET /api/v1/models`` catalog the frontend uses to augment its dropdown\\n    # right after a provider is configured, before the backend repopulates\\n    # ``template[model][\\\"options\\\"]``) carry only the raw ``create_model_metadata``\\n    # fields \u2014 none of the enriched ``*_param`` keys. Derive those param names\\n    # from the provider mapping (the same source ``get_language_model_options``\\n    # uses) so provider-specific names are honored instead of the generic\\n    # ``model`` / ``api_key`` defaults. This matters for IBM WatsonX: passing a\\n    # foundation-model id under the generic ``model`` kwarg routes ChatWatsonx to\\n    # the Model Gateway (a different, OpenAI-style catalog), surfacing as\\n    # \\\"model <id> not found\\\" / IAM \\\"Provided user not found or active\\\" even\\n    # though the dropdown, connection test, and standalone component all work.\\n    from lfx.base.models.model_metadata import get_provider_param_mapping\\n\\n    provider_param_mapping = get_provider_param_mapping(provider)\\n\\n    # Get model class and parameter names from metadata\\n    api_key_param = (\\n        provider_param_mapping.get(\\\"api_key_param\\\", \\\"api_key\\\")\\n        if provider_is_known\\n        else metadata.get(\\\"api_key_param\\\") or \\\"api_key\\\"\\n    )\\n\\n    # Capture the user-supplied api_key BEFORE resolution so we can name\\n    # it back in the error message if it was a Global Variable reference\\n    # the resolver couldn't find \u2014 see PR-12575 Bug 2.\\n    original_api_key_input = api_key.strip() if isinstance(api_key, str) else None\\n\\n    # Get API key from user input or global variables\\n    api_key = unified_models_module.get_api_key_for_provider(user_id, provider, api_key)\\n\\n    # Validate API key. Ollama needs none; extension-bundle providers that\\n    # declare api_key_required=False (e.g. local OpenAI-compatible servers such\\n    # as vLLM) also opt out via provider_registry.\\n    from lfx.base.models.provider_registry import is_api_key_optional, is_registered\\n\\n    if not api_key and provider != \\\"Ollama\\\" and not is_api_key_optional(provider):\\n        # Bug 2 [P1] \u2014 Defensive guard: provider arriving as empty / None /\\n        # literal \\\"Unknown\\\" produces a nonsense error message (the worst\\n        # case being ``Unknown API key is required when using Unknown\\n        # provider \u2026 configure it globally as UNKNOWN_API_KEY``). The root\\n        # cause is the frontend ``ModelInputComponent`` falling back to\\n        # ``provider: \\\"Unknown\\\"`` when an option has no provider \u2014 but\\n        # regardless of how the bad value arrived, surfacing the literal\\n        # placeholder gives the user zero hint about what to do. Replace it\\n        # with a message that points back to the actionable fix: reselect\\n        # the model in the dropdown.\\n        if not provider or provider == \\\"Unknown\\\":\\n            msg = (\\n                \\\"The selected model is missing a provider. \\\"\\n                \\\"Please reselect a model from the dropdown in the Language Model field \\\"\\n                \\\"so the component knows which provider's API key to use.\\\"\\n            )\\n            raise ValueError(msg)\\n\\n        # Get the correct variable name from the provider variable mapping\\n        provider_variable_map = unified_models_module.get_model_provider_variable_mapping()\\n        variable_name = provider_variable_map.get(provider, f\\\"{provider.upper().replace(' ', '_')}_API_KEY\\\")\\n        # Bug 2 [P1] \u2014 when the user (or the assistant) passed a Global\\n        # Variable name as ``api_key`` that the resolver couldn't find,\\n        # name it back so the user can fix the actual reference instead\\n        # of being pointed at the canonical key (which may not be what\\n        # they configured).\\n        if original_api_key_input and original_api_key_input != variable_name:\\n            msg = (\\n                f\\\"{provider} API key is required when using {provider} provider. \\\"\\n                f\\\"The variable '{original_api_key_input}' referenced by the component's \\\"\\n                f\\\"`api_key` field could not be resolved from environment variables or \\\"\\n                f\\\"Global Variables. Configure '{original_api_key_input}' (or the canonical \\\"\\n                f\\\"'{variable_name}') in Settings \u2192 Model Providers.\\\"\\n            )\\n        else:\\n            msg = (\\n                f\\\"{provider} API key is required when using {provider} provider. \\\"\\n                f\\\"Please provide it in the component or configure it globally as {variable_name}.\\\"\\n            )\\n        raise ValueError(msg)\\n\\n    # OpenAI-compatible servers that opt out of API keys (api_key_required=False)\\n    # still need a non-empty placeholder so the client library constructs, e.g.\\n    # a local vLLM endpoint without auth.\\n    if not api_key and is_api_key_optional(provider):\\n        api_key = \\\"EMPTY\\\"  # pragma: allowlist secret\\n\\n    # Get model class from metadata, falling back to the provider-level\\n    # mapping when the stored model value was sourced from\\n    # ``get_unified_models_detailed`` (which, unlike\\n    # ``get_language_model_options``, does not inject ``model_class`` into\\n    # each model's metadata).  This happens for example immediately after a\\n    # user configures a provider and the frontend augments its dropdown from\\n    # ``/api/v1/models`` before the backend has repopulated\\n    # ``template[model][\\\"options\\\"]``; the resulting stored selection only\\n    # carries the raw ``create_model_metadata`` fields, so we have to derive\\n    # ``model_class`` from the provider mapping that\\n    # ``get_language_model_options`` would have used.\\n    model_class_name = (\\n        provider_param_mapping.get(\\\"model_class\\\")\\n        if provider_is_known\\n        else metadata.get(\\\"model_class\\\") or provider_param_mapping.get(\\\"model_class\\\")\\n    )\\n    if not model_class_name:\\n        msg = f\\\"No model class defined for {model_name}\\\"\\n        raise ValueError(msg)\\n    model_class = unified_models_module.get_model_class(model_class_name)\\n    # The provider mapping stores the model-name param under ``model_param``\\n    # (``get_language_model_options`` re-keys it to ``model_name_param``); fall\\n    # back to it so e.g. IBM WatsonX resolves to ``model_id`` rather than the\\n    # generic ``model``.\\n    model_name_param = (\\n        provider_param_mapping.get(\\\"model_param\\\", \\\"model\\\")\\n        if provider_is_known\\n        else metadata.get(\\\"model_name_param\\\") or provider_param_mapping.get(\\\"model_param\\\", \\\"model\\\")\\n    )\\n\\n    # Reasoning models commonly reject sampling parameters such as\\n    # ``temperature``. Catalog metadata marks these with ``reasoning: True``;\\n    # enriched UI options also carry ``reasoning_models``. Keep the user's\\n    # explicit token cap, though: provider clients either accept the configured\\n    # ``max_tokens_field_name`` directly or normalize it to the provider's wire\\n    # format (for example, ChatOpenAI maps ``max_tokens`` to\\n    # ``max_completion_tokens`` for reasoning models).\\n    reasoning_models = metadata.get(\\\"reasoning_models\\\", [])\\n    is_reasoning_model = metadata.get(\\\"reasoning\\\", False) is True or model_name in reasoning_models\\n    if is_reasoning_model:\\n        temperature = None\\n\\n    # Build kwargs dynamically\\n    kwargs = {\\n        model_name_param: model_name,\\n        \\\"streaming\\\": stream,\\n        api_key_param: api_key,\\n    }\\n\\n    if temperature is not None:\\n        kwargs[\\\"temperature\\\"] = temperature\\n\\n    # Add max_tokens with provider-specific field name (only when a valid integer >= 1)\\n    if max_tokens is not None and max_tokens != \\\"\\\":\\n        try:\\n            max_tokens_int = int(max_tokens)\\n            if max_tokens_int >= 1:\\n                # Look up provider-specific field name from model metadata first,\\n                # then fall back to provider metadata, then default to \\\"max_tokens\\\"\\n                provider_meta = model_provider_metadata.get(provider, {})\\n                max_tokens_param = (\\n                    provider_meta.get(\\\"max_tokens_field_name\\\", \\\"max_tokens\\\")\\n                    if provider_is_known\\n                    else metadata.get(\\\"max_tokens_field_name\\\")\\n                    or provider_meta.get(\\\"max_tokens_field_name\\\", \\\"max_tokens\\\")\\n                )\\n                kwargs[max_tokens_param] = max_tokens_int\\n        except (TypeError, ValueError):\\n            pass  # Skip invalid max_tokens (e.g. empty string from form input)\\n\\n    # Enable streaming usage for providers that support it\\n    if provider in [\\\"OpenAI\\\", \\\"Anthropic\\\"]:\\n        kwargs[\\\"stream_usage\\\"] = True\\n\\n    # Add provider-specific parameters\\n    connection_url_param: str | None = None\\n    if provider in {\\\"IBM WatsonX\\\", \\\"IBM watsonx.ai\\\"}:\\n        # For watsonx, url and project_id are required parameters\\n        # Try database first, then component values, then environment variables\\n        url_param = (\\n            provider_param_mapping.get(\\\"url_param\\\", \\\"url\\\")\\n            if provider_is_known\\n            else metadata.get(\\\"url_param\\\") or provider_param_mapping.get(\\\"url_param\\\", \\\"url\\\")\\n        )\\n        project_id_param = (\\n            provider_param_mapping.get(\\\"project_id_param\\\", \\\"project_id\\\")\\n            if provider_is_known\\n            else metadata.get(\\\"project_id_param\\\") or provider_param_mapping.get(\\\"project_id_param\\\", \\\"project_id\\\")\\n        )\\n\\n        # Get all provider variables from database\\n        provider_vars = unified_models_module.get_all_variables_for_provider(user_id, provider)\\n\\n        # Priority: component value > database value > env var\\n        watsonx_url_value = (\\n            watsonx_url if watsonx_url else provider_vars.get(\\\"WATSONX_URL\\\") or _env_if_allowed(\\\"WATSONX_URL\\\")\\n        )\\n        watsonx_project_id_value = (\\n            watsonx_project_id\\n            if watsonx_project_id\\n            else provider_vars.get(\\\"WATSONX_PROJECT_ID\\\") or _env_if_allowed(\\\"WATSONX_PROJECT_ID\\\")\\n        )\\n\\n        has_url = bool(watsonx_url_value)\\n        has_project_id = bool(watsonx_project_id_value)\\n\\n        if has_url and has_project_id:\\n            # Both provided - add them to kwargs\\n            kwargs[url_param] = watsonx_url_value\\n            kwargs[project_id_param] = watsonx_project_id_value\\n            connection_url_param = url_param\\n        elif has_url or has_project_id:\\n            # Only one provided - this is a misconfiguration\\n            missing = \\\"project ID (WATSONX_PROJECT_ID)\\\" if has_url else \\\"URL (WATSONX_URL)\\\"\\n            provided = \\\"URL\\\" if has_url else \\\"project ID\\\"\\n            msg = (\\n                f\\\"IBM WatsonX requires both a URL and project ID. \\\"\\n                f\\\"You provided a watsonx {provided} but no {missing}. \\\"\\n                f\\\"Please configure the missing value in the component or set the environment variable.\\\"\\n            )\\n            raise ValueError(msg)\\n        # else: neither provided - let ChatWatsonx handle it (will fail with its own error)\\n    elif provider == \\\"Ollama\\\":\\n        # For Ollama, handle custom base_url with database > component > env var fallback\\n        base_url_param = (\\n            provider_param_mapping.get(\\\"base_url_param\\\", \\\"base_url\\\")\\n            if provider_is_known\\n            else metadata.get(\\\"base_url_param\\\", \\\"base_url\\\")\\n        )\\n\\n        # Get all provider variables from database\\n        provider_vars = unified_models_module.get_all_variables_for_provider(user_id, provider)\\n\\n        # Priority: component value > database value > env var > default fallback (localhost)\\n        ollama_base_url_value = (\\n            ollama_base_url\\n            if ollama_base_url\\n            else provider_vars.get(\\\"OLLAMA_BASE_URL\\\") or _env_if_allowed(\\\"OLLAMA_BASE_URL\\\") or \\\"http://localhost:11434\\\"\\n        )\\n        if ollama_base_url_value:\\n            kwargs[base_url_param] = ollama_base_url_value\\n            connection_url_param = base_url_param\\n    elif provider == \\\"OpenAI\\\":\\n        from lfx.utils.util import transform_localhost_url\\n\\n        provider_vars = unified_models_module.get_all_variables_for_provider(user_id, provider)\\n        openai_base_url_value = provider_vars.get(\\\"OPENAI_BASE_URL\\\") or _env_if_allowed(\\\"OPENAI_BASE_URL\\\")\\n        if openai_base_url_value:\\n            kwargs[\\\"base_url\\\"] = transform_localhost_url(openai_base_url_value)\\n            connection_url_param = \\\"base_url\\\"\\n    elif provider == \\\"OpenRouter\\\":\\n        # OpenRouter speaks the OpenAI wire format. Point ChatOpenAI at the\\n        # OpenRouter base URL (declared in MODEL_PROVIDER_METADATA) and forward\\n        # any configured attribution headers (HTTP-Referer, X-Title) so usage\\n        # shows up correctly in the OpenRouter dashboard.\\n        provider_meta = model_provider_metadata.get(provider, {})\\n        base_url_value = provider_meta.get(\\\"base_url\\\")\\n        if base_url_value:\\n            kwargs[\\\"base_url\\\"] = base_url_value\\n\\n        provider_vars = unified_models_module.get_all_variables_for_provider(user_id, provider)\\n        default_headers: dict[str, str] = {}\\n        for var in provider_meta.get(\\\"variables\\\", []):\\n            if not var.get(\\\"is_header\\\"):\\n                continue\\n            header_name = var.get(\\\"header_name\\\")\\n            # KeyError on a misconfigured metadata entry beats silently\\n            # skipping a header the operator expects to be sent.\\n            variable_key = var[\\\"variable_key\\\"]\\n            value = provider_vars.get(variable_key) or _env_if_allowed(variable_key)\\n            if header_name and value:\\n                default_headers[header_name] = value\\n        if default_headers:\\n            kwargs[\\\"default_headers\\\"] = default_headers\\n    elif provider == \\\"Azure AI Foundry\\\":\\n        from lfx.base.models.model_utils import AZURE_AI_FOUNDRY_REQUEST_TIMEOUT, normalize_azure_ai_foundry_endpoint\\n\\n        provider_vars = unified_models_module.get_all_variables_for_provider(user_id, provider)\\n        endpoint_value = provider_vars.get(\\\"AZURE_AI_FOUNDRY_ENDPOINT\\\") or _env_if_allowed(\\\"AZURE_AI_FOUNDRY_ENDPOINT\\\")\\n        if not endpoint_value:\\n            msg = (\\n                \\\"Azure AI Foundry endpoint is required. Configure AZURE_AI_FOUNDRY_ENDPOINT \\\"\\n                \\\"in Settings \u2192 Model Providers or set the environment variable.\\\"\\n            )\\n            raise ValueError(msg)\\n        kwargs[\\\"endpoint\\\"] = normalize_azure_ai_foundry_endpoint(endpoint_value)\\n        connection_url_param = \\\"endpoint\\\"\\n        # Bound hung/blackholed endpoints the same way live discovery does.\\n        kwargs[\\\"request_timeout\\\"] = AZURE_AI_FOUNDRY_REQUEST_TIMEOUT\\n    elif is_registered(provider):\\n        # Bundle-contributed provider: apply its declared connection variables\\n        # (base_url, attribution headers, etc.) generically from its metadata.\\n        _apply_registered_provider_connection(provider, user_id, kwargs)\\n        if kwargs.get(\\\"base_url\\\"):\\n            connection_url_param = \\\"base_url\\\"\\n\\n    # Apply overrides discovered from a prior failed call to this model (cache)\\n    # plus any the caller passed for this attempt (error-driven remediation).\\n    from lfx.base.models.model_remediation import cached_overrides\\n\\n    remediation_overrides = cached_overrides(provider, model_name)\\n    kwargs.update(remediation_overrides)\\n    if overrides:\\n        kwargs.update(overrides)\\n    if model_class_name in {\\\"ChatOpenAI\\\", \\\"ChatOllama\\\"} and (\\n        \\\"base_url\\\" in remediation_overrides or (overrides and \\\"base_url\\\" in overrides)\\n    ):\\n        connection_url_param = \\\"base_url\\\"\\n\\n    _protect_model_connection(\\n        kwargs,\\n        model_class_name=model_class_name,\\n        url_param=connection_url_param,\\n    )\\n\\n    try:\\n        return model_class(**kwargs)\\n    except Exception as e:\\n        # If instantiation fails and it's WatsonX, provide additional context\\n        if provider in {\\\"IBM WatsonX\\\", \\\"IBM watsonx.ai\\\"} and (\\\"url\\\" in str(e).lower() or \\\"project\\\" in str(e).lower()):\\n            msg = (\\n                f\\\"Failed to initialize IBM WatsonX model: {e}\\\\n\\\\n\\\"\\n                \\\"IBM WatsonX requires additional configuration parameters (API endpoint URL and project ID). \\\"\\n                \\\"This component may not support these parameters. \\\"\\n                \\\"Consider using the 'Language Model' component instead, which fully supports IBM WatsonX.\\\"\\n            )\\n            raise ValueError(msg) from e\\n        # Re-raise the original exception for other cases\\n        raise\\n\\n\\ndef _get_provider_catalog_models(\\n    provider: str,\\n    user_id: UUID | str | None,\\n) -> list[dict[str, Any]]:\\n    \\\"\\\"\\\"Return catalog model entries for a provider (LLM + embedding, not type-filtered).\\\"\\\"\\\"\\n    provider_models = get_unified_models_detailed(\\n        providers=[provider],\\n        include_deprecated=False,\\n        include_unsupported=False,\\n    )\\n\\n    explicitly_enabled_models: set[str] = set()\\n    if user_id:\\n        with contextlib.suppress(Exception):\\n            enabled_providers = run_until_complete(_fetch_enabled_providers_for_user(user_id))\\n            if provider in enabled_providers:\\n                replace_with_live_models(\\n                    provider_models,\\n                    user_id,\\n                    {provider},\\n                    None,\\n                    model_provider_metadata,\\n                )\\n            _, explicitly_enabled_models = run_until_complete(_get_model_status(user_id))\\n\\n    # Include free-text custom deployments absent from the seed catalog.\\n    inject_custom_enabled_models(provider_models, explicitly_enabled_models)\\n\\n    catalog_models: list[dict[str, Any]] = []\\n    for provider_data in provider_models:\\n        if provider_data.get(\\\"provider\\\") != provider:\\n            continue\\n        catalog_models.extend(provider_data.get(\\\"models\\\", []))\\n    return catalog_models\\n\\n\\ndef _get_provider_enabled_model_names(\\n    provider: str,\\n    user_id: UUID | str | None,\\n    model_type: str | None = None,\\n) -> list[str]:\\n    \\\"\\\"\\\"Return model names enabled for a provider in Model Providers settings.\\n\\n    Includes both LLM and embedding models unless *model_type* restricts the\\n    result. When *user_id* is absent, returns all matching non-deprecated\\n    catalog models for the provider.\\n    \\\"\\\"\\\"\\n    catalog_models = _get_provider_catalog_models(provider, user_id)\\n\\n    disabled_models: set[str] = set()\\n    explicitly_enabled_models: set[str] = set()\\n    enabled_providers: set[str] = set()\\n    if user_id:\\n        with contextlib.suppress(Exception):\\n            disabled_models, explicitly_enabled_models = run_until_complete(_get_model_status(user_id))\\n        with contextlib.suppress(Exception):\\n            enabled_providers = run_until_complete(_fetch_enabled_providers_for_user(user_id))\\n\\n    apply_user_prefs = bool(user_id and enabled_providers and provider in enabled_providers)\\n\\n    model_names: list[str] = []\\n    for model_data in catalog_models:\\n        model_name = model_data.get(\\\"model_name\\\")\\n        if not model_name:\\n            continue\\n        metadata = model_data.get(\\\"metadata\\\", {})\\n        row_model_type = metadata.get(\\\"model_type\\\") or \\\"llm\\\"\\n        if model_type is not None and row_model_type != model_type:\\n            continue\\n\\n        if apply_user_prefs:\\n            is_default = metadata.get(\\\"default\\\", False)\\n            if not is_default and not model_status_contains(\\n                explicitly_enabled_models,\\n                provider,\\n                model_name,\\n                model_type=row_model_type,\\n            ):\\n                continue\\n            if model_status_contains(disabled_models, provider, model_name, model_type=row_model_type):\\n                continue\\n\\n        model_names.append(model_name)\\n    return model_names\\n\\n\\ndef _get_configured_embedding_providers(\\n    user_id: UUID | str | None,\\n    selected_provider: str,\\n) -> list[str]:\\n    \\\"\\\"\\\"Return embedding-capable providers configured in Model Providers.\\\"\\\"\\\"\\n    if not user_id:\\n        return [selected_provider]\\n\\n    with contextlib.suppress(Exception):\\n        enabled_providers = run_until_complete(_fetch_enabled_providers_for_user(user_id))\\n        providers = sorted(p for p in enabled_providers if p in EMBEDDING_PROVIDER_CLASS_MAPPING)\\n        if selected_provider not in providers:\\n            providers.insert(0, selected_provider)\\n        return providers\\n\\n    return [selected_provider]\\n\\n\\ndef _get_provider_embedding_model_names(\\n    provider: str,\\n    user_id: UUID | str | None,\\n) -> list[str]:\\n    \\\"\\\"\\\"Return enabled embedding model names for a single provider.\\\"\\\"\\\"\\n    return _get_provider_enabled_model_names(provider, user_id, model_type=\\\"embeddings\\\")\\n\\n\\ndef _compose_embedding_kwargs(\\n    provider: str,\\n    model_name: str,\\n    user_id: UUID | str | None,\\n    unified_models_module: Any,\\n    *,\\n    selected_provider: str,\\n    metadata: dict[str, Any] | None = None,\\n    component_api_key: str | None = None,\\n    api_base: str | None = None,\\n    dimensions: int | None = None,\\n    chunk_size: int | None = None,\\n    request_timeout: float | None = None,\\n    max_retries: int | None = None,\\n    show_progress_bar: bool | None = None,\\n    model_kwargs: dict[str, Any] | None = None,\\n    watsonx_url: str | None = None,\\n    watsonx_project_id: str | None = None,\\n    watsonx_truncate_input_tokens: int | None = None,\\n    watsonx_input_text: bool | None = None,\\n    ollama_base_url: str | None = None,\\n) -> tuple[type, dict[str, Any]] | None:\\n    \\\"\\\"\\\"Build kwargs for a provider/model pair. Returns None when credentials are missing.\\\"\\\"\\\"\\n    from lfx.base.models.provider_registry import (\\n        is_api_key_optional,\\n        is_registered,\\n        provider_name_for_id,\\n        resolve_provider_id,\\n    )\\n\\n    metadata = metadata or {}\\n    provider_id = resolve_provider_id(provider)\\n    canonical_provider = provider_name_for_id(provider_id)\\n    provider_is_known = canonical_provider is not None\\n    provider = canonical_provider or provider\\n    api_key_override = component_api_key if provider == selected_provider else None\\n    api_key = unified_models_module.get_api_key_for_provider(user_id, provider, api_key_override)\\n    if not api_key and provider != \\\"Ollama\\\" and not is_api_key_optional(provider):\\n        return None\\n    if not api_key and is_api_key_optional(provider):\\n        api_key = \\\"EMPTY\\\"  # pragma: allowlist secret\\n\\n    embedding_class_name = (\\n        EMBEDDING_PROVIDER_CLASS_MAPPING.get(provider)\\n        if provider_is_known\\n        else metadata.get(\\\"embedding_class\\\") or EMBEDDING_PROVIDER_CLASS_MAPPING.get(provider)\\n    )\\n    if not embedding_class_name:\\n        return None\\n\\n    param_mapping: dict[str, str] = (\\n        EMBEDDING_PARAM_MAPPINGS.get(provider, {})\\n        if provider_is_known\\n        else metadata.get(\\\"param_mapping\\\") or EMBEDDING_PARAM_MAPPINGS.get(provider, {})\\n    )\\n    if not param_mapping:\\n        return None\\n\\n    embedding_class = unified_models_module.get_embedding_class(embedding_class_name)\\n\\n    # Treat blank MessageTextInput api_base as unset so it cannot wipe provider endpoints.\\n    api_base_value = _to_str(api_base) if provider == selected_provider else None\\n    if isinstance(api_base_value, str) and not api_base_value.strip():\\n        api_base_value = None\\n    if provider == \\\"OpenAI\\\" and not api_base_value:\\n        provider_vars = unified_models_module.get_all_variables_for_provider(user_id, provider)\\n        openai_base_url = _to_str(provider_vars.get(\\\"OPENAI_BASE_URL\\\")) or _to_str(_env_if_allowed(\\\"OPENAI_BASE_URL\\\"))\\n        if openai_base_url:\\n            from lfx.utils.util import transform_localhost_url\\n\\n            api_base_value = transform_localhost_url(openai_base_url)\\n        else:\\n            api_base_value = _to_str(_env_if_allowed(\\\"OPENAI_EMBEDDINGS_API_BASE\\\")) or _to_str(\\n                _env_if_allowed(\\\"OPENAI_API_BASE\\\")\\n            )\\n\\n    kwargs: dict[str, Any] = {}\\n    connection_url_param: str | None = None\\n    if provider == \\\"OpenAI Compatible\\\" and embedding_class_name == \\\"OpenAIEmbeddings\\\":\\n        # Non-OpenAI servers expect strings and commonly reject the token-ID\\n        # arrays produced by LangChain's client-side context-length handling.\\n        kwargs[\\\"check_embedding_ctx_length\\\"] = False\\n    if \\\"model\\\" in param_mapping:\\n        kwargs[param_mapping[\\\"model\\\"]] = model_name\\n    elif \\\"model_id\\\" in param_mapping:\\n        kwargs[param_mapping[\\\"model_id\\\"]] = model_name\\n\\n    if \\\"api_key\\\" in param_mapping and api_key:\\n        kwargs[param_mapping[\\\"api_key\\\"]] = api_key\\n    elif is_registered(provider) and api_key:\\n        # Bundle providers may omit an explicit \\\"api_key\\\" slot in their embedding\\n        # param_mapping; pass the resolved key (or the api-key-optional\\n        # placeholder) under the OpenAI-compatible \\\"api_key\\\" kwarg so the client\\n        # still authenticates.\\n        kwargs.setdefault(\\\"api_key\\\", api_key)\\n\\n    use_component_overrides = provider == selected_provider\\n    optional_params: dict[str, Any] = {\\n        \\\"api_base\\\": api_base_value if use_component_overrides else None,\\n        \\\"dimensions\\\": dimensions if use_component_overrides else None,\\n        \\\"chunk_size\\\": chunk_size if use_component_overrides else None,\\n        \\\"request_timeout\\\": request_timeout if use_component_overrides else None,\\n        \\\"max_retries\\\": max_retries if use_component_overrides else None,\\n        \\\"show_progress_bar\\\": show_progress_bar if use_component_overrides else None,\\n        \\\"model_kwargs\\\": model_kwargs if use_component_overrides else None,\\n    }\\n\\n    if provider in {\\\"IBM WatsonX\\\", \\\"IBM watsonx.ai\\\"}:\\n        watsonx_provider_vars = unified_models_module.get_all_variables_for_provider(user_id, provider)\\n        url_value = (\\n            (watsonx_url if use_component_overrides else None)\\n            or watsonx_provider_vars.get(\\\"WATSONX_URL\\\")\\n            or _env_if_allowed(\\\"WATSONX_URL\\\")\\n        )\\n        pid_value = (\\n            (watsonx_project_id if use_component_overrides else None)\\n            or watsonx_provider_vars.get(\\\"WATSONX_PROJECT_ID\\\")\\n            or _env_if_allowed(\\\"WATSONX_PROJECT_ID\\\")\\n        )\\n        has_url = bool(url_value)\\n        has_project_id = bool(pid_value)\\n\\n        if has_url and has_project_id:\\n            if \\\"url\\\" in param_mapping:\\n                connection_url_param = param_mapping[\\\"url\\\"]\\n                kwargs[connection_url_param] = url_value\\n            if \\\"project_id\\\" in param_mapping:\\n                kwargs[param_mapping[\\\"project_id\\\"]] = pid_value\\n        elif has_url or has_project_id:\\n            if use_component_overrides:\\n                missing = \\\"project ID (WATSONX_PROJECT_ID)\\\" if has_url else \\\"URL (WATSONX_URL)\\\"\\n                provided = \\\"URL\\\" if has_url else \\\"project ID\\\"\\n                msg = (\\n                    f\\\"IBM WatsonX requires both a URL and project ID. \\\"\\n                    f\\\"You provided a watsonx {provided} but no {missing}. \\\"\\n                    f\\\"Please configure the missing value in the component or set the environment variable.\\\"\\n                )\\n                raise ValueError(msg)\\n            return None\\n\\n        if use_component_overrides:\\n            watsonx_params = {}\\n            if watsonx_truncate_input_tokens is not None:\\n                try:\\n                    from ibm_watsonx_ai.metanames import EmbedTextParamsMetaNames\\n\\n                    watsonx_params[EmbedTextParamsMetaNames.TRUNCATE_INPUT_TOKENS] = int(watsonx_truncate_input_tokens)\\n                except ImportError:\\n                    watsonx_params[\\\"truncate_input_tokens\\\"] = int(watsonx_truncate_input_tokens)\\n            if watsonx_input_text is not None:\\n                try:\\n                    from ibm_watsonx_ai.metanames import EmbedTextParamsMetaNames\\n\\n                    watsonx_params[EmbedTextParamsMetaNames.RETURN_OPTIONS] = {\\\"input_text\\\": bool(watsonx_input_text)}\\n                except ImportError:\\n                    watsonx_params[\\\"return_options\\\"] = {\\\"input_text\\\": bool(watsonx_input_text)}\\n            if watsonx_params:\\n                kwargs[\\\"params\\\"] = watsonx_params\\n\\n    if provider == \\\"Ollama\\\" and \\\"base_url\\\" in param_mapping:\\n        provider_vars = unified_models_module.get_all_variables_for_provider(user_id, provider)\\n        base_url_value = (\\n            (ollama_base_url if use_component_overrides else None)\\n            or provider_vars.get(\\\"OLLAMA_BASE_URL\\\")\\n            or _env_if_allowed(\\\"OLLAMA_BASE_URL\\\")\\n            or \\\"http://localhost:11434\\\"\\n        )\\n        connection_url_param = param_mapping[\\\"base_url\\\"]\\n        kwargs[connection_url_param] = base_url_value\\n\\n    # Bundle-contributed provider: apply its declared connection variables\\n    # (e.g. an OpenAI-compatible base_url) generically from its metadata. Runs\\n    # before the optional-params loop so an explicit api_base still wins.\\n    if is_registered(provider):\\n        _apply_registered_provider_connection(provider, user_id, kwargs)\\n        if kwargs.get(\\\"base_url\\\"):\\n            connection_url_param = \\\"base_url\\\"\\n\\n    for param_name, param_value in optional_params.items():\\n        if param_value is None:\\n            continue\\n        # Skip blank api_base so it does not clobber a provider-resolved base URL.\\n        if param_name == \\\"api_base\\\" and isinstance(param_value, str) and not param_value.strip():\\n            continue\\n        if (\\n            param_name == \\\"request_timeout\\\"\\n            and provider == \\\"Google Generative AI\\\"\\n            and isinstance(param_value, (int, float))\\n        ):\\n            kwargs[param_mapping[param_name]] = {\\\"timeout\\\": param_value}\\n        elif param_name in param_mapping:\\n            kwargs[param_mapping[param_name]] = param_value\\n            if param_name == \\\"api_base\\\":\\n                connection_url_param = param_mapping[param_name]\\n\\n    # Apply Foundry endpoint last so a blank component api_base cannot wipe it.\\n    if provider == \\\"Azure AI Foundry\\\" and \\\"api_base\\\" in param_mapping:\\n        from lfx.base.models.model_utils import normalize_azure_ai_foundry_endpoint\\n\\n        foundry_vars = unified_models_module.get_all_variables_for_provider(user_id, provider)\\n        endpoint_value = (\\n            api_base_value\\n            or _to_str(foundry_vars.get(\\\"AZURE_AI_FOUNDRY_ENDPOINT\\\"))\\n            or _to_str(_env_if_allowed(\\\"AZURE_AI_FOUNDRY_ENDPOINT\\\"))\\n        )\\n        if not endpoint_value:\\n            if use_component_overrides:\\n                msg = (\\n                    \\\"Azure AI Foundry endpoint is required. Configure AZURE_AI_FOUNDRY_ENDPOINT \\\"\\n                    \\\"in Settings \u2192 Model Providers or set the environment variable.\\\"\\n                )\\n                raise ValueError(msg)\\n            return None\\n        connection_url_param = param_mapping[\\\"api_base\\\"]\\n        kwargs[connection_url_param] = normalize_azure_ai_foundry_endpoint(endpoint_value)\\n\\n    _protect_model_connection(\\n        kwargs,\\n        model_class_name=embedding_class_name,\\n        url_param=connection_url_param,\\n    )\\n\\n    return embedding_class, kwargs\\n\\n\\ndef _build_available_embedding_models(\\n    *,\\n    selected_provider: str,\\n    primary_model_name: str,\\n    primary_instance: Embeddings,\\n    user_id: UUID | str | None,\\n    unified_models_module: Any,\\n    metadata: dict[str, Any],\\n    component_api_key: str | None,\\n    api_base: str | None,\\n    dimensions: int | None,\\n    chunk_size: int | None,\\n    request_timeout: float | None,\\n    max_retries: int | None,\\n    show_progress_bar: bool | None,\\n    model_kwargs: dict[str, Any] | None,\\n    watsonx_url: str | None,\\n    watsonx_project_id: str | None,\\n    watsonx_truncate_input_tokens: int | None,\\n    watsonx_input_text: bool | None,\\n    ollama_base_url: str | None,\\n    provider_policy: ModelProviderPolicySnapshot,\\n) -> dict[str, Embeddings]:\\n    \\\"\\\"\\\"Build embedding instances for every enabled embedding model on configured providers.\\\"\\\"\\\"\\n    available_models: dict[str, Embeddings] = {primary_model_name: primary_instance}\\n\\n    for provider in _get_configured_embedding_providers(user_id, selected_provider):\\n        if not provider_policy.allows(provider):\\n            continue\\n        provider_metadata = metadata if provider == selected_provider else {}\\n        for model_name in _get_provider_embedding_model_names(provider, user_id):\\n            if model_name in available_models:\\n                continue\\n            if not provider_policy.allows_model(provider, model_name, model_type=\\\"embeddings\\\"):\\n                continue\\n\\n            composed = _compose_embedding_kwargs(\\n                provider,\\n                model_name,\\n                user_id,\\n                unified_models_module,\\n                selected_provider=selected_provider,\\n                metadata=provider_metadata,\\n                component_api_key=component_api_key,\\n                api_base=api_base,\\n                dimensions=dimensions,\\n                chunk_size=chunk_size,\\n                request_timeout=request_timeout,\\n                max_retries=max_retries,\\n                show_progress_bar=show_progress_bar,\\n                model_kwargs=model_kwargs,\\n                watsonx_url=watsonx_url,\\n                watsonx_project_id=watsonx_project_id,\\n                watsonx_truncate_input_tokens=watsonx_truncate_input_tokens,\\n                watsonx_input_text=watsonx_input_text,\\n                ollama_base_url=ollama_base_url,\\n            )\\n            if composed is None:\\n                continue\\n\\n            embedding_class, model_kwargs_dict = composed\\n            try:\\n                available_models[model_name] = embedding_class(**model_kwargs_dict)\\n            except Exception:  # noqa: BLE001\\n                logger.debug(\\n                    \\\"Failed to instantiate embedding model %s for provider %s; skipping\\\",\\n                    model_name,\\n                    provider,\\n                    exc_info=True,\\n                )\\n\\n    return available_models\\n\\n\\ndef get_embeddings(\\n    model,\\n    user_id: UUID | str | None = None,\\n    api_key=None,\\n    *,\\n    api_base=None,\\n    dimensions=None,\\n    chunk_size=None,\\n    request_timeout=None,\\n    max_retries=None,\\n    show_progress_bar=None,\\n    model_kwargs=None,\\n    watsonx_url=None,\\n    watsonx_project_id=None,\\n    watsonx_truncate_input_tokens=None,\\n    watsonx_input_text=None,\\n    ollama_base_url=None,\\n    provider_policy: ModelProviderPolicySnapshot | None = None,\\n) -> Any:\\n    \\\"\\\"\\\"Instantiate an embeddings model from a model selection dict.\\n\\n    Returns an :class:`~lfx.base.embeddings.embeddings_class.EmbeddingsWithModels`\\n    wrapper containing the primary instance for the selected model and an\\n    ``available_models`` map of enabled embedding models from every configured provider.\\n    \\\"\\\"\\\"\\n    # Coerce provider-specific string params\\n    ollama_base_url = _to_str(ollama_base_url)\\n    watsonx_url = _to_str(watsonx_url)\\n    watsonx_project_id = _to_str(watsonx_project_id)\\n\\n    # Gate list-shaped selections before importing a LangChain base class,\\n    # provider SDK, or credential-resolution helper.\\n    if isinstance(model, list):\\n        if not model:\\n            msg = \\\"An embedding model selection is required\\\"\\n            raise ValueError(msg)\\n        model_dict = model[0]\\n    else:\\n        # Preserve passthrough for already-instantiated connection objects.\\n        try:\\n            from langchain_core.embeddings import Embeddings as BaseEmbeddings\\n\\n            if isinstance(model, BaseEmbeddings):\\n                return model\\n        except ImportError:\\n            pass\\n        msg = \\\"An embedding model selection is required\\\"\\n        raise ValueError(msg)\\n\\n    model_name = model_dict.get(\\\"name\\\")\\n    provider = model_dict.get(\\\"provider\\\")\\n    metadata = model_dict.get(\\\"metadata\\\", {})\\n\\n    if not isinstance(provider, str) or not provider.strip():\\n        msg = \\\"The selected embedding model is missing a provider\\\"\\n        raise ValueError(msg)\\n    if provider_policy is None:\\n        from lfx.base.models.provider_registry import get_registry_snapshot\\n        from lfx.services.model_provider_policy import ModelProviderPolicyPurpose, resolve_model_provider_policy\\n\\n        provider_policy = resolve_model_provider_policy(\\n            user_id=user_id,\\n            providers=(*get_registry_snapshot().provider_ids, provider),\\n            purpose=ModelProviderPolicyPurpose.USE,\\n        )\\n    provider_policy.require(provider)\\n    if isinstance(model_name, str) and model_name:\\n        provider_policy.require_model(provider, model_name, model_type=\\\"embeddings\\\")\\n\\n    # Resolve helpers through the patchable package namespace only after the\\n    # provider has been authorized for runtime use.\\n    from lfx.base.models import unified_models as unified_models_module\\n    from lfx.base.models.provider_registry import provider_name_for_id, resolve_provider_id\\n\\n    provider_id = resolve_provider_id(provider)\\n    canonical_provider = provider_name_for_id(provider_id)\\n    provider_is_known = canonical_provider is not None\\n    provider = canonical_provider or provider\\n\\n    # --- resolve API key for the selected provider ---------------------------\\n    api_key = unified_models_module.get_api_key_for_provider(user_id, provider, api_key)\\n    from lfx.base.models.provider_registry import is_api_key_optional\\n\\n    if not api_key and provider != \\\"Ollama\\\" and not is_api_key_optional(provider):\\n        provider_variable_map = unified_models_module.get_model_provider_variable_mapping()\\n        variable_name = provider_variable_map.get(provider, f\\\"{provider.upper().replace(' ', '_')}_API_KEY\\\")\\n        msg = (\\n            f\\\"{provider} API key is required. \\\"\\n            f\\\"Please provide it in the component or configure it globally as {variable_name}.\\\"\\n        )\\n        raise ValueError(msg)\\n\\n    # OpenAI-compatible embedding servers that opt out of API keys still need a\\n    # non-empty placeholder so the client library constructs (e.g. local vLLM).\\n    if not api_key and is_api_key_optional(provider):\\n        api_key = \\\"EMPTY\\\"  # pragma: allowlist secret\\n\\n    if not model_name:\\n        msg = \\\"Embedding model name is required\\\"\\n        raise ValueError(msg)\\n\\n    composed = _compose_embedding_kwargs(\\n        provider,\\n        model_name,\\n        user_id,\\n        unified_models_module,\\n        selected_provider=provider,\\n        metadata=metadata,\\n        component_api_key=api_key,\\n        api_base=_to_str(api_base),\\n        dimensions=int(dimensions) if dimensions else None,\\n        chunk_size=int(chunk_size) if chunk_size else None,\\n        request_timeout=float(request_timeout) if request_timeout else None,\\n        max_retries=int(max_retries) if max_retries else None,\\n        show_progress_bar=show_progress_bar,\\n        model_kwargs=model_kwargs if model_kwargs else None,\\n        watsonx_url=watsonx_url,\\n        watsonx_project_id=watsonx_project_id,\\n        watsonx_truncate_input_tokens=watsonx_truncate_input_tokens,\\n        watsonx_input_text=watsonx_input_text,\\n        ollama_base_url=ollama_base_url,\\n    )\\n    if composed is None:\\n        embedding_class_name = (\\n            EMBEDDING_PROVIDER_CLASS_MAPPING.get(provider)\\n            if provider_is_known\\n            else metadata.get(\\\"embedding_class\\\") or EMBEDDING_PROVIDER_CLASS_MAPPING.get(provider)\\n        )\\n        if not embedding_class_name:\\n            msg = (\\n                f\\\"No embedding class defined in metadata for {model_name} (provider: {provider}). \\\"\\n                \\\"Add the provider to EMBEDDING_PROVIDER_CLASS_MAPPING or re-select the model.\\\"\\n            )\\n            raise ValueError(msg)\\n        unified_models_module.get_embedding_class(embedding_class_name)\\n        param_mapping = (\\n            EMBEDDING_PARAM_MAPPINGS.get(provider, {})\\n            if provider_is_known\\n            else metadata.get(\\\"param_mapping\\\") or EMBEDDING_PARAM_MAPPINGS.get(provider, {})\\n        )\\n        if not param_mapping:\\n            msg = (\\n                f\\\"Parameter mapping not found in metadata for model '{model_name}' (provider: {provider}). \\\"\\n                \\\"This usually means the model was saved with an older format that is no longer recognized. \\\"\\n                \\\"Please re-select the embedding model in the component configuration.\\\"\\n            )\\n            raise ValueError(msg)\\n        msg = f\\\"{provider} API key is required.\\\"\\n        raise ValueError(msg)\\n\\n    embedding_class, kwargs = composed\\n\\n    try:\\n        primary_instance = embedding_class(**kwargs)\\n    except Exception as e:\\n        if provider == \\\"IBM WatsonX\\\" and (\\\"url\\\" in str(e).lower() or \\\"project\\\" in str(e).lower()):\\n            msg = (\\n                f\\\"Failed to initialize IBM WatsonX embedding model: {e}\\\\n\\\\n\\\"\\n                \\\"IBM WatsonX requires additional configuration parameters (API endpoint URL and project ID).\\\"\\n            )\\n            raise ValueError(msg) from e\\n        raise\\n\\n    available_models = _build_available_embedding_models(\\n        selected_provider=provider,\\n        primary_model_name=model_name,\\n        primary_instance=primary_instance,\\n        user_id=user_id,\\n        unified_models_module=unified_models_module,\\n        metadata=metadata,\\n        component_api_key=api_key,\\n        api_base=_to_str(api_base),\\n        dimensions=int(dimensions) if dimensions else None,\\n        chunk_size=int(chunk_size) if chunk_size else None,\\n        request_timeout=float(request_timeout) if request_timeout else None,\\n        max_retries=int(max_retries) if max_retries else None,\\n        show_progress_bar=show_progress_bar,\\n        model_kwargs=model_kwargs if model_kwargs else None,\\n        watsonx_url=watsonx_url,\\n        watsonx_project_id=watsonx_project_id,\\n        watsonx_truncate_input_tokens=watsonx_truncate_input_tokens,\\n        watsonx_input_text=watsonx_input_text,\\n        ollama_base_url=ollama_base_url,\\n        provider_policy=provider_policy,\\n    )\\n\\n    return EmbeddingsWithModels(\\n        embeddings=primary_instance,\\n        available_models=available_models,\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/models/unified_models/model_catalog.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f5a54179e59b007ad49837fa728654977e21b2be1b1f17bf2e6c3cc9b993e5f1\",\"content\":\"\\\"\\\"\\\"Unified model catalog filtering and UI option construction.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.base.models.model_metadata import EXPLICIT_ENABLE_ONLY_PROVIDERS, get_provider_param_mapping\\nfrom lfx.base.models.model_utils import apply_metadata_filters, inject_custom_enabled_models, replace_with_live_models\\nfrom lfx.utils.async_helpers import run_until_complete\\n\\nfrom .class_registry import EMBEDDING_PARAM_MAPPINGS, EMBEDDING_PROVIDER_CLASS_MAPPING\\nfrom .credentials import _fetch_enabled_providers_for_user, _get_model_status, model_status_contains\\nfrom .provider_queries import get_model_providers, get_models_detailed, model_provider_metadata\\n\\nif TYPE_CHECKING:\\n    from uuid import UUID\\n\\n    from lfx.services.model_provider_policy import ModelProviderPolicySnapshot\\n\\n\\ndef get_unified_models_detailed(\\n    providers: list[str] | None = None,\\n    model_name: str | None = None,\\n    model_type: str | None = None,\\n    *,\\n    include_unsupported: bool | None = None,\\n    include_deprecated: bool | None = None,\\n    only_defaults: bool = False,\\n    **metadata_filters,\\n):\\n    \\\"\\\"\\\"Return a list of providers and their models, optionally filtered.\\n\\n    Parameters\\n    ----------\\n    providers : list[str] | None\\n        If given, only models from these providers are returned.\\n    model_name : str | None\\n        If given, only the model with this exact name is returned.\\n    model_type : str | None\\n        Optional. Restrict to models whose metadata \\\"model_type\\\" matches this value.\\n    include_unsupported : bool\\n        When False (default) models whose metadata contains ``not_supported=True``\\n        are filtered out.\\n    include_deprecated : bool\\n        When False (default) models whose metadata contains ``deprecated=True``\\n        are filtered out.\\n    only_defaults : bool\\n        When True, only models marked as default are returned.\\n        The first 5 models from each provider (in list order) are automatically\\n        marked as default. Defaults to False to maintain backward compatibility.\\n    **metadata_filters\\n        Arbitrary key/value pairs to match against the model's metadata.\\n        Example: ``get_unified_models_detailed(size=\\\"4k\\\", context_window=8192)``\\n    \\\"\\\"\\\"\\n    if include_unsupported is None:\\n        include_unsupported = False\\n    if include_deprecated is None:\\n        include_deprecated = False\\n\\n    # Gather all models from the active catalog (static lists + any\\n    # models.dev override that may have been installed at startup).\\n    all_models: list[dict] = []\\n    for models_detailed in get_models_detailed():\\n        all_models.extend(models_detailed)\\n\\n    # Apply filters\\n    filtered_models: list[dict] = []\\n    for md in all_models:\\n        # Skip models flagged as not_supported unless explicitly included\\n        if (not include_unsupported) and md.get(\\\"not_supported\\\", False):\\n            continue\\n\\n        # Skip models flagged as deprecated unless explicitly included\\n        if (not include_deprecated) and md.get(\\\"deprecated\\\", False):\\n            continue\\n\\n        if providers and md.get(\\\"provider\\\") not in providers:\\n            continue\\n        if model_name and md.get(\\\"name\\\") != model_name:\\n            continue\\n        if model_type and md.get(\\\"model_type\\\") != model_type:\\n            continue\\n        # Match arbitrary metadata key/value pairs\\n        if any(md.get(k) != v for k, v in metadata_filters.items()):\\n            continue\\n\\n        filtered_models.append(md)\\n\\n    # Group by provider\\n    provider_map: dict[str, list[dict]] = {}\\n    for metadata in filtered_models:\\n        prov = metadata.get(\\\"provider\\\", \\\"Unknown\\\")\\n        provider_map.setdefault(prov, []).append(\\n            {\\n                \\\"model_name\\\": metadata.get(\\\"name\\\"),\\n                \\\"metadata\\\": {k: v for k, v in metadata.items() if k not in (\\\"provider\\\", \\\"name\\\")},\\n            }\\n        )\\n\\n    # Sort each provider's list so the picker presents newest-supported first,\\n    # deprecated drops to the bottom, and providers with no date data preserve\\n    # their hand-curated constants-file order (stable sort + tuple ties).\\n    #\\n    # Sort key: (is_deprecated, -created_epoch). When ``created`` is unknown\\n    # (== 0) every row in the same deprecation tier ties on the second\\n    # component, so list.sort's stable behavior keeps the original order\\n    # intact. Defaults are stamped AFTER sorting so the first-N selection\\n    # reflects the new ordering instead of the raw constants order.\\n    default_model_count = 5  # Number of default models per provider\\n\\n    def _sort_key(model: dict) -> tuple[int, int]:\\n        meta = model.get(\\\"metadata\\\", {})\\n        is_deprecated = 1 if meta.get(\\\"deprecated\\\") else 0\\n        created = meta.get(\\\"created\\\") or 0\\n        try:\\n            created_int = int(created)\\n        except (TypeError, ValueError):\\n            created_int = 0\\n        return (is_deprecated, -created_int)\\n\\n    for prov, models in provider_map.items():\\n        models.sort(key=_sort_key)\\n        for i, model in enumerate(models):\\n            model[\\\"metadata\\\"][\\\"default\\\"] = i < default_model_count\\n\\n        # If only_defaults is True, filter to only default models\\n        if only_defaults:\\n            provider_map[prov] = [m for m in models if m[\\\"metadata\\\"].get(\\\"default\\\", False)]\\n\\n    # Format as requested\\n    return [\\n        {\\n            **model_provider_metadata.get(prov, {}),\\n            \\\"provider\\\": prov,\\n            \\\"models\\\": models,\\n            \\\"num_models\\\": len(models),\\n        }\\n        for prov, models in provider_map.items()\\n    ]\\n\\n\\ndef get_language_model_options(\\n    user_id: UUID | str | None = None,\\n    *,\\n    tool_calling: bool | None = None,\\n    filters: dict[str, Any] | None = None,\\n    provider_policy: ModelProviderPolicySnapshot | None = None,\\n) -> list[dict[str, Any]]:\\n    \\\"\\\"\\\"Return available language model providers with their configuration.\\n\\n    ``filters`` is a dict of metadata key/value constraints forwarded to\\n    ``get_unified_models_detailed`` (e.g. ``{\\\"tool_calling\\\": True}``,\\n    ``{\\\"reasoning\\\": True}``). It is the declarative path used by\\n    ``ModelInput(filters=...)``. The legacy ``tool_calling`` kwarg is kept\\n    for back-compat and merged into ``filters`` when present.\\n    \\\"\\\"\\\"\\n    # Get all LLM models (excluding embeddings, deprecated, and unsupported by default)\\n    metadata_filters: dict[str, Any] = dict(filters or {})\\n    if tool_calling is not None:\\n        metadata_filters.setdefault(\\\"tool_calling\\\", tool_calling)\\n\\n    all_models = get_unified_models_detailed(\\n        model_type=\\\"llm\\\",\\n        include_deprecated=False,\\n        include_unsupported=False,\\n        **metadata_filters,\\n    )\\n\\n    if provider_policy is None:\\n        from lfx.services.model_provider_policy import ModelProviderPolicyPurpose, resolve_model_provider_policy\\n\\n        provider_policy = resolve_model_provider_policy(\\n            user_id=user_id,\\n            providers=get_model_providers(),\\n            purpose=ModelProviderPolicyPurpose.USE,\\n        )\\n    all_models = [provider_data for provider_data in all_models if provider_policy.allows(provider_data[\\\"provider\\\"])]\\n\\n    # Get disabled and explicitly enabled models for this user if user_id is provided\\n    disabled_models: set[str] = set()\\n    explicitly_enabled_models: set[str] = set()\\n    if user_id:\\n        with contextlib.suppress(Exception):\\n            disabled_models, explicitly_enabled_models = run_until_complete(_get_model_status(user_id))\\n\\n    # Get enabled providers (those with credentials configured and validated)\\n    enabled_providers = set()\\n    if user_id:\\n        with contextlib.suppress(Exception):\\n            enabled_providers = run_until_complete(\\n                _fetch_enabled_providers_for_user(user_id, provider_policy=provider_policy)\\n            )\\n    enabled_providers = {provider for provider in enabled_providers if provider_policy.allows(provider)}\\n\\n    # Replace static defaults with actual available models from configured instances\\n    suppressed: dict[str, set[tuple[str, str]]] = {}\\n    if enabled_providers:\\n        replace_with_live_models(all_models, user_id, enabled_providers, \\\"llm\\\", model_provider_metadata)\\n        # Live rows replace the statically filtered catalog wholesale \u2014 re-apply the\\n        # metadata filters so e.g. the Agent picker can't see no-tool live models.\\n        suppressed = apply_metadata_filters(all_models, metadata_filters)\\n    inject_custom_enabled_models(\\n        all_models,\\n        explicitly_enabled_models,\\n        model_type=\\\"llm\\\",\\n        metadata_filters=metadata_filters or None,\\n        suppressed=suppressed or None,\\n    )\\n    all_models = [provider_data for provider_data in all_models if provider_policy.allows(provider_data[\\\"provider\\\"])]\\n\\n    options = []\\n\\n    # Track which providers have models\\n    providers_with_models = set()\\n\\n    for provider_data in all_models:\\n        provider = provider_data.get(\\\"provider\\\")\\n        if provider not in enabled_providers:\\n            continue\\n        models = provider_data.get(\\\"models\\\", [])\\n        icon = provider_data.get(\\\"icon\\\", \\\"Bot\\\")\\n\\n        # Check if provider is enabled\\n        is_provider_enabled = not user_id or not enabled_providers or provider in enabled_providers\\n\\n        # Track this provider\\n        if is_provider_enabled:\\n            providers_with_models.add(provider)\\n\\n        # Skip provider if user_id is provided and provider is not enabled\\n        if user_id and enabled_providers and provider not in enabled_providers:\\n            continue\\n\\n        for model_data in models:\\n            model_name = model_data.get(\\\"model_name\\\")\\n            metadata = model_data.get(\\\"metadata\\\", {})\\n            is_default = metadata.get(\\\"default\\\", False)\\n            row_model_type = metadata.get(\\\"model_type\\\") or \\\"llm\\\"\\n\\n            # Foundry: only user-enabled deployment names; else defaults or explicit enables.\\n            if provider in EXPLICIT_ENABLE_ONLY_PROVIDERS:\\n                if not model_status_contains(\\n                    explicitly_enabled_models,\\n                    provider,\\n                    model_name,\\n                    model_type=row_model_type,\\n                ):\\n                    continue\\n            elif not is_default and not model_status_contains(\\n                explicitly_enabled_models,\\n                provider,\\n                model_name,\\n                model_type=row_model_type,\\n            ):\\n                continue\\n            if model_status_contains(disabled_models, provider, model_name, model_type=row_model_type):\\n                continue\\n            if not provider_policy.allows_model(provider, model_name, model_type=row_model_type):\\n                continue\\n\\n            # Get parameter mapping for this provider\\n            param_mapping = get_provider_param_mapping(provider)\\n\\n            # Build the option dict\\n            # Get provider-level metadata for max_tokens field name\\n            provider_meta = model_provider_metadata.get(provider, {})\\n            option_metadata = {\\n                \\\"context_length\\\": 128000,  # Default, can be overridden\\n                \\\"model_class\\\": param_mapping.get(\\\"model_class\\\", \\\"ChatOpenAI\\\"),\\n                \\\"model_name_param\\\": param_mapping.get(\\\"model_param\\\", \\\"model\\\"),\\n                \\\"api_key_param\\\": param_mapping.get(\\\"api_key_param\\\", \\\"api_key\\\"),\\n            }\\n            if \\\"max_tokens_field_name\\\" in provider_meta:\\n                option_metadata[\\\"max_tokens_field_name\\\"] = provider_meta[\\\"max_tokens_field_name\\\"]\\n\\n            option = {\\n                \\\"name\\\": model_name,\\n                \\\"icon\\\": icon,\\n                \\\"category\\\": provider,\\n                \\\"provider\\\": provider,\\n                \\\"metadata\\\": option_metadata,\\n            }\\n\\n            # Propagate catalog ``reasoning`` for every provider (not just\\n            # OpenAI) so get_llm can suppress unsupported sampling parameters\\n            # consistently while preserving independently supported token caps.\\n            if metadata.get(\\\"reasoning\\\"):\\n                option[\\\"metadata\\\"][\\\"reasoning\\\"] = True\\n                option[\\\"metadata\\\"][\\\"reasoning_models\\\"] = [model_name]\\n\\n            # Add provider-specific params from mapping\\n            if \\\"base_url_param\\\" in param_mapping:\\n                option[\\\"metadata\\\"][\\\"base_url_param\\\"] = param_mapping[\\\"base_url_param\\\"]\\n            if \\\"url_param\\\" in param_mapping:\\n                option[\\\"metadata\\\"][\\\"url_param\\\"] = param_mapping[\\\"url_param\\\"]\\n            if \\\"project_id_param\\\" in param_mapping:\\n                option[\\\"metadata\\\"][\\\"project_id_param\\\"] = param_mapping[\\\"project_id_param\\\"]\\n\\n            options.append(option)\\n\\n    return options\\n\\n\\ndef get_embedding_model_options(\\n    user_id: UUID | str | None = None,\\n    *,\\n    provider_policy: ModelProviderPolicySnapshot | None = None,\\n) -> list[dict[str, Any]]:\\n    \\\"\\\"\\\"Return available embedding model providers with their configuration.\\\"\\\"\\\"\\n    # Get all embedding models (excluding deprecated and unsupported by default)\\n    all_models = get_unified_models_detailed(\\n        model_type=\\\"embeddings\\\",\\n        include_deprecated=False,\\n        include_unsupported=False,\\n    )\\n\\n    if provider_policy is None:\\n        from lfx.services.model_provider_policy import ModelProviderPolicyPurpose, resolve_model_provider_policy\\n\\n        provider_policy = resolve_model_provider_policy(\\n            user_id=user_id,\\n            providers=get_model_providers(),\\n            purpose=ModelProviderPolicyPurpose.USE,\\n        )\\n    all_models = [provider_data for provider_data in all_models if provider_policy.allows(provider_data[\\\"provider\\\"])]\\n\\n    # Get disabled and explicitly enabled models for this user if user_id is provided\\n    disabled_models: set[str] = set()\\n    explicitly_enabled_models: set[str] = set()\\n    if user_id:\\n        with contextlib.suppress(Exception):\\n            disabled_models, explicitly_enabled_models = run_until_complete(_get_model_status(user_id))\\n\\n    # Get enabled providers (those with credentials configured and validated)\\n    enabled_providers = set()\\n    if user_id:\\n        with contextlib.suppress(Exception):\\n            enabled_providers = run_until_complete(\\n                _fetch_enabled_providers_for_user(user_id, provider_policy=provider_policy)\\n            )\\n    enabled_providers = {provider for provider in enabled_providers if provider_policy.allows(provider)}\\n\\n    # Replace static defaults with actual available models from configured instances\\n    if enabled_providers:\\n        replace_with_live_models(\\n            all_models,\\n            user_id,\\n            enabled_providers,\\n            \\\"embeddings\\\",\\n            model_provider_metadata,\\n        )\\n    inject_custom_enabled_models(all_models, explicitly_enabled_models, model_type=\\\"embeddings\\\")\\n    all_models = [provider_data for provider_data in all_models if provider_policy.allows(provider_data[\\\"provider\\\"])]\\n\\n    options = []\\n\\n    # Provider-specific param mappings live in class_registry alongside\\n    # the embedding-class mapping so the instantiation fallback in\\n    # ``_instantiate_embeddings`` shares one source of truth.\\n    param_mappings = EMBEDDING_PARAM_MAPPINGS\\n\\n    # Track which providers have models\\n    providers_with_models = set()\\n\\n    for provider_data in all_models:\\n        provider = provider_data.get(\\\"provider\\\")\\n        if provider not in enabled_providers:\\n            continue\\n\\n        models = provider_data.get(\\\"models\\\", [])\\n        icon = provider_data.get(\\\"icon\\\", \\\"Bot\\\")\\n\\n        # Check if provider is enabled\\n        is_provider_enabled = not user_id or not enabled_providers or provider in enabled_providers\\n\\n        # Track this provider\\n        if is_provider_enabled:\\n            providers_with_models.add(provider)\\n\\n        # Skip provider if user_id is provided and provider is not enabled\\n        if user_id and enabled_providers and provider not in enabled_providers:\\n            continue\\n\\n        for model_data in models:\\n            model_name = model_data.get(\\\"model_name\\\")\\n            metadata = model_data.get(\\\"metadata\\\", {})\\n            is_default = metadata.get(\\\"default\\\", False)\\n            row_model_type = metadata.get(\\\"model_type\\\") or \\\"embeddings\\\"\\n\\n            # Foundry: require explicit enable; else defaults or explicit enables.\\n            if provider in EXPLICIT_ENABLE_ONLY_PROVIDERS:\\n                if not model_status_contains(\\n                    explicitly_enabled_models,\\n                    provider,\\n                    model_name,\\n                    model_type=row_model_type,\\n                ):\\n                    continue\\n            elif not is_default and not model_status_contains(\\n                explicitly_enabled_models,\\n                provider,\\n                model_name,\\n                model_type=row_model_type,\\n            ):\\n                continue\\n            if model_status_contains(disabled_models, provider, model_name, model_type=row_model_type):\\n                continue\\n            if not provider_policy.allows_model(provider, model_name, model_type=row_model_type):\\n                continue\\n\\n            # Build the option dict\\n            option = {\\n                \\\"name\\\": model_name,\\n                \\\"icon\\\": icon,\\n                \\\"category\\\": provider,\\n                \\\"provider\\\": provider,\\n                \\\"metadata\\\": {\\n                    \\\"embedding_class\\\": EMBEDDING_PROVIDER_CLASS_MAPPING.get(provider, \\\"OpenAIEmbeddings\\\"),\\n                    \\\"param_mapping\\\": param_mappings.get(provider, param_mappings[\\\"OpenAI\\\"]),\\n                    \\\"model_type\\\": \\\"embeddings\\\",  # Mark as embedding model\\n                },\\n            }\\n\\n            options.append(option)\\n\\n    return options\\n\\n\\ndef normalize_model_names_to_dicts(\\n    model_names: list[str] | str,\\n) -> list[dict[str, Any]]:\\n    \\\"\\\"\\\"Convert simple model name(s) to list of dicts format.\\\"\\\"\\\"\\n    # Convert single string to list\\n    if isinstance(model_names, str):\\n        model_names = [model_names]\\n\\n    # Get all available models to look up metadata\\n    try:\\n        all_models = get_unified_models_detailed()\\n    except Exception:  # noqa: BLE001\\n        # If we can't get models, just create basic dicts\\n        return [{\\\"name\\\": name} for name in model_names]\\n\\n    # Build a lookup map of model_name -> full model data with runtime metadata\\n    model_lookup = {}\\n    for provider_data in all_models:\\n        provider = provider_data.get(\\\"provider\\\")\\n        icon = provider_data.get(\\\"icon\\\", \\\"Bot\\\")\\n        for model_data in provider_data.get(\\\"models\\\", []):\\n            model_name = model_data.get(\\\"model_name\\\")\\n            base_metadata = model_data.get(\\\"metadata\\\", {})\\n\\n            # Get parameter mapping for this provider\\n            param_mapping = get_provider_param_mapping(provider)\\n\\n            # Build runtime metadata similar to get_language_model_options\\n            runtime_metadata = {\\n                \\\"context_length\\\": 128000,  # Default\\n                \\\"model_class\\\": param_mapping.get(\\\"model_class\\\", \\\"ChatOpenAI\\\"),\\n                \\\"model_name_param\\\": param_mapping.get(\\\"model_param\\\", \\\"model\\\"),\\n                \\\"api_key_param\\\": param_mapping.get(\\\"api_key_param\\\", \\\"api_key\\\"),\\n            }\\n\\n            # Add max_tokens_field_name from provider metadata\\n            provider_meta = model_provider_metadata.get(provider, {})\\n            if \\\"max_tokens_field_name\\\" in provider_meta:\\n                runtime_metadata[\\\"max_tokens_field_name\\\"] = provider_meta[\\\"max_tokens_field_name\\\"]\\n\\n            if base_metadata.get(\\\"reasoning\\\"):\\n                runtime_metadata[\\\"reasoning_models\\\"] = [model_name]\\n\\n            # Add provider-specific params from mapping\\n            if \\\"base_url_param\\\" in param_mapping:\\n                runtime_metadata[\\\"base_url_param\\\"] = param_mapping[\\\"base_url_param\\\"]\\n            if \\\"url_param\\\" in param_mapping:\\n                runtime_metadata[\\\"url_param\\\"] = param_mapping[\\\"url_param\\\"]\\n            if \\\"project_id_param\\\" in param_mapping:\\n                runtime_metadata[\\\"project_id_param\\\"] = param_mapping[\\\"project_id_param\\\"]\\n\\n            # Merge base metadata with runtime metadata\\n            full_metadata = {**base_metadata, **runtime_metadata}\\n\\n            # Catalog order is the backwards-compatibility precedence for bare\\n            # model names. Keep the first provider when aliases overlap.\\n            model_lookup.setdefault(\\n                model_name,\\n                {\\n                    \\\"name\\\": model_name,\\n                    \\\"icon\\\": icon,\\n                    \\\"category\\\": provider,\\n                    \\\"provider\\\": provider,\\n                    \\\"metadata\\\": full_metadata,\\n                },\\n            )\\n\\n    # Convert string list to dict list\\n    result = []\\n    for name in model_names:\\n        if name in model_lookup:\\n            result.append(model_lookup[name])\\n        else:\\n            # Model not found in registry, create basic entry with minimal required metadata\\n            result.append(\\n                {\\n                    \\\"name\\\": name,\\n                    \\\"provider\\\": \\\"Unknown\\\",\\n                    \\\"metadata\\\": {\\n                        \\\"model_class\\\": \\\"ChatOpenAI\\\",  # Default fallback\\n                        \\\"model_name_param\\\": \\\"model\\\",\\n                        \\\"api_key_param\\\": \\\"api_key\\\",\\n                    },\\n                }\\n            )\\n\\n    return result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/models/unified_models/provider_queries.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9fd36c1dc4245b7ea92ed08da48e9aba16f243eed40652bd9d1bdc42768a093c\",\"content\":\"\\\"\\\"\\\"Provider metadata accessors and static model catalog primitives.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom functools import lru_cache\\n\\nfrom lfx.base.models.anthropic_constants import ANTHROPIC_MODELS_DETAILED\\nfrom lfx.base.models.azure_ai_foundry_constants import AZURE_AI_FOUNDRY_MODELS_DETAILED\\nfrom lfx.base.models.google_generative_ai_constants import (\\n    GOOGLE_GENERATIVE_AI_EMBEDDING_MODELS_DETAILED,\\n    GOOGLE_GENERATIVE_AI_MODELS_DETAILED,\\n)\\nfrom lfx.base.models.model_metadata import (\\n    CONDITIONAL_LIVE_MODEL_PROVIDERS,\\n    LIVE_MODEL_PROVIDERS,\\n    MODEL_PROVIDER_METADATA,\\n)\\nfrom lfx.base.models.ollama_constants import (\\n    OLLAMA_EMBEDDING_MODELS_DETAILED,\\n    OLLAMA_MODELS_DETAILED,\\n)\\nfrom lfx.base.models.openai_constants import (\\n    OPENAI_EMBEDDING_MODELS_DETAILED,\\n    OPENAI_MODELS_DETAILED,\\n)\\nfrom lfx.base.models.openrouter_constants import OPENROUTER_MODELS_DETAILED\\nfrom lfx.base.models.watsonx_constants import WATSONX_MODELS_DETAILED\\n\\n\\n@lru_cache(maxsize=1)\\ndef get_model_provider_metadata() -> dict:\\n    \\\"\\\"\\\"Return the model provider metadata configuration.\\\"\\\"\\\"\\n    return MODEL_PROVIDER_METADATA\\n\\n\\nmodel_provider_metadata = get_model_provider_metadata()\\n\\n\\ndef _canonical_provider_name(provider: str) -> str:\\n    \\\"\\\"\\\"Resolve a provider selector to the metadata table's legacy name key.\\\"\\\"\\\"\\n    from lfx.base.models.provider_registry import provider_name_for_id, resolve_provider_id\\n\\n    try:\\n        provider_id = resolve_provider_id(provider)\\n    except ValueError:\\n        return provider\\n    return provider_name_for_id(provider_id) or provider\\n\\n\\n_STATIC_MODELS_DETAILED: list[list[dict]] = [\\n    ANTHROPIC_MODELS_DETAILED,\\n    OPENAI_MODELS_DETAILED,\\n    OPENAI_EMBEDDING_MODELS_DETAILED,\\n    GOOGLE_GENERATIVE_AI_MODELS_DETAILED,\\n    GOOGLE_GENERATIVE_AI_EMBEDDING_MODELS_DETAILED,\\n    OLLAMA_MODELS_DETAILED,\\n    OLLAMA_EMBEDDING_MODELS_DETAILED,\\n    OPENROUTER_MODELS_DETAILED,\\n    WATSONX_MODELS_DETAILED,\\n    # Last: seed deployment aliases (gpt-4o, gpt-4.1, \u2026) overlap OpenAI rows.\\n    # ``get_provider_for_model_name`` returns the first catalog hit, so keep\\n    # Foundry after established providers for 1.8.x backwards compat.\\n    AZURE_AI_FOUNDRY_MODELS_DETAILED,\\n]\\n\\n\\n@lru_cache(maxsize=1)\\ndef get_models_detailed() -> list[list[dict]]:\\n    \\\"\\\"\\\"Return grouped model metadata, preferring the models.dev override.\\n\\n    When ``lfx.base.models.models_dev_catalog`` has an active snapshot\\n    installed (loaded from disk or fetched from models.dev at startup),\\n    apply its overrides on top of the bundled static lists. Providers the\\n    snapshot doesn't cover keep their bundled rows; live-fetched providers\\n    (Ollama, IBM WatsonX, OpenRouter) keep theirs too because\\n    ``replace_with_live_models`` overrides at read time, downstream of this\\n    function. ``get_models_detailed.cache_clear()`` must be called whenever\\n    a new snapshot is installed.\\n    \\\"\\\"\\\"\\n    # Lazy import to avoid a circular dependency on application startup\\n    # (models_dev_catalog imports from this module transitively via\\n    # invalidate_catalog_cache).\\n    from lfx.base.models.models_dev_catalog import apply_models_dev_overrides, get_active_snapshot\\n\\n    # Provider-only extensions can contribute a static catalog without editing\\n    # this core list. Import lazily to avoid a cycle during registry mutation.\\n    from lfx.base.models.provider_registry import get_registered_model_catalogs\\n\\n    active_catalog = [*_STATIC_MODELS_DETAILED, *get_registered_model_catalogs()]\\n    snapshot = get_active_snapshot()\\n    if snapshot is None:\\n        return active_catalog\\n    return apply_models_dev_overrides(active_catalog, snapshot)\\n\\n\\n# NOTE: ``MODELS_DETAILED`` is a back-compat binding for callers that imported\\n# it before ``get_models_detailed()`` existed. It reflects the **static**\\n# baseline only \u2014 once a models.dev snapshot installs at startup, in-process\\n# consumers must call ``get_models_detailed()`` (which honours the override and\\n# benefits from ``cache_clear()``) to see fresh data.\\nMODELS_DETAILED = _STATIC_MODELS_DETAILED\\n\\n\\ndef get_provider_secret_variable_key(provider: str) -> str | None:\\n    \\\"\\\"\\\"Return the provider's primary secret variable, never connection config.\\n\\n    Required secrets take precedence over optional secrets. Providers with no\\n    declared secret (for example, a local API-key-optional endpoint configured\\n    only by base URL) intentionally return ``None``.\\n    \\\"\\\"\\\"\\n    variables = model_provider_metadata.get(_canonical_provider_name(provider), {}).get(\\\"variables\\\", [])\\n    required_secret = next(\\n        (\\n            variable.get(\\\"variable_key\\\")\\n            for variable in variables\\n            if variable.get(\\\"required\\\") and variable.get(\\\"is_secret\\\")\\n        ),\\n        None,\\n    )\\n    if required_secret is not None:\\n        return required_secret\\n    return next((variable.get(\\\"variable_key\\\") for variable in variables if variable.get(\\\"is_secret\\\")), None)\\n\\n\\ndef is_required_provider_variable(variable_key: str) -> bool:\\n    \\\"\\\"\\\"True when *variable_key* is a required variable of some model provider.\\n\\n    \\\"Required\\\" is the same notion provider enablement uses: a provider counts as\\n    configured once every required variable is present. Optional variables\\n    (``OPENAI_BASE_URL``, ``AZURE_AI_FOUNDRY_API_VERSION``) are opt-in switches\\n    that enablement never consults, so they must stay explicitly configured.\\n    \\\"\\\"\\\"\\n    return any(\\n        variable.get(\\\"required\\\") and variable.get(\\\"variable_key\\\") == variable_key\\n        for meta in model_provider_metadata.values()\\n        for variable in meta.get(\\\"variables\\\", [])\\n    )\\n\\n\\ndef is_known_model_provider(provider: str) -> bool:\\n    \\\"\\\"\\\"True when *provider* names a provider the model catalog recognizes.\\n\\n    Recognition is independent of credentials: a provider configured only by a\\n    base URL (Ollama) declares no secret variable, so a secret lookup returning\\n    ``None`` says nothing about whether the provider exists.\\n\\n    Bundle-registered providers need no separate check \u2014 registration writes the\\n    bundle's metadata into this same table and unregistration removes it \u2014 so a\\n    single canonicalized membership test answers for every selector form (name,\\n    provider id, alias) and for core and bundle providers alike.\\n\\n    Deliberately uncached: bundles register and unregister providers at runtime.\\n    \\\"\\\"\\\"\\n    return _canonical_provider_name(provider) in model_provider_metadata\\n\\n\\n@lru_cache(maxsize=1)\\ndef get_model_provider_variable_mapping() -> dict[str, str]:\\n    \\\"\\\"\\\"Return one primary variable for each provider.\\n\\n    This broad, backward-compatible mapping is used by provider UI and\\n    enablement callers that need a representative variable even when a\\n    provider has no secret. API-key resolution must instead use\\n    :func:`get_provider_secret_variable_key`.\\n    \\\"\\\"\\\"\\n    result = {}\\n    for provider, meta in model_provider_metadata.items():\\n        variables = meta.get(\\\"variables\\\", [])\\n        # Prefer a required secret (the canonical API key), then any optional\\n        # secret. Providers with no secret retain their first connection field\\n        # for backward-compatible UI/enablement behavior; credential resolution\\n        # deliberately uses get_provider_secret_variable_key directly.\\n        chosen = get_provider_secret_variable_key(provider)\\n        if chosen is None and variables:\\n            chosen = variables[0][\\\"variable_key\\\"]\\n        if chosen is not None:\\n            result[provider] = chosen\\n    return result\\n\\n\\ndef get_provider_all_variables(provider: str) -> list[dict]:\\n    \\\"\\\"\\\"Get all variables for a provider.\\\"\\\"\\\"\\n    meta = model_provider_metadata.get(_canonical_provider_name(provider), {})\\n    return meta.get(\\\"variables\\\", [])\\n\\n\\ndef get_provider_required_variable_keys(provider: str) -> list[str]:\\n    \\\"\\\"\\\"Get all required variable keys for a provider.\\\"\\\"\\\"\\n    variables = get_provider_all_variables(provider)\\n    return [v[\\\"variable_key\\\"] for v in variables if v.get(\\\"required\\\")]\\n\\n\\n@lru_cache(maxsize=1)\\ndef _get_all_provider_specific_field_names() -> set[str]:\\n    \\\"\\\"\\\"Return set of all field names used as mapping_field by any provider.\\\"\\\"\\\"\\n    names: set[str] = set()\\n    for meta in model_provider_metadata.values():\\n        for v in meta.get(\\\"variables\\\", []):\\n            mapping = v.get(\\\"component_metadata\\\", {}).get(\\\"mapping_field\\\")\\n            if mapping:\\n                names.add(mapping)\\n    return names\\n\\n\\ndef get_model_providers() -> list[str]:\\n    \\\"\\\"\\\"Return a sorted list of unique provider names.\\n\\n    Unions providers that have a static model catalog (``get_models_detailed``)\\n    with every provider declared in ``MODEL_PROVIDER_METADATA``. The latter\\n    covers providers that ship no static catalog and rely entirely on live\\n    discovery -- including providers contributed by extension bundles via\\n    ``provider_registry`` (which merge their metadata in place).\\n\\n    Stable identity, rather than display text, owns deduplication. This folds\\n    a legacy alias contributed by one catalog surface into the canonical\\n    metadata provider without changing the public display-name response.\\n    \\\"\\\"\\\"\\n    from lfx.base.models.provider_registry import resolve_provider_id\\n\\n    providers_by_id: dict[str, str] = {}\\n    # Metadata is authoritative for the public provider name, so seed it\\n    # before catalog aliases and retain the first spelling for each stable ID.\\n    for provider in model_provider_metadata:\\n        if isinstance(provider, str) and provider.strip():\\n            providers_by_id.setdefault(resolve_provider_id(provider), provider)\\n    for group in get_models_detailed():\\n        for metadata in group:\\n            provider = metadata.get(\\\"provider\\\", \\\"Unknown\\\")\\n            if isinstance(provider, str) and provider.strip():\\n                providers_by_id.setdefault(resolve_provider_id(provider), provider)\\n    return sorted(providers_by_id.values())\\n\\n\\ndef get_live_only_providers() -> list[str]:\\n    \\\"\\\"\\\"Return providers whose models come exclusively from live discovery.\\n\\n    A provider qualifies when it is declared in the provider metadata and in\\n    the live-discovery gates but ships no static catalog rows -- today always\\n    a provider contributed by an extension bundle via ``provider_registry``\\n    (e.g. vLLM, OpenAI Compatible). Catalog-driven listings such as\\n    ``get_unified_models_detailed`` can never emit these, and\\n    ``replace_with_live_models`` only appends a provider once it is configured\\n    *and* its endpoint returns models, so provider-facing surfaces (the Model\\n    Providers dialog) must union them in explicitly or an unconfigured\\n    provider would be undiscoverable.\\n\\n    Metadata-only providers that are *not* live-capable (Azure OpenAI, Groq)\\n    are deliberately excluded: with neither a catalog nor live discovery they\\n    could never list models, and they are intentionally absent from the\\n    unified-model UI today.\\n\\n    Not cached: ``register_provider`` mutates the metadata and live gates in\\n    place, and the underlying collections are small.\\n    \\\"\\\"\\\"\\n    cataloged = {md.get(\\\"provider\\\") for group in get_models_detailed() for md in group}\\n    live_capable = {*LIVE_MODEL_PROVIDERS, *CONDITIONAL_LIVE_MODEL_PROVIDERS}\\n    return sorted(name for name in model_provider_metadata if name in live_capable and name not in cataloged)\\n\\n\\ndef get_provider_for_model_name(model_name: str) -> str:\\n    \\\"\\\"\\\"Return the provider for a model name by searching the active catalog.\\n\\n    Retained for backwards compatibility with components authored against the\\n    pre-refactor ``unified_models`` module (e.g. flows exported from 1.8.x).\\n    \\\"\\\"\\\"\\n    if not model_name or not isinstance(model_name, str):\\n        return \\\"\\\"\\n    for group in get_models_detailed():\\n        for md in group:\\n            if md.get(\\\"name\\\") == model_name:\\n                return md.get(\\\"provider\\\", \\\"\\\") or \\\"\\\"\\n    return \\\"\\\"\\n\\n\\ndef get_provider_from_variable_key(variable_key: str) -> str | None:\\n    \\\"\\\"\\\"Get provider name from a variable key.\\n\\n    Args:\\n        variable_key: The variable key (e.g., \\\"OPENAI_API_KEY\\\", \\\"WATSONX_APIKEY\\\")\\n\\n    Returns:\\n        The provider name or None if not found\\n    \\\"\\\"\\\"\\n    for provider, meta in model_provider_metadata.items():\\n        for var in meta.get(\\\"variables\\\", []):\\n            if var.get(\\\"variable_key\\\") == variable_key:\\n                return provider\\n    return None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/models/watsonx_constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5b460bb36986a5b4b12f79230686ce575dd57a24f06c25e40de79fc64a6c20f5\",\"content\":\"from .model_metadata import create_model_metadata\\n\\n# Pre-credential seed catalog. Once the provider is configured,\\n# ``fetch_live_watsonx_models`` replaces these entries with the live\\n# ``/ml/v1/foundation_model_specs`` listing (which already excludes\\n# withdrawn models), so this list only needs to track the commonly\\n# available watsonx.ai models. ``deprecated=True`` is reserved for models\\n# IBM has withdrawn from the catalog \u2014 kept here so legacy flows that\\n# reference them still resolve; the UI hides them behind the\\n# \\\"Show deprecated\\\" toggle.\\nWATSONX_DEFAULT_LLM_MODELS = [\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"ibm/granite-4-h-small\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"llm\\\",\\n        tool_calling=True,\\n    ),\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"meta-llama/llama-3-3-70b-instruct\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"llm\\\",\\n        tool_calling=True,\\n    ),\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"mistral-large-2512\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"llm\\\",\\n        tool_calling=True,\\n    ),\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"meta-llama/llama-4-maverick-17b-128e-instruct-fp8\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"llm\\\",\\n        tool_calling=True,\\n    ),\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"mistralai/mistral-medium-2505\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"llm\\\",\\n        tool_calling=True,\\n    ),\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"mistralai/mistral-small-3-1-24b-instruct-2503\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"llm\\\",\\n        tool_calling=True,\\n    ),\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"openai/gpt-oss-120b\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"llm\\\",\\n        tool_calling=True,\\n    ),\\n    # Guardian is a safety-classification model; it does not support tools.\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"ibm/granite-guardian-3-8b\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"llm\\\",\\n        tool_calling=False,\\n    ),\\n    # Withdrawn from IBM's chat catalog.\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"ibm/granite-8b-code-instruct\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"llm\\\",\\n        tool_calling=True,\\n        deprecated=True,\\n    ),\\n]\\n\\nWATSONX_DEFAULT_EMBEDDING_MODELS = [\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"ibm/granite-embedding-278m-multilingual\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"embeddings\\\",\\n    ),\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"ibm/slate-125m-english-rtrvr-v2\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"embeddings\\\",\\n    ),\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"ibm/slate-30m-english-rtrvr-v2\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"embeddings\\\",\\n    ),\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"intfloat/multilingual-e5-large\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"embeddings\\\",\\n    ),\\n    # Withdrawn from IBM's embedding catalog.\\n    create_model_metadata(\\n        provider=\\\"IBM WatsonX\\\",\\n        name=\\\"sentence-transformers/all-minilm-l12-v2\\\",\\n        icon=\\\"IBM\\\",\\n        model_type=\\\"embeddings\\\",\\n        deprecated=True,\\n    ),\\n]\\n\\n\\nWATSONX_EMBEDDING_MODELS_DETAILED = WATSONX_DEFAULT_EMBEDDING_MODELS\\n# Combined list for all watsonx models\\nWATSONX_MODELS_DETAILED = WATSONX_DEFAULT_LLM_MODELS + WATSONX_DEFAULT_EMBEDDING_MODELS\\n\\nWATSONX_EMBEDDING_MODEL_NAMES = [metadata[\\\"name\\\"] for metadata in WATSONX_DEFAULT_EMBEDDING_MODELS]\\n\\nIBM_WATSONX_URLS = [\\n    \\\"https://us-south.ml.cloud.ibm.com\\\",\\n    \\\"https://eu-de.ml.cloud.ibm.com\\\",\\n    \\\"https://eu-gb.ml.cloud.ibm.com\\\",\\n    \\\"https://au-syd.ml.cloud.ibm.com\\\",\\n    \\\"https://jp-tok.ml.cloud.ibm.com\\\",\\n    \\\"https://ca-tor.ml.cloud.ibm.com\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/processing/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/prompts/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/prompts/api_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e32203d8af843fe7f42de9245f361c6c7806976a97a701bb79257cfaac7eedf1\",\"content\":\"from collections import defaultdict\\nfrom typing import Any\\n\\nfrom fastapi import HTTPException\\nfrom langchain_core.prompts import PromptTemplate\\nfrom langchain_core.prompts.string import mustache_template_vars\\n\\nfrom lfx.inputs.inputs import DefaultPromptField\\nfrom lfx.interface.utils import extract_input_variables_from_prompt\\nfrom lfx.log.logger import logger\\nfrom lfx.utils.mustache_security import validate_mustache_template\\n\\n_INVALID_CHARACTERS = {\\n    \\\" \\\",\\n    \\\",\\\",\\n    \\\".\\\",\\n    \\\":\\\",\\n    \\\";\\\",\\n    \\\"!\\\",\\n    \\\"?\\\",\\n    \\\"/\\\",\\n    \\\"\\\\\\\\\\\",\\n    \\\"(\\\",\\n    \\\")\\\",\\n    \\\"[\\\",\\n    \\\"]\\\",\\n}\\n\\n_INVALID_NAMES = {\\n    \\\"code\\\",\\n    \\\"input_variables\\\",\\n    \\\"output_parser\\\",\\n    \\\"partial_variables\\\",\\n    \\\"template\\\",\\n    \\\"template_format\\\",\\n    \\\"validate_template\\\",\\n}\\n\\n# Keys prefixed with an underscore are node-template metadata (`_type`,\\n# `_frontend_node_flow_id`, ...), not component fields. The frontend filters them out of\\n# every render path, so a prompt variable landing in that namespace is created in the\\n# template but never gets an input or a handle, and resolves to an empty string at run\\n# time. Reject the name instead, the same way `_INVALID_NAMES` is rejected.\\n# Mirrored in the frontend by `invalidVariableReason`, together with the other three\\n# rejection paths below, so the editor can flag the name while the user is still typing.\\nRESERVED_VARIABLE_PREFIX = \\\"_\\\"\\n\\n\\ndef _is_json_like(var):\\n    if var.startswith(\\\"{{\\\") and var.endswith(\\\"}}\\\"):\\n        # If it is a double brance variable\\n        # we don't want to validate any of its content\\n        return True\\n    # the above doesn't work on all cases because the json string can be multiline\\n    # or indented which can add \\\\n or spaces at the start or end of the string\\n    # test_case_3 new_var == '\\\\n{{\\\\n    \\\"test\\\": \\\"hello\\\",\\\\n    \\\"text\\\": \\\"world\\\"\\\\n}}\\\\n'\\n    # what we can do is to remove the \\\\n and spaces from the start and end of the string\\n    # and then check if the string starts with {{ and ends with }}\\n    var = var.strip()\\n    var = var.replace(\\\"\\\\n\\\", \\\"\\\")\\n    var = var.replace(\\\" \\\", \\\"\\\")\\n    # Now it should be a valid json string\\n    return var.startswith(\\\"{{\\\") and var.endswith(\\\"}}\\\")\\n\\n\\ndef _fix_variable(var, invalid_chars, wrong_variables):\\n    if not var:\\n        return var, invalid_chars, wrong_variables\\n    new_var = var\\n\\n    # Handle variables starting with a number\\n    if var[0].isdigit():\\n        invalid_chars.append(var[0])\\n        new_var, invalid_chars, wrong_variables = _fix_variable(var[1:], invalid_chars, wrong_variables)\\n\\n    # Temporarily replace {{ and }} to avoid treating them as invalid\\n    new_var = new_var.replace(\\\"{{\\\", \\\"\u1d1b\u1d07\u1d0d\u1d18\u1d0f\u1d18\u1d07\u0274\\\").replace(\\\"}}\\\", \\\"\u1d1b\u1d07\u1d0d\u1d18\u1d04\u029f\u1d0fs\u1d07\\\")  # noqa: RUF001\\n\\n    # Remove invalid characters\\n    for char in new_var:\\n        if char in _INVALID_CHARACTERS:\\n            invalid_chars.append(char)\\n            new_var = new_var.replace(char, \\\"\\\")\\n            if var not in wrong_variables:  # Avoid duplicating entries\\n                wrong_variables.append(var)\\n\\n    # Restore {{ and }}\\n    new_var = new_var.replace(\\\"\u1d1b\u1d07\u1d0d\u1d18\u1d0f\u1d18\u1d07\u0274\\\", \\\"{{\\\").replace(\\\"\u1d1b\u1d07\u1d0d\u1d18\u1d04\u029f\u1d0fs\u1d07\\\", \\\"}}\\\")  # noqa: RUF001\\n\\n    return new_var, invalid_chars, wrong_variables\\n\\n\\ndef _check_variable(var, invalid_chars, wrong_variables, empty_variables):\\n    if any(char in invalid_chars for char in var):\\n        wrong_variables.append(var)\\n    elif var == \\\"\\\":\\n        empty_variables.append(var)\\n    return wrong_variables, empty_variables\\n\\n\\ndef _check_for_errors(input_variables, fixed_variables, wrong_variables, empty_variables) -> None:\\n    if any(var for var in input_variables if var not in fixed_variables):\\n        error_message = (\\n            f\\\"Input variables contain invalid characters or formats. \\\\n\\\"\\n            f\\\"Invalid variables: {', '.join(wrong_variables)}.\\\\n\\\"\\n            f\\\"Empty variables: {', '.join(empty_variables)}. \\\\n\\\"\\n            f\\\"Fixed variables: {', '.join(fixed_variables)}.\\\"\\n        )\\n        raise ValueError(error_message)\\n\\n\\ndef _check_input_variables(input_variables):\\n    invalid_chars = []\\n    fixed_variables = []\\n    wrong_variables = []\\n    empty_variables = []\\n    variables_to_check = []\\n\\n    for var in input_variables:\\n        # First, let's check if the variable is a JSON string\\n        # because if it is, it won't be considered a variable\\n        # and we don't need to validate it\\n        if _is_json_like(var):\\n            continue\\n\\n        new_var, wrong_variables, empty_variables = _fix_variable(var, invalid_chars, wrong_variables)\\n        wrong_variables, empty_variables = _check_variable(var, _INVALID_CHARACTERS, wrong_variables, empty_variables)\\n        fixed_variables.append(new_var)\\n        variables_to_check.append(var)\\n\\n    _check_for_errors(variables_to_check, fixed_variables, wrong_variables, empty_variables)\\n\\n    return fixed_variables\\n\\n\\ndef _check_reserved_prefix(input_variables: list[str]) -> None:\\n    \\\"\\\"\\\"Reject variable names that fall into the reserved `_*` template namespace.\\\"\\\"\\\"\\n    reserved = [var for var in input_variables if var.startswith(RESERVED_VARIABLE_PREFIX)]\\n    if reserved:\\n        # Backticks are not decoration: the frontend renders this message through\\n        # react-markdown, where bare underscores pair up into emphasis markers and\\n        # disappear -- \\\"_x\\\" would reach the user as \\\"x\\\".\\n        names = \\\", \\\".join(f\\\"`{var}`\\\" for var in reserved)\\n        msg = (\\n            f\\\"Invalid input variables: {names}. \\\"\\n            f\\\"Variable names cannot start with `{RESERVED_VARIABLE_PREFIX}` because that prefix is \\\"\\n            f\\\"reserved for internal template fields.\\\"\\n        )\\n        raise ValueError(msg)\\n\\n\\ndef validate_prompt(prompt_template: str, *, silent_errors: bool = False, is_mustache: bool = False) -> list[str]:\\n    if is_mustache:\\n        # Validate that template doesn't contain complex mustache syntax\\n        # This must happen before variable extraction to catch patterns like {{#section}}{{/section}}\\n        validate_mustache_template(prompt_template)\\n\\n        # Extract only mustache variables\\n        try:\\n            input_variables = mustache_template_vars(prompt_template)\\n        except Exception as exc:\\n            # Mustache parser errors are often cryptic (e.g., \\\"unclosed tag at line 1\\\")\\n            # Provide a more helpful error message\\n            error_str = str(exc).lower()\\n            if \\\"unclosed\\\" in error_str or \\\"tag\\\" in error_str:\\n                msg = \\\"Invalid template syntax. Check that all {{variables}} have matching opening and closing braces.\\\"\\n            else:\\n                msg = f\\\"Invalid mustache template: {exc}\\\"\\n            raise ValueError(msg) from exc\\n\\n        # Also get f-string variables to filter them out\\n        fstring_vars = extract_input_variables_from_prompt(prompt_template)\\n\\n        # Only keep variables that are actually in mustache syntax (not in f-string syntax)\\n        # This handles cases where template has both {var} and {{var}}\\n        input_variables = [v for v in input_variables if v not in fstring_vars or f\\\"{{{{{v}}}}}\\\" in prompt_template]\\n    else:\\n        # Extract f-string variables\\n        input_variables = extract_input_variables_from_prompt(prompt_template)\\n\\n        # Also get mustache variables to filter them out\\n        mustache_vars = mustache_template_vars(prompt_template)\\n\\n        # Only keep variables that are NOT in mustache syntax\\n        # This handles cases where template has both {var} and {{var}}\\n        input_variables = [v for v in input_variables if v not in mustache_vars]\\n\\n    # Check if there are invalid characters in the input_variables\\n    input_variables = _check_input_variables(input_variables)\\n    _check_reserved_prefix(input_variables)\\n    if any(var in _INVALID_NAMES for var in input_variables):\\n        msg = f\\\"Invalid input variables. None of the variables can be named {', '.join(input_variables)}. \\\"\\n        raise ValueError(msg)\\n\\n    try:\\n        PromptTemplate(template=prompt_template, input_variables=input_variables)\\n    except Exception as exc:\\n        msg = f\\\"Invalid prompt: {exc}\\\"\\n        logger.exception(msg)\\n        if not silent_errors:\\n            raise ValueError(msg) from exc\\n\\n    return input_variables\\n\\n\\ndef get_old_custom_fields(custom_fields, name):\\n    try:\\n        if len(custom_fields) == 1 and name == \\\"\\\":\\n            # If there is only one custom field and the name is empty string\\n            # then we are dealing with the first prompt request after the node was created\\n            name = next(iter(custom_fields.keys()))\\n\\n        old_custom_fields = custom_fields[name]\\n        if not old_custom_fields:\\n            old_custom_fields = []\\n\\n        old_custom_fields = old_custom_fields.copy()\\n    except KeyError:\\n        old_custom_fields = []\\n    custom_fields[name] = []\\n    return old_custom_fields\\n\\n\\ndef add_new_variables_to_template(input_variables, custom_fields, template, name) -> None:\\n    for variable in input_variables:\\n        try:\\n            template_field = DefaultPromptField(name=variable, display_name=variable)\\n            if variable in template:\\n                # Set the new field with the old value\\n                template_field.value = template[variable][\\\"value\\\"]\\n\\n            template[variable] = template_field.to_dict()\\n\\n            # Check if variable is not already in the list before appending\\n            if variable not in custom_fields[name]:\\n                custom_fields[name].append(variable)\\n\\n        except Exception as exc:\\n            raise HTTPException(status_code=500, detail=str(exc)) from exc\\n\\n\\ndef remove_old_variables_from_template(old_custom_fields, input_variables, custom_fields, template, name) -> None:\\n    for variable in old_custom_fields:\\n        if variable not in input_variables:\\n            try:\\n                # Remove the variable from custom_fields associated with the given name\\n                if variable in custom_fields[name]:\\n                    custom_fields[name].remove(variable)\\n\\n                # Remove the variable from the template\\n                template.pop(variable, None)\\n\\n            except Exception as exc:\\n                raise HTTPException(status_code=500, detail=str(exc)) from exc\\n\\n\\ndef update_input_variables_field(input_variables, template) -> None:\\n    if \\\"input_variables\\\" in template:\\n        template[\\\"input_variables\\\"][\\\"value\\\"] = input_variables\\n\\n\\ndef process_prompt_template(\\n    template: str,\\n    name: str,\\n    custom_fields: dict[str, list[str]] | None,\\n    frontend_node_template: dict[str, Any],\\n    *,\\n    is_mustache: bool = False,\\n):\\n    \\\"\\\"\\\"Process and validate prompt template, update template and custom fields.\\\"\\\"\\\"\\n    # Validate the prompt template and extract input variables\\n    input_variables = validate_prompt(template, is_mustache=is_mustache)\\n\\n    # Initialize custom_fields if None\\n    if custom_fields is None:\\n        custom_fields = defaultdict(list)\\n\\n    # Retrieve old custom fields\\n    old_custom_fields = get_old_custom_fields(custom_fields, name)\\n\\n    # Add new variables to the template\\n    add_new_variables_to_template(input_variables, custom_fields, frontend_node_template, name)\\n\\n    # Remove old variables from the template\\n    remove_old_variables_from_template(old_custom_fields, input_variables, custom_fields, frontend_node_template, name)\\n\\n    # Update the input variables field in the template\\n    update_input_variables_field(input_variables, frontend_node_template)\\n\\n    return input_variables\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/prompts/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a1694bc131716132a4925789d3ed256f667caa41126a05e98b4331f0331309b2\",\"content\":\"from copy import deepcopy\\n\\nfrom langchain_core.documents import Document\\n\\nfrom lfx.schema.data import Data\\n\\n\\ndef data_to_string(record: Data) -> str:\\n    \\\"\\\"\\\"Convert a record to a string.\\n\\n    Args:\\n        record (Data): The record to convert.\\n\\n    Returns:\\n        str: The record as a string.\\n    \\\"\\\"\\\"\\n    return record.get_text()\\n\\n\\ndef dict_values_to_string(d: dict) -> dict:\\n    \\\"\\\"\\\"Converts the values of a dictionary to strings.\\n\\n    Args:\\n        d (dict): The dictionary whose values need to be converted.\\n\\n    Returns:\\n        dict: The dictionary with values converted to strings.\\n    \\\"\\\"\\\"\\n    from lfx.schema.message import Message\\n\\n    # Do something similar to the above\\n    d_copy = deepcopy(d)\\n    for key, value in d_copy.items():\\n        # it could be a list of data or documents or strings\\n        if isinstance(value, list):\\n            for i, item in enumerate(value):\\n                if isinstance(item, Message):\\n                    d_copy[key][i] = item.text\\n                elif isinstance(item, Data):\\n                    d_copy[key][i] = data_to_string(item)\\n                elif isinstance(item, Document):\\n                    d_copy[key][i] = document_to_string(item)\\n        elif isinstance(value, Message):\\n            d_copy[key] = value.text\\n        elif isinstance(value, Data):\\n            d_copy[key] = data_to_string(value)\\n        elif isinstance(value, Document):\\n            d_copy[key] = document_to_string(value)\\n    return d_copy\\n\\n\\ndef document_to_string(document: Document) -> str:\\n    \\\"\\\"\\\"Convert a document to a string.\\n\\n    Args:\\n        document (Document): The document to convert.\\n\\n    Returns:\\n        str: The document as a string.\\n    \\\"\\\"\\\"\\n    return document.page_content\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/textsplitters/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/textsplitters/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"52d675be19ec8a4cc6a0a93bbc4f4c4445873ba01236406bf663af8653c348d0\",\"content\":\"from abc import abstractmethod\\n\\nfrom langchain_core.documents import BaseDocumentTransformer\\nfrom langchain_text_splitters import TextSplitter\\n\\nfrom lfx.base.document_transformers.model import LCDocumentTransformerComponent\\n\\n\\nclass LCTextSplitterComponent(LCDocumentTransformerComponent):\\n    trace_type = \\\"text_splitter\\\"\\n\\n    def _validate_outputs(self) -> None:\\n        required_output_methods = [\\\"text_splitter\\\"]\\n        output_names = [output.name for output in self.outputs]\\n        for method_name in required_output_methods:\\n            if method_name not in output_names:\\n                msg = f\\\"Output with name '{method_name}' must be defined.\\\"\\n                raise ValueError(msg)\\n            if not hasattr(self, method_name):\\n                msg = f\\\"Method '{method_name}' must be defined.\\\"\\n                raise ValueError(msg)\\n\\n    def build_document_transformer(self) -> BaseDocumentTransformer:\\n        return self.build_text_splitter()\\n\\n    @abstractmethod\\n    def build_text_splitter(self) -> TextSplitter:\\n        \\\"\\\"\\\"Build the text splitter.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/tools/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/tools/base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"08c609cd832826801e37d5d50d120a2df84764efd630cd3016c447410da89a67\",\"content\":\"from lfx.field_typing import Tool\\n\\n\\ndef build_status_from_tool(tool: Tool):\\n    \\\"\\\"\\\"Builds a status string representation of a tool.\\n\\n    Args:\\n        tool (Tool): The tool object to build the status for.\\n\\n    Returns:\\n        str: The status string representation of the tool, including its name, description, arguments (if any),\\n            and args_schema (if any).\\n    \\\"\\\"\\\"\\n    description_repr = repr(tool.description).strip(\\\"'\\\")\\n    args_str = \\\"\\\\n\\\".join(\\n        [\\n            f\\\"- {arg_name}: {arg_data['description']}\\\"\\n            for arg_name, arg_data in tool.args.items()\\n            if \\\"description\\\" in arg_data\\n        ]\\n    )\\n    # Include args_schema information\\n    args_schema_str = repr(tool.args_schema) if tool.args_schema else \\\"None\\\"\\n    status = f\\\"Name: {tool.name}\\\\nDescription: {description_repr}\\\"\\n    status += f\\\"\\\\nArgs Schema: {args_schema_str}\\\"\\n    return status + (f\\\"\\\\nArguments:\\\\n{args_str}\\\" if args_str else \\\"\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/tools/component_tool.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"72a9f7303f01c6c4ce9e22aacfa55c864c7822d0d5a5ae3fb134635b46de82ea\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nimport re\\nfrom copy import deepcopy\\nfrom typing import TYPE_CHECKING, Any, Literal\\n\\nimport pandas as pd\\n\\n# LangChain resolves these annotations at runtime to inject config and callback managers.\\nfrom langchain_core.callbacks import AsyncCallbackManagerForToolRun, CallbackManagerForToolRun  # noqa: TC002\\nfrom langchain_core.runnables import RunnableConfig  # noqa: TC002\\nfrom langchain_core.tools import BaseTool, ToolException\\nfrom langchain_core.tools.structured import StructuredTool\\nfrom typing_extensions import override\\n\\nfrom lfx.base.tools.constants import TOOL_OUTPUT_NAME\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.message import Message\\nfrom lfx.serialization.serialization import serialize\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Callable\\n\\n    from langchain_core.callbacks import Callbacks\\n\\n    from lfx.custom.custom_component.component import Component\\n    from lfx.events.event_manager import EventManager\\n    from lfx.inputs.inputs import InputTypes\\n    from lfx.io import Output\\n    from lfx.schema.dotdict import dotdict\\n\\nTOOL_TYPES_SET = {\\\"Tool\\\", \\\"BaseTool\\\", \\\"StructuredTool\\\"}\\n\\n\\nclass ComponentStructuredTool(StructuredTool):\\n    \\\"\\\"\\\"StructuredTool that keeps JSON-safe component results as LangChain artifacts.\\\"\\\"\\\"\\n\\n    response_format: Literal[\\\"content_and_artifact\\\"] = \\\"content_and_artifact\\\"\\n\\n    @staticmethod\\n    def _content_and_artifact(content: Any) -> tuple[Any, Any | None]:\\n        artifact = None if isinstance(content, str) else serialize(content)\\n        return content, artifact\\n\\n    @override\\n    def _run(\\n        self,\\n        *args: Any,\\n        config: RunnableConfig,\\n        run_manager: CallbackManagerForToolRun | None = None,\\n        **kwargs: Any,\\n    ) -> tuple[Any, Any | None]:\\n        content = super()._run(*args, config=config, run_manager=run_manager, **kwargs)\\n        return self._content_and_artifact(content)\\n\\n    @override\\n    async def _arun(\\n        self,\\n        *args: Any,\\n        config: RunnableConfig,\\n        run_manager: AsyncCallbackManagerForToolRun | None = None,\\n        **kwargs: Any,\\n    ) -> tuple[Any, Any | None]:\\n        if self.coroutine is None:\\n            # StructuredTool falls back to self._run, which already returns the\\n            # content-and-artifact tuple. Wrapping it again would nest the tuple.\\n            return await super()._arun(*args, config=config, run_manager=run_manager, **kwargs)\\n        content = await super()._arun(*args, config=config, run_manager=run_manager, **kwargs)\\n        return self._content_and_artifact(content)\\n\\n\\ndef _get_input_type(input_: InputTypes):\\n    if input_.input_types:\\n        if len(input_.input_types) == 1:\\n            return input_.input_types[0]\\n        return \\\" | \\\".join(input_.input_types)\\n    return input_.field_type\\n\\n\\ndef build_description(component: Component, output=None) -> str:\\n    \\\"\\\"\\\"Build tool description, preferring output-level info over component description.\\\"\\\"\\\"\\n    if output and getattr(output, \\\"info\\\", None):\\n        return output.info\\n    return component.description or \\\"\\\"\\n\\n\\nasync def send_message_noop(\\n    message: Message,\\n    id_: str | None = None,  # noqa: ARG001\\n    *,\\n    skip_db_update: bool = False,  # noqa: ARG001\\n) -> Message:\\n    \\\"\\\"\\\"No-op implementation of send_message.\\\"\\\"\\\"\\n    return message\\n\\n\\ndef patch_components_send_message(component: Component):\\n    old_send_message = component.send_message\\n    component.send_message = send_message_noop  # type: ignore[method-assign, assignment]\\n    return old_send_message\\n\\n\\ndef _build_output_function(\\n    component: Component,\\n    output_method: Callable,\\n    event_manager: EventManager | None = None,\\n    output_name: str = TOOL_OUTPUT_NAME,\\n):\\n    method_name = output_method.__name__\\n    # Capture tool_mode input names so positional args can be mapped to kwargs\\n    _tool_input_names = [inp.name for inp in component.inputs if getattr(inp, \\\"tool_mode\\\", False)]\\n\\n    def output_function(*args, **kwargs):\\n        # Map positional args to keyword args using tool_mode input names\\n        if args:\\n            for i, val in enumerate(args):\\n                if i < len(_tool_input_names) and _tool_input_names[i] not in kwargs:\\n                    kwargs[_tool_input_names[i]] = val\\n        # Create an isolated copy to prevent race conditions when this\\n        # tool is invoked concurrently by an agent (GitHub issue #8791)\\n        comp = deepcopy(component)\\n        # Nothing patches send_message here. Silencing the shared component leaked across\\n        # overlapping calls: the second call recorded the first call's no-op as the method\\n        # to restore, and restored it once the first call had put the real one back.\\n        # Suppressing the tool run's own messages is a separate change, tracked on its own.\\n        local_method = getattr(comp, method_name, output_method)\\n        build_started = False\\n        result = None\\n        try:\\n            comp._ensure_code_execution_policy()  # noqa: SLF001\\n            if event_manager:\\n                event_manager.on_build_start(data={\\\"id\\\": comp.get_id()})\\n                build_started = True\\n            comp.set_event_manager(event_manager)\\n            comp.set_current_output(output_name)\\n            comp.set(**kwargs)\\n            result = local_method()\\n        except Exception as e:\\n            logger.error(\\n                \\\"Component %s failed during tool mode execution: %s\\\",\\n                comp.get_id(),\\n                e,\\n                exc_info=True,\\n            )\\n            raise ToolException(str(e)) from e\\n        finally:\\n            comp.set_current_output(\\\"\\\")\\n            comp.set_event_manager(None)\\n            if build_started and event_manager:\\n                event_manager.on_build_end(data={\\\"id\\\": comp.get_id()})\\n\\n        if isinstance(result, Message):\\n            return result.get_text()\\n        if isinstance(result, Data):\\n            return result.data\\n        if isinstance(result, pd.DataFrame):\\n            return result\\n        # removing the model_dump() call here because it is not serializable\\n        return serialize(result)\\n\\n    return output_function\\n\\n\\ndef _build_output_async_function(\\n    component: Component,\\n    output_method: Callable,\\n    event_manager: EventManager | None = None,\\n    output_name: str = TOOL_OUTPUT_NAME,\\n):\\n    method_name = output_method.__name__\\n    # Capture tool_mode input names so positional args can be mapped to kwargs\\n    _tool_input_names = [inp.name for inp in component.inputs if getattr(inp, \\\"tool_mode\\\", False)]\\n\\n    async def output_function(*args, **kwargs):\\n        # Map positional args to keyword args using tool_mode input names\\n        if args:\\n            for i, val in enumerate(args):\\n                if i < len(_tool_input_names) and _tool_input_names[i] not in kwargs:\\n                    kwargs[_tool_input_names[i]] = val\\n        # Create an isolated copy to prevent race conditions when this\\n        # tool is invoked concurrently by an agent (GitHub issue #8791)\\n        comp = deepcopy(component)\\n        # See _build_output_function: a tool call must not patch send_message anywhere.\\n        local_method = getattr(comp, method_name, output_method)\\n        build_started = False\\n        result = None\\n        try:\\n            comp._ensure_code_execution_policy()  # noqa: SLF001\\n            if event_manager:\\n                event_manager.on_build_start(data={\\\"id\\\": comp.get_id()})\\n                build_started = True\\n            comp.set_event_manager(event_manager)\\n            comp.set_current_output(output_name)\\n            comp.set(**kwargs)\\n            result = await local_method()\\n        except Exception as e:\\n            logger.error(\\n                \\\"Component %s failed during tool mode execution: %s\\\",\\n                comp.get_id(),\\n                e,\\n                exc_info=True,\\n            )\\n            raise ToolException(str(e)) from e\\n        finally:\\n            comp.set_current_output(\\\"\\\")\\n            comp.set_event_manager(None)\\n            if build_started and event_manager:\\n                event_manager.on_build_end(data={\\\"id\\\": comp.get_id()})\\n        if isinstance(result, Message):\\n            return result.get_text()\\n        if isinstance(result, Data):\\n            return result.data\\n        if isinstance(result, pd.DataFrame):\\n            return result\\n        # removing the model_dump() call here because it is not serializable\\n        return serialize(result)\\n\\n    return output_function\\n\\n\\ndef _format_tool_name(name: str):\\n    # format to '^[a-zA-Z0-9_-]+$'.\\\"\\n    # to do that we must remove all non-alphanumeric characters\\n\\n    return re.sub(r\\\"[^a-zA-Z0-9_-]\\\", \\\"-\\\", name)\\n\\n\\n# Method names that carry no semantic signal about what the tool DOES. When\\n# a single-output component uses one of these, the LLM-facing tool name is\\n# derived from the component class name instead \u2014 the class name is the\\n# user's stated intent (e.g. ``RandomMenuItem``, ``DrinkPrice``) and is\\n# always more informative than ``output``/``process``. Kept narrow on\\n# purpose: descriptive method names (``get_forecast``, ``search_products``)\\n# must NOT be overridden, and multi-output components must NOT be\\n# collapsed to a single name (that would shadow tools).\\n_GENERIC_OUTPUT_METHOD_NAMES = frozenset(\\n    {\\\"output\\\", \\\"process\\\", \\\"build_output\\\", \\\"run\\\", \\\"execute\\\", \\\"main\\\", \\\"handler\\\", \\\"build_result\\\"}\\n)\\n\\n\\ndef _class_name_to_tool_name(class_name: str) -> str:\\n    \\\"\\\"\\\"CamelCase \u2192 snake_case, preserving acronym boundaries.\\n\\n    Examples:\\n        RandomMenuItem  \u2192 random_menu_item\\n        DrinkPrice      \u2192 drink_price\\n        HTTPClient      \u2192 http_client\\n        S3Bucket        \u2192 s3_bucket\\n        MyXMLParser     \u2192 my_xml_parser\\n        Already_snake   \u2192 already_snake (passthrough)\\n    \\\"\\\"\\\"\\n    # Insert underscore between acronym and following CamelCase word\\n    # (\\\"HTTPClient\\\" \u2192 \\\"HTTP_Client\\\", \\\"MyXMLParser\\\" \u2192 \\\"My_XMLParser\\\")\\n    step1 = re.sub(r\\\"([A-Z]+)([A-Z][a-z])\\\", r\\\"\\\\1_\\\\2\\\", class_name)\\n    # Insert underscore between lowercase/digit and uppercase\\n    # (\\\"RandomMenu\\\" \u2192 \\\"Random_Menu\\\", \\\"S3Bucket\\\" \u2192 \\\"S3_Bucket\\\")\\n    step2 = re.sub(r\\\"([a-z0-9])([A-Z])\\\", r\\\"\\\\1_\\\\2\\\", step1)\\n    return step2.lower()\\n\\n\\ndef _derive_tool_name(component: Component, output_method: str, outputs: list[Output]) -> str:\\n    \\\"\\\"\\\"Pick a tool name that an LLM can act on.\\n\\n    Defaults to the output's method name (existing contract). Falls back to\\n    the snake_cased component class name only when:\\n\\n    1. The method name is generic (``output``/``process``/...) \u2014 i.e. it\\n       carries no semantic signal.\\n    2. The component has exactly one tool-exposed output. Multi-output\\n       components keep method-derived names so each tool stays distinct.\\n    \\\"\\\"\\\"\\n    if output_method in _GENERIC_OUTPUT_METHOD_NAMES and len(outputs) == 1:\\n        return _class_name_to_tool_name(type(component).__name__)\\n    return output_method\\n\\n\\ndef _add_commands_to_tool_description(tool_description: str, commands: str):\\n    return f\\\"very_time you see one of those commands {commands} run the tool. tool description is {tool_description}\\\"\\n\\n\\nclass ComponentToolkit:\\n    def __init__(self, component: Component, metadata: pd.DataFrame | None = None):\\n        self.component = component\\n        self.metadata = metadata\\n\\n    def _should_skip_output(self, output: Output) -> bool:\\n        \\\"\\\"\\\"Determines if an output should be skipped when creating tools.\\n\\n        Args:\\n            output (Output): The output to check.\\n\\n        Returns:\\n            bool: True if the output should be skipped, False otherwise.\\n\\n        The output will be skipped if:\\n        - tool_mode is False (the user opted this output out of tool exposure)\\n        - it is the SYNTHETIC output that ``_append_tool_to_outputs_map`` adds\\n          when the component is flipped to tool mode (name + method + types\\n          all match \u2014 those three together uniquely identify the synthetic,\\n          whereas matching on name alone wrongly skipped LLM-generated user\\n          components whose Output happened to be named ``component_as_tool``,\\n          producing an empty tool list \u2014 production failure 2026-05-27).\\n        - the output is already a Tool-typed handoff (anything in\\n          ``TOOL_TYPES_SET``) \u2014 wrapping a Tool in another Tool is a no-op.\\n        \\\"\\\"\\\"\\n        if not output.tool_mode:\\n            return True\\n        # Synthetic-tool sentinel: name + method + types ALL match. Anything\\n        # less is a user-declared output that happens to share the name.\\n        is_synthetic_tool = (\\n            output.name == TOOL_OUTPUT_NAME\\n            and output.method == \\\"to_toolkit\\\"\\n            and any(tool_type in output.types for tool_type in TOOL_TYPES_SET)\\n        )\\n        if is_synthetic_tool:\\n            return True\\n        # Already-a-Tool outputs short-circuit too.\\n        return any(tool_type in output.types for tool_type in TOOL_TYPES_SET)\\n\\n    def get_tools(\\n        self,\\n        tool_name: str | None = None,\\n        tool_description: str | None = None,\\n        callbacks: Callbacks | None = None,\\n        flow_mode_inputs: list[dotdict] | None = None,\\n    ) -> list[BaseTool]:\\n        from lfx.io.schema import create_input_schema, create_input_schema_from_dict\\n\\n        tools = []\\n        # Resolve up front: tool_mode-eligible outputs gate the class-name\\n        # fallback below (only safe for single-output components).\\n        eligible_outputs = [o for o in self.component.outputs if not self._should_skip_output(o)]\\n        for output in eligible_outputs:\\n            if not output.method:\\n                msg = f\\\"Output {output.name} does not have a method defined\\\"\\n                raise ValueError(msg)\\n\\n            output_method: Callable = getattr(self.component, output.method)\\n            args_schema = None\\n            tool_mode_inputs = [_input for _input in self.component.inputs if getattr(_input, \\\"tool_mode\\\", False)]\\n            if flow_mode_inputs:\\n                args_schema = create_input_schema_from_dict(\\n                    inputs=flow_mode_inputs,\\n                    param_key=\\\"flow_tweak_data\\\",\\n                )\\n            elif tool_mode_inputs:\\n                args_schema = create_input_schema(tool_mode_inputs)\\n            elif output.required_inputs:\\n                inputs = [\\n                    self.component.get_underscore_inputs()[input_name]\\n                    for input_name in output.required_inputs\\n                    if getattr(self.component, input_name) is None\\n                ]\\n                # If any of the required inputs are not in tool mode, this means\\n                # that when the tool is called it will raise an error.\\n                # so we should raise an error here.\\n                # TODO: This logic might need to be improved, example if the required is an api key.\\n                if not all(getattr(_input, \\\"tool_mode\\\", False) for _input in inputs):\\n                    non_tool_mode_inputs = [\\n                        input_.name\\n                        for input_ in inputs\\n                        if not getattr(input_, \\\"tool_mode\\\", False) and input_.name is not None\\n                    ]\\n                    non_tool_mode_inputs_str = \\\", \\\".join(non_tool_mode_inputs)\\n                    msg = (\\n                        f\\\"Output '{output.name}' requires inputs that are not in tool mode. \\\"\\n                        f\\\"The following inputs are not in tool mode: {non_tool_mode_inputs_str}. \\\"\\n                        \\\"Please ensure all required inputs are set to tool mode.\\\"\\n                    )\\n                    raise ValueError(msg)\\n                args_schema = create_input_schema(inputs)\\n\\n            else:\\n                args_schema = create_input_schema(self.component.inputs)\\n\\n            name = _derive_tool_name(self.component, f\\\"{output.method}\\\".strip(\\\".\\\"), eligible_outputs)\\n            formatted_name = _format_tool_name(name)\\n            event_manager = self.component.get_event_manager()\\n            if asyncio.iscoroutinefunction(output_method):\\n                tools.append(\\n                    ComponentStructuredTool(\\n                        name=formatted_name,\\n                        description=build_description(self.component, output),\\n                        coroutine=_build_output_async_function(\\n                            self.component, output_method, event_manager, TOOL_OUTPUT_NAME\\n                        ),\\n                        args_schema=args_schema,\\n                        handle_tool_error=True,\\n                        callbacks=callbacks,\\n                        tags=[formatted_name],\\n                        metadata={\\n                            \\\"display_name\\\": formatted_name,\\n                            \\\"display_description\\\": build_description(self.component, output),\\n                        },\\n                    )\\n                )\\n            else:\\n                tools.append(\\n                    ComponentStructuredTool(\\n                        name=formatted_name,\\n                        description=build_description(self.component, output),\\n                        func=_build_output_function(self.component, output_method, event_manager, TOOL_OUTPUT_NAME),\\n                        args_schema=args_schema,\\n                        handle_tool_error=True,\\n                        callbacks=callbacks,\\n                        tags=[formatted_name],\\n                        metadata={\\n                            \\\"display_name\\\": formatted_name,\\n                            \\\"display_description\\\": build_description(self.component, output),\\n                        },\\n                    )\\n                )\\n        if len(tools) == 1 and (tool_name or tool_description):\\n            tool = tools[0]\\n            tool.name = _format_tool_name(str(tool_name)) or tool.name\\n            tool.description = tool_description or tool.description\\n            tool.tags = [tool.name]\\n        elif (tool_name or tool_description) and (flow_mode_inputs or len(tools) > 1):\\n            for tool in tools:\\n                tool.name = _format_tool_name(str(tool_name) + \\\"_\\\" + str(tool.name)) or tool.name\\n                # Only prepend an explicit tool_description. Without one, keep the\\n                # output-derived description so it stays equal to display_description\\n                # and the Actions-panel merge logic can detect real user edits.\\n                if tool_description:\\n                    tool.description = f\\\"{tool_description} Output details: {tool.description}\\\"\\n                tool.tags = [tool.name]\\n        return tools\\n\\n    def get_tools_metadata_dictionary(self) -> dict:\\n        if isinstance(self.metadata, pd.DataFrame):\\n            try:\\n                return {\\n                    record[\\\"tags\\\"][0]: record\\n                    for record in self.metadata.to_dict(orient=\\\"records\\\")\\n                    if record.get(\\\"tags\\\")\\n                }\\n            except (KeyError, IndexError) as e:\\n                msg = \\\"Error processing metadata records: \\\" + str(e)\\n                raise ValueError(msg) from e\\n        return {}\\n\\n    def update_tools_metadata(\\n        self,\\n        tools: list[BaseTool | StructuredTool],\\n    ) -> list[BaseTool]:\\n        # update the tool_name and description according to the name and secriotion mentioned in the list\\n        if isinstance(self.metadata, pd.DataFrame):\\n            metadata_dict = self.get_tools_metadata_dictionary()\\n            filtered_tools = []\\n            for tool in tools:\\n                if isinstance(tool, StructuredTool | BaseTool) and tool.tags:\\n                    try:\\n                        tag = tool.tags[0]\\n                    except IndexError:\\n                        msg = \\\"Tool tags cannot be empty.\\\"\\n                        raise ValueError(msg) from None\\n                    if tag in metadata_dict:\\n                        tool_metadata = metadata_dict[tag]\\n                        # Only include tools with status=True\\n                        if tool_metadata.get(\\\"status\\\", True):\\n                            tool.name = tool_metadata.get(\\\"name\\\", tool.name)\\n                            tool.description = tool_metadata.get(\\\"description\\\", tool.description)\\n                            # Carry the per-action HITL decisions onto the tool so the\\n                            # agent gates exactly what the user selected (LE-1447).\\n                            if tool.metadata is None:\\n                                tool.metadata = {}\\n                            tool.metadata[\\\"approval_actions\\\"] = tool_metadata.get(\\\"approval_actions\\\") or []\\n                            if tool_metadata.get(\\\"commands\\\"):\\n                                tool.description = _add_commands_to_tool_description(\\n                                    tool.description, tool_metadata.get(\\\"commands\\\")\\n                                )\\n                            filtered_tools.append(tool)\\n                else:\\n                    msg = f\\\"Expected a StructuredTool or BaseTool, got {type(tool)}\\\"\\n                    raise TypeError(msg)\\n            return filtered_tools\\n        return tools\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/tools/constants.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"020ba557b3376b11de4ca40e9a5b3ef59d42ee94df87a12bd6a6a1b454b66a6e\",\"content\":\"from lfx.schema.table import EditMode\\n\\nTOOL_OUTPUT_NAME = \\\"component_as_tool\\\"\\nTOOL_OUTPUT_DISPLAY_NAME = \\\"Toolset\\\"\\nTOOLS_METADATA_INPUT_NAME = \\\"tools_metadata\\\"\\nTOOL_TABLE_SCHEMA = [\\n    {\\n        \\\"name\\\": \\\"name\\\",\\n        \\\"display_name\\\": \\\"Tool Name\\\",\\n        \\\"type\\\": \\\"str\\\",\\n        \\\"description\\\": \\\"Specify the name of the tool.\\\",\\n        \\\"sortable\\\": False,\\n        \\\"filterable\\\": False,\\n        \\\"edit_mode\\\": EditMode.INLINE,\\n        \\\"hidden\\\": False,\\n    },\\n    {\\n        \\\"name\\\": \\\"description\\\",\\n        \\\"display_name\\\": \\\"Tool Description\\\",\\n        \\\"type\\\": \\\"str\\\",\\n        \\\"description\\\": \\\"Describe the purpose of the tool.\\\",\\n        \\\"sortable\\\": False,\\n        \\\"filterable\\\": False,\\n        \\\"edit_mode\\\": EditMode.POPOVER,\\n        \\\"hidden\\\": False,\\n    },\\n    {\\n        \\\"name\\\": \\\"tags\\\",\\n        \\\"display_name\\\": \\\"Tool Identifiers\\\",\\n        \\\"type\\\": \\\"str\\\",\\n        \\\"description\\\": (\\\"The default identifiers for the tools and cannot be changed.\\\"),\\n        \\\"disable_edit\\\": True,\\n        \\\"sortable\\\": False,\\n        \\\"filterable\\\": False,\\n        \\\"edit_mode\\\": EditMode.INLINE,\\n        \\\"hidden\\\": True,\\n    },\\n    {\\n        \\\"name\\\": \\\"status\\\",\\n        \\\"display_name\\\": \\\"Enable\\\",\\n        \\\"type\\\": \\\"boolean\\\",\\n        \\\"description\\\": \\\"Indicates whether the tool is currently active. Set to True to activate this tool.\\\",\\n        \\\"default\\\": True,\\n    },\\n]\\n\\nTOOLS_METADATA_INFO = \\\"Modify tool names and descriptions to help agents understand when to use each tool.\\\"\\n\\nTOOL_UPDATE_CONSTANTS = [\\\"tool_mode\\\", \\\"tool_actions\\\", TOOLS_METADATA_INPUT_NAME, \\\"flow_name_selected\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/vectorstores/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/vectorstores/chroma_security.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fd424e77957c513edab6ae986bf307f7c38bf8d1ab93fa76ac8a394f7b48d22c\",\"content\":\"\\\"\\\"\\\"Safe defaults for Langflow-created Chroma collections.\\n\\nChroma collection configuration can persist server-side embedding functions.\\nSome embedding functions accept model-loading kwargs such as trust_remote_code.\\nLangflow embeds client-side, so built-in collection creation should not register\\nserver-side embedding code.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\n\\n\\ndef chroma_langchain_collection_kwargs() -> dict[str, Any]:\\n    \\\"\\\"\\\"Return LangChain Chroma kwargs that disable Chroma server-side embedding code.\\\"\\\"\\\"\\n    return {\\\"collection_configuration\\\": _chroma_collection_configuration_without_embedding_function()}\\n\\n\\ndef chroma_client_create_collection_kwargs() -> dict[str, Any]:\\n    \\\"\\\"\\\"Return chromadb client kwargs that create collections without server-side embedding code.\\\"\\\"\\\"\\n    return {\\n        \\\"configuration\\\": _chroma_collection_configuration_without_embedding_function(),\\n        \\\"embedding_function\\\": None,\\n    }\\n\\n\\ndef _chroma_collection_configuration_without_embedding_function() -> dict[str, Any]:\\n    return {\\\"embedding_function\\\": None}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/vectorstores/model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"194376af440fd79f5a1fe8dedb8cebe27d588f89064d47ab76f973515a4ea20b\",\"content\":\"from abc import abstractmethod\\nfrom functools import wraps\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.field_typing import Text, VectorStore\\nfrom lfx.helpers.data import docs_to_data\\nfrom lfx.inputs.inputs import BoolInput\\nfrom lfx.io import HandleInput, Output, QueryInput\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\n\\nif TYPE_CHECKING:\\n    from langchain_core.documents import Document\\n\\n\\ndef check_cached_vector_store(f):\\n    \\\"\\\"\\\"Decorator to check for cached vector stores, and returns them if they exist.\\n\\n    Note: caching only occurs during the execution of a component - they do not persist\\n    across separate invocations of the component. This method exists so that components with\\n    multiple output methods share the same vector store during the same invocation of the\\n    component.\\n    \\\"\\\"\\\"\\n\\n    @wraps(f)\\n    def check_cached(self, *args, **kwargs):\\n        should_cache = getattr(self, \\\"should_cache_vector_store\\\", True)\\n\\n        if should_cache and self._cached_vector_store is not None:\\n            return self._cached_vector_store\\n\\n        result = f(self, *args, **kwargs)\\n        self._cached_vector_store = result\\n        return result\\n\\n    check_cached.is_cached_vector_store_checked = True\\n    return check_cached\\n\\n\\nclass LCVectorStoreComponent(Component):\\n    # Used to ensure a single vector store is built for each run of the flow\\n    _cached_vector_store: VectorStore | None = None\\n\\n    def __init_subclass__(cls, **kwargs):\\n        \\\"\\\"\\\"Enforces the check cached decorator on all subclasses.\\\"\\\"\\\"\\n        super().__init_subclass__(**kwargs)\\n        if hasattr(cls, \\\"build_vector_store\\\"):\\n            method = cls.build_vector_store\\n            if not hasattr(method, \\\"is_cached_vector_store_checked\\\"):\\n                msg = (\\n                    f\\\"The method 'build_vector_store' in class {cls.__name__} \\\"\\n                    \\\"must be decorated with @check_cached_vector_store\\\"\\n                )\\n                raise TypeError(msg)\\n\\n    trace_type = \\\"retriever\\\"\\n\\n    inputs = [\\n        HandleInput(\\n            name=\\\"ingest_data\\\",\\n            display_name=\\\"Ingest Data\\\",\\n            input_types=[\\\"Data\\\", \\\"DataFrame\\\", \\\"Table\\\"],\\n            is_list=True,\\n        ),\\n        QueryInput(\\n            name=\\\"search_query\\\",\\n            display_name=\\\"Search Query\\\",\\n            info=\\\"Enter a query to run a similarity search.\\\",\\n            placeholder=\\\"Enter a query...\\\",\\n            tool_mode=True,\\n        ),\\n        BoolInput(\\n            name=\\\"should_cache_vector_store\\\",\\n            display_name=\\\"Cache Vector Store\\\",\\n            value=True,\\n            advanced=True,\\n            info=\\\"If True, the vector store will be cached for the current build of the component. \\\"\\n            \\\"This is useful for components that have multiple output methods and want to share the same vector store.\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\\"Search Results\\\",\\n            name=\\\"search_results\\\",\\n            method=\\\"search_documents\\\",\\n            info=(\\n                \\\"Performs semantic similarity search in the vector store to find relevant documents/files. \\\"\\n                \\\"Input: A natural language search query (str). \\\"\\n                \\\"Returns: A list of Data objects (dicts). Each result has structure: {'data': {'text': '...', ...}}. \\\"\\n                \\\"The 'text' field always contains the matched document content. \\\"\\n                \\\"Other metadata fields depend on what was indexed \\\"\\n                \\\"(may include: 'file_path', 'source', 'page', etc.). \\\"\\n                \\\"IMPORTANT: To extract metadata like file_path, use: \\\"\\n                \\\"result['data'].get('file_path') or result.data.get('file_path'). \\\"\\n                \\\"Check what fields are available by inspecting result['data'].keys() or the first search result.\\\"\\n            ),\\n            tool_mode=True,\\n        ),\\n        Output(\\n            display_name=\\\"Table\\\",\\n            name=\\\"dataframe\\\",\\n            method=\\\"as_dataframe\\\",\\n        ),\\n    ]\\n\\n    def _validate_outputs(self) -> None:\\n        # At least these three outputs must be defined\\n        required_output_methods = [\\n            \\\"search_documents\\\",\\n            \\\"build_vector_store\\\",\\n        ]\\n        output_names = [output.name for output in self.outputs]\\n        for method_name in required_output_methods:\\n            if method_name not in output_names:\\n                msg = f\\\"Output with name '{method_name}' must be defined.\\\"\\n                raise ValueError(msg)\\n            if not hasattr(self, method_name):\\n                msg = f\\\"Method '{method_name}' must be defined.\\\"\\n                raise ValueError(msg)\\n\\n    def _prepare_ingest_data(self) -> list[Any]:\\n        \\\"\\\"\\\"Prepares ingest_data by converting DataFrame to Data if needed.\\\"\\\"\\\"\\n        ingest_data: list | Data | DataFrame = self.ingest_data\\n        if not ingest_data:\\n            return []\\n\\n        if not isinstance(ingest_data, list):\\n            ingest_data = [ingest_data]\\n\\n        result = []\\n\\n        for _input in ingest_data:\\n            if isinstance(_input, DataFrame):\\n                result.extend(_input.to_data_list())\\n            else:\\n                result.append(_input)\\n        return result\\n\\n    def search_with_vector_store(\\n        self,\\n        input_value: Text,\\n        search_type: str,\\n        vector_store: VectorStore,\\n        k=10,\\n        **kwargs,\\n    ) -> list[Data]:\\n        \\\"\\\"\\\"Search for data in the vector store based on the input value and search type.\\n\\n        Args:\\n            input_value (Text): The input value to search for.\\n            search_type (str): The type of search to perform.\\n            vector_store (VectorStore): The vector store to search in.\\n            k (int): The number of results to return.\\n            **kwargs: Additional keyword arguments to pass to the vector store search method.\\n\\n        Returns:\\n            List[Data]: A list of data matching the search criteria.\\n\\n        Raises:\\n            ValueError: If invalid inputs are provided.\\n        \\\"\\\"\\\"\\n        docs: list[Document] = []\\n        if input_value and isinstance(input_value, str) and hasattr(vector_store, \\\"search\\\"):\\n            docs = vector_store.search(query=input_value, search_type=search_type.lower(), k=k, **kwargs)\\n        else:\\n            msg = \\\"Invalid inputs provided.\\\"\\n            raise ValueError(msg)\\n        data = docs_to_data(docs)\\n        self.status = data\\n        return data\\n\\n    def search_documents(self) -> list[Data]:\\n        \\\"\\\"\\\"Search for documents in the vector store.\\\"\\\"\\\"\\n        if self._cached_vector_store is not None:\\n            vector_store = self._cached_vector_store\\n        else:\\n            vector_store = self.build_vector_store()\\n            self._cached_vector_store = vector_store\\n\\n        search_query: str = self.search_query\\n        if not search_query:\\n            self.status = \\\"\\\"\\n            return []\\n\\n        self.log(f\\\"Search input: {search_query}\\\")\\n        self.log(f\\\"Search type: {self.search_type}\\\")\\n        self.log(f\\\"Number of results: {self.number_of_results}\\\")\\n\\n        search_results = self.search_with_vector_store(\\n            search_query, self.search_type, vector_store, k=self.number_of_results\\n        )\\n        self.status = search_results\\n        return search_results\\n\\n    def as_dataframe(self) -> DataFrame:\\n        return DataFrame(self.search_documents())\\n\\n    def get_retriever_kwargs(self):\\n        \\\"\\\"\\\"Get the retriever kwargs. Implementations can override this method to provide custom retriever kwargs.\\\"\\\"\\\"\\n        return {}\\n\\n    @abstractmethod\\n    @check_cached_vector_store\\n    def build_vector_store(self) -> VectorStore:\\n        \\\"\\\"\\\"Builds the Vector Store object.\\\"\\\"\\\"\\n        msg = \\\"build_vector_store method must be implemented.\\\"\\n        raise NotImplementedError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/vectorstores/user_scoping.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"db92eeb7bd2507181cbd7909f7b87b1dc63dd1d5f15be3a327602417eebc50e0\",\"content\":\"\\\"\\\"\\\"Per-user scoping helpers for local (on-disk) vector stores.\\n\\nLocal vector stores (Chroma, FAISS, LocalDB) persist to a directory keyed only by\\na collection / index name. Two different users that happen to pick the same name\\nand resolve to the same persist directory would otherwise read and write the same\\non-disk store, leaking documents across users.\\n\\nThese helpers derive a stable, non-identifying per-user name so local stores are\\nisolated by the runtime user, while remote/server-backed stores are left\\nuntouched. When there is genuinely no runtime user (e.g. running outside a\\nuser-owned graph) the original name is returned unchanged, so behaviour is\\npreserved for non-multi-user usage.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom hashlib import sha256\\nfrom typing import Any\\n\\n\\ndef scoped_collection_name(collection_name: str, user_id: object | None) -> str:\\n    \\\"\\\"\\\"Return a stable, non-identifying per-user name for a local vector store.\\n\\n    The returned value is derived from a length-prefixed\\n    ``sha256(user_id, collection_name)`` payload and is safe to use as a Chroma\\n    collection name or an on-disk index/file name. Falls back to the original\\n    ``collection_name`` when there is no usable user id, so callers can apply this\\n    unconditionally on the local/on-disk path.\\n    \\\"\\\"\\\"\\n    if not collection_name or user_id is None:\\n        return collection_name\\n\\n    user_id_str = str(user_id).strip()\\n    if not user_id_str or user_id_str == \\\"None\\\":\\n        return collection_name\\n\\n    # Length-prefix each field so the hash payload is unambiguous: a bare\\n    # \\\"{user_id}:{collection_name}\\\" join collides for pairs like (\\\"a:b\\\", \\\"c\\\") and\\n    # (\\\"a\\\", \\\"b:c\\\"), which would map distinct users/collections to the same store.\\n    payload = f\\\"{len(user_id_str)}:{user_id_str}{len(collection_name)}:{collection_name}\\\"\\n    digest = sha256(payload.encode()).hexdigest()[:16]\\n    return f\\\"lf_{digest}\\\"\\n\\n\\ndef runtime_user_id(component: Any) -> object | None:\\n    \\\"\\\"\\\"Return the runtime user id when the component executes in a user-owned graph.\\n\\n    Prefers the component's ``_user_id`` and falls back to the owning graph's\\n    ``user_id``. Returns ``None`` when neither is available so callers fail safe to\\n    the unscoped name.\\n    \\\"\\\"\\\"\\n    user_id = getattr(component, \\\"_user_id\\\", None)\\n    if user_id:\\n        return user_id\\n\\n    vertex = getattr(component, \\\"_vertex\\\", None)\\n    graph = getattr(vertex, \\\"graph\\\", None) if vertex is not None else None\\n    return getattr(graph, \\\"user_id\\\", None)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/vectorstores/utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3a104d62cf59f69a1ef36ad33453ddac448d446b8fe913baf9e3a9c2a24b046d\",\"content\":\"from lfx.schema.data import Data\\n\\n\\ndef chroma_collection_to_data(collection_dict: dict):\\n    \\\"\\\"\\\"Converts a collection of chroma vectors into a list of data.\\n\\n    Args:\\n        collection_dict (dict): A dictionary containing the collection of chroma vectors.\\n\\n    Returns:\\n        list: A list of data, where each record represents a document in the collection.\\n    \\\"\\\"\\\"\\n    data = []\\n    for i, doc in enumerate(collection_dict[\\\"documents\\\"]):\\n        data_dict = {\\n            \\\"id\\\": collection_dict[\\\"ids\\\"][i],\\n            \\\"text\\\": doc,\\n        }\\n        if (\\\"metadatas\\\" in collection_dict) and collection_dict[\\\"metadatas\\\"][i]:\\n            data_dict.update(collection_dict[\\\"metadatas\\\"][i].items())\\n        data.append(Data(**data_dict))\\n    return data\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/base/vectorstores/vector_store_connection_decorator.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"da08770cc85c32c0a055814415a54d313df3b1b77e7e4172e4197ffa35c3bbc7\",\"content\":\"from langchain_core.vectorstores import VectorStore\\n\\nfrom lfx.io import Output\\n\\n\\ndef vector_store_connection(cls):\\n    \\\"\\\"\\\"A decorator that adds vector store connection functionality to a class.\\n\\n    This decorator performs the following actions:\\n    1. Adds a `decorated` attribute to the class and sets it to True.\\n    2. Checks if the class has an `outputs` attribute:\\n        - If it does, it makes a copy of the `outputs` attribute to avoid modifying the base class attribute.\\n        - It then checks if \\\"vectorstoreconnection\\\" is not already in the output names.\\n        - If not, it adds a new `Output` entry for \\\"Vector Store Connection\\\" to the `outputs` attribute.\\n    3. Adds an `as_vector_store` method to the class, which returns the result of the `build_vector_store` method.\\n\\n    Args:\\n        cls (type): The class to be decorated.\\n\\n    Returns:\\n        type: The decorated class with added vector store connection functionality.\\n    \\\"\\\"\\\"\\n    cls.decorated = True  # Add an attribute to the class\\n\\n    if hasattr(cls, \\\"outputs\\\"):\\n        cls.outputs = cls.outputs.copy()  # Make a copy to avoid modifying the base class attribute\\n        output_names = [output.name for output in cls.outputs]\\n\\n        if \\\"vectorstoreconnection\\\" not in output_names:\\n            cls.outputs.extend(\\n                [\\n                    Output(\\n                        display_name=\\\"Vector Store Connection\\\",\\n                        hidden=False,\\n                        name=\\\"vectorstoreconnection\\\",\\n                        method=\\\"as_vector_store\\\",\\n                        group_outputs=False,\\n                    )\\n                ]\\n            )\\n\\n    def as_vector_store(self) -> VectorStore:\\n        \\\"\\\"\\\"Converts the current instance to a VectorStore object.\\n\\n        Returns:\\n            VectorStore: The resulting VectorStore object.\\n        \\\"\\\"\\\"\\n        return self.build_vector_store()\\n\\n    cls.as_vector_store = as_vector_store  # Ensures that the method is added to the class\\n\\n    return cls\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ec532514013c85f70eb19aa644c6dfd06326da23b21a52273a4ee8a59206c5d2\",\"content\":\"\\\"\\\"\\\"LFX CLI module for serving flows.\\\"\\\"\\\"\\n\\n__all__ = [\\\"serve_command\\\"]\\n\\n\\ndef __getattr__(name: str):\\n    \\\"\\\"\\\"Lazy import for serve_command.\\\"\\\"\\\"\\n    if name == \\\"serve_command\\\":\\n        from lfx.cli.commands import serve_command\\n\\n        return serve_command\\n    msg = f\\\"module {__name__!r} has no attribute {name!r}\\\"\\n    raise AttributeError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/_authoring_commands.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"036f555b6cd8fd2f346f391486cd6a355db92a16b5c9a0bb90aa38e74de7970e\",\"content\":\"\\\"\\\"\\\"Authoring commands: create, requirements, validate.\\\"\\\"\\\"\\n\\nimport typer\\n\\n\\ndef register(app: typer.Typer) -> None:\\n    \\\"\\\"\\\"Register authoring-stage commands on *app*.\\\"\\\"\\\"\\n\\n    @app.command(name=\\\"create\\\", help=\\\"Create a new flow JSON from a built-in template\\\", rich_help_panel=\\\"Authoring\\\")\\n    def create_command_wrapper(\\n        name: str = typer.Argument(help=\\\"Display name for the new flow (also used as the filename).\\\"),\\n        template: str = typer.Option(\\n            \\\"hello-world\\\",\\n            \\\"--template\\\",\\n            \\\"-t\\\",\\n            help=\\\"Template to use. Run with --list to see all available templates.\\\",\\n        ),\\n        output_dir: str = typer.Option(\\n            \\\"flows\\\",\\n            \\\"--output-dir\\\",\\n            \\\"-o\\\",\\n            help=\\\"Directory to write the new flow JSON into (created if absent; default: flows/).\\\",\\n        ),\\n        *,\\n        list_templates: bool = typer.Option(\\n            False,\\n            \\\"--list\\\",\\n            \\\"-l\\\",\\n            help=\\\"Print available templates and exit.\\\",\\n            is_eager=True,\\n        ),\\n        overwrite: bool = typer.Option(\\n            False,\\n            \\\"--overwrite\\\",\\n            help=\\\"Overwrite the destination file if it already exists.\\\",\\n        ),\\n    ) -> None:\\n        \\\"\\\"\\\"Scaffold a new Langflow flow JSON from a built-in template (lazy-loaded).\\\"\\\"\\\"\\n        from pathlib import Path\\n\\n        from lfx.cli.create import create_command, print_templates\\n\\n        if list_templates:\\n            print_templates()\\n            raise typer.Exit(0)\\n\\n        create_command(\\n            name=name,\\n            template=template,\\n            output_dir=Path(output_dir),\\n            overwrite=overwrite,\\n        )\\n\\n    @app.command(\\n        name=\\\"requirements\\\",\\n        help=\\\"Generate requirements.txt for a flow\\\",\\n        no_args_is_help=True,\\n        rich_help_panel=\\\"Authoring\\\",\\n    )\\n    def requirements_command_wrapper(\\n        flow_path: str = typer.Argument(help=\\\"Path to the Langflow flow JSON file\\\"),\\n        output: str | None = typer.Option(\\n            None,\\n            \\\"--output\\\",\\n            \\\"-o\\\",\\n            help=\\\"Output file path (default: stdout)\\\",\\n        ),\\n        lfx_package: str = typer.Option(\\n            \\\"lfx\\\",\\n            \\\"--lfx-package\\\",\\n            help=\\\"Name of the LFX package (default: lfx)\\\",\\n        ),\\n        *,\\n        no_lfx: bool = typer.Option(\\n            False,\\n            \\\"--no-lfx\\\",\\n            help=\\\"Exclude the LFX package from output\\\",\\n        ),\\n        no_pin: bool = typer.Option(\\n            False,\\n            \\\"--no-pin\\\",\\n            help=\\\"Do not pin package versions (default: pin to currently installed versions)\\\",\\n        ),\\n    ) -> None:\\n        \\\"\\\"\\\"Generate requirements.txt from a Langflow flow JSON (lazy-loaded).\\\"\\\"\\\"\\n        import json\\n        from pathlib import Path\\n\\n        from lfx.utils.flow_requirements import generate_requirements_txt\\n\\n        path = Path(flow_path)\\n        if not path.is_file():\\n            typer.echo(f\\\"Error: File not found: {path}\\\", err=True)\\n            raise typer.Exit(1)\\n\\n        try:\\n            flow = json.loads(path.read_text(encoding=\\\"utf-8\\\"))\\n        except (json.JSONDecodeError, OSError) as e:\\n            typer.echo(f\\\"Error: Could not read flow JSON: {e}\\\", err=True)\\n            raise typer.Exit(1) from e\\n\\n        content = generate_requirements_txt(\\n            flow,\\n            lfx_package=lfx_package,\\n            include_lfx=not no_lfx,\\n            pin_versions=not no_pin,\\n        )\\n\\n        if output:\\n            try:\\n                Path(output).write_text(content, encoding=\\\"utf-8\\\")\\n            except OSError as e:\\n                typer.echo(f\\\"Error: Could not write to {output}: {e}\\\", err=True)\\n                raise typer.Exit(1) from e\\n            typer.echo(f\\\"Requirements written to {output}\\\")\\n        else:\\n            typer.echo(content, nl=False)\\n\\n    @app.command(name=\\\"validate\\\", help=\\\"Validate one or more flow JSON files\\\", rich_help_panel=\\\"Authoring\\\")\\n    def validate_command_wrapper(\\n        flow_paths: list[str] = typer.Argument(\\n            default=None,\\n            help=\\\"Path(s) to Langflow flow JSON file(s) or directories to validate. Defaults to flows/.\\\",\\n        ),\\n        dir_path: str | None = typer.Option(\\n            None,\\n            \\\"--dir\\\",\\n            \\\"-d\\\",\\n            help=\\\"Directory of flow JSON files to validate (validates all *.json files). Defaults to flows/.\\\",\\n        ),\\n        level: int = typer.Option(\\n            4,\\n            \\\"--level\\\",\\n            \\\"-l\\\",\\n            min=1,\\n            max=4,\\n            help=(\\n                \\\"Validation depth: \\\"\\n                \\\"1=structural JSON, \\\"\\n                \\\"2=+component existence, \\\"\\n                \\\"3=+edge type compatibility, \\\"\\n                \\\"4=+required inputs connected\\\"\\n            ),\\n        ),\\n        skip_components: bool = typer.Option(\\n            False,\\n            \\\"--skip-components\\\",\\n            help=\\\"Skip component existence checks (level 2)\\\",\\n        ),\\n        skip_edge_types: bool = typer.Option(\\n            False,\\n            \\\"--skip-edge-types\\\",\\n            help=\\\"Skip edge type compatibility checks (level 3)\\\",\\n        ),\\n        skip_required_inputs: bool = typer.Option(\\n            False,\\n            \\\"--skip-required-inputs\\\",\\n            help=\\\"Skip required-inputs checks (level 4)\\\",\\n        ),\\n        skip_version_check: bool = typer.Option(\\n            False,\\n            \\\"--skip-version-check\\\",\\n            help=\\\"Skip version-mismatch / outdated-component warnings\\\",\\n        ),\\n        skip_credentials: bool = typer.Option(\\n            False,\\n            \\\"--skip-credentials\\\",\\n            help=\\\"Skip missing-credentials warnings for password/secret fields\\\",\\n        ),\\n        strict: bool = typer.Option(\\n            False,\\n            \\\"--strict\\\",\\n            help=\\\"Treat warnings as errors (exit 1 if any warnings are found)\\\",\\n        ),\\n        verbose: bool = typer.Option(\\n            False,\\n            \\\"--verbose\\\",\\n            \\\"-v\\\",\\n            help=\\\"Print all issues including warnings for passing flows\\\",\\n        ),\\n        output_format: str = typer.Option(\\n            \\\"text\\\",\\n            \\\"--format\\\",\\n            \\\"-f\\\",\\n            help=\\\"Output format: text (default) or json\\\",\\n        ),\\n    ) -> None:\\n        \\\"\\\"\\\"Validate Langflow flow JSON files without executing them (lazy-loaded).\\\"\\\"\\\"\\n        from lfx.cli.validate import validate_command\\n\\n        # Merge --dir into positional paths for a consistent interface with push\\n        effective_paths = list(flow_paths or [])\\n        if dir_path is not None:\\n            effective_paths.append(dir_path)\\n\\n        validate_command(\\n            flow_paths=effective_paths,\\n            level=level,\\n            skip_components=skip_components,\\n            skip_edge_types=skip_edge_types,\\n            skip_required_inputs=skip_required_inputs,\\n            skip_version_check=skip_version_check,\\n            skip_credentials=skip_credentials,\\n            strict=strict,\\n            verbose=verbose,\\n            output_format=output_format,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/_extension_commands.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"025502ca79ae197ad541d3951519a7322fa01c1216748c4787ee19623777cba8\",\"content\":\"\\\"\\\"\\\"Extension authoring commands.\\n\\nSub-app rather than a flat command so future authoring verbs (``init``,\\n``dev``, ``reload``, ...) can attach without a top-level naming collision with\\nthe existing ``lfx validate`` (which validates flow JSON, not extensions).\\n\\nCommands shipped here:\\n\\n    - ``validate``  -- static manifest + AST checker.\\n    - ``schema``    -- emit the manifest JSON Schema.\\n    - ``init``      -- scaffold a basic single-Bundle extension.\\n    - ``dev``       -- register a local extension and launch Langflow with\\n                       it loaded.\\n\\nEach command is implemented as a thin shell over the helpers in\\n``lfx.extension.*`` so the same code paths are reachable from tests\\nwithout going through Typer.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport os\\nimport shlex\\nimport shutil\\nimport subprocess\\nimport sys\\nfrom pathlib import Path\\n\\nimport typer\\n\\nextension_app = typer.Typer(\\n    name=\\\"extension\\\",\\n    help=\\\"Author and inspect Langflow Extensions.\\\",\\n    no_args_is_help=True,\\n    add_completion=False,\\n)\\n\\n\\ndef register(app: typer.Typer) -> None:\\n    \\\"\\\"\\\"Mount the ``extension`` sub-app on *app* under the Authoring help panel.\\\"\\\"\\\"\\n    app.add_typer(extension_app, name=\\\"extension\\\", rich_help_panel=\\\"Authoring\\\")\\n\\n\\n@extension_app.command(\\n    name=\\\"validate\\\",\\n    help=\\\"Statically validate an extension manifest and bundle (offline by default).\\\",\\n)\\ndef validate_command(\\n    root: str = typer.Argument(\\n        \\\".\\\",\\n        help=(\\n            \\\"Path to the extension root (the directory containing extension.json \\\"\\n            \\\"or pyproject.toml). Defaults to the current directory.\\\"\\n        ),\\n    ),\\n    output_format: str = typer.Option(\\n        \\\"text\\\",\\n        \\\"--format\\\",\\n        \\\"-f\\\",\\n        help=\\\"Output format: text (default) or json.\\\",\\n    ),\\n    *,\\n    execute_imports: bool = typer.Option(\\n        False,  # noqa: FBT003 - typer Option requires positional default\\n        \\\"--execute-imports\\\",\\n        help=(\\n            \\\"Additionally run each bundle module in a fresh subprocess to \\\"\\n            \\\"surface import-time errors. Opt-in only: never invoked in pack, \\\"\\n            \\\"publish, install, or registry-ingest pipelines.\\\"\\n        ),\\n    ),\\n) -> None:\\n    \\\"\\\"\\\"Run the offline extension validator and exit non-zero on any error.\\n\\n    By default this performs:\\n      1. Manifest discovery and Pydantic schema validation.\\n      2. Path-safety checks on every declared bundle path.\\n      3. AST-level inspection of every Python source file in each bundle.\\n\\n    With ``--execute-imports``, additionally imports each bundle module in a\\n    subprocess with a temporary Langflow state directory.\\n    \\\"\\\"\\\"\\n    from lfx.extension import format_extension_error, validate_extension\\n\\n    target = Path(root)\\n    report = validate_extension(target, execute_imports=execute_imports)\\n\\n    if output_format not in {\\\"text\\\", \\\"json\\\"}:\\n        typer.echo(\\\"Invalid --format. Expected one of: text, json.\\\", err=True)\\n        raise typer.Exit(code=2)\\n\\n    if output_format == \\\"json\\\":\\n        payload = {\\n            \\\"ok\\\": report.ok,\\n            \\\"root\\\": str(report.root),\\n            \\\"manifest\\\": report.manifest.model_dump(by_alias=True, mode=\\\"json\\\") if report.manifest is not None else None,\\n            \\\"errors\\\": [e.to_dict() for e in report.errors.errors],\\n            \\\"warnings\\\": [w.to_dict() for w in report.errors.warnings],\\n            \\\"bundle_files_scanned\\\": report.bundle_files_scanned,\\n        }\\n        typer.echo(json.dumps(payload, indent=2, sort_keys=True))\\n    else:\\n        if report.ok:\\n            typer.echo(f\\\"validate: ok ({report.bundle_files_scanned} file(s) scanned)\\\")\\n        else:\\n            for error in report.errors.errors:\\n                typer.echo(format_extension_error(error), err=True)\\n                typer.echo(\\\"\\\", err=True)\\n        for warning in report.errors.warnings:\\n            typer.echo(format_extension_error(warning), err=True)\\n\\n    if not report.ok:\\n        raise typer.Exit(code=1)\\n\\n\\n@extension_app.command(\\n    name=\\\"list\\\",\\n    help=\\\"List installed and seed-directory Extensions discovered at startup.\\\",\\n)\\ndef list_command(\\n    output_format: str = typer.Option(\\n        \\\"text\\\",\\n        \\\"--format\\\",\\n        \\\"-f\\\",\\n        help=\\\"Output format: text (default) or json.\\\",\\n    ),\\n    seed_dir: str | None = typer.Option(\\n        None,\\n        \\\"--seed-dir\\\",\\n        help=(\\n            \\\"Override $LANGFLOW_SEED_DIR for this invocation. \\\"\\n            \\\"Use os.pathsep (':' on POSIX) to pass multiple roots. \\\"\\n            \\\"Pass an empty string to skip the seed-directory pass entirely.\\\"\\n        ),\\n    ),\\n) -> None:\\n    \\\"\\\"\\\"Print every Extension currently visible to production discovery.\\n\\n    Read-only.  Mutation verbs (enable, disable, install, uninstall) are\\n    intentionally absent in this milestone; they ship in follow-up work,\\n    and the router-trust CI guard blocks them from sneaking in via HTTP\\n    routes.\\n\\n    Output (text mode) is one row per Extension::\\n\\n        ID                  VERSION   BUNDLE              SLOT       SOURCE   STATUS\\n        lfx-openai          1.2.0     openai              @official  installed  discovered\\n        lfx-anthropic       0.4.1     anthropic           @official  seed       discovered\\n\\n    Errors from discovery (malformed manifests, missing seed dirs) are\\n    appended after the table, separated by a blank line, and rendered with\\n    :func:`~lfx.extension.format_extension_error`.\\n\\n    JSON mode emits a stable structure that downstream tooling can pin to::\\n\\n        {\\n          \\\"extensions\\\": [...],\\n          \\\"errors\\\":     [...]\\n        }\\n    \\\"\\\"\\\"\\n    from lfx.extension import (\\n        build_registry_from_discovery,\\n        discover_all_extensions,\\n        format_extension_error,\\n    )\\n\\n    if output_format not in {\\\"text\\\", \\\"json\\\"}:\\n        typer.echo(\\\"Invalid --format. Expected one of: text, json.\\\", err=True)\\n        raise typer.Exit(code=2)\\n\\n    extensions, errors = discover_all_extensions(seed_dir_env=seed_dir)\\n    registry, dup_errors = build_registry_from_discovery(extensions)\\n    all_errors = errors + dup_errors\\n    rows = registry.list_extensions()\\n\\n    # Codes that signal \\\"something is wrong but discovery itself succeeded\\\".\\n    # ``lfx extension list`` should still exit 0 in those cases so CI scripts\\n    # like ``lfx extension list && ...`` keep flowing -- the warning stays on\\n    # stderr where humans see it.  Configuration errors that point at a\\n    # missing seed dir stay as hard failures: that's an operator misconfig,\\n    # not a runtime warning.\\n    warn_only_codes = frozenset({\\\"seed-bundle-shadowed\\\", \\\"bundle-shadowed\\\"})\\n    hard_errors = [err for err in all_errors if err.code not in warn_only_codes]\\n\\n    if output_format == \\\"json\\\":\\n        payload = {\\n            \\\"interpreter\\\": {\\n                \\\"executable\\\": sys.executable,\\n                \\\"prefix\\\": sys.prefix,\\n                \\\"version\\\": sys.version.split()[0],\\n            },\\n            \\\"extensions\\\": [\\n                {\\n                    \\\"id\\\": ext.extension_id,\\n                    \\\"version\\\": ext.version,\\n                    \\\"bundle\\\": ext.bundle_name,\\n                    \\\"bundles\\\": list(ext.bundle_names),\\n                    \\\"slot\\\": ext.namespaced_slot,\\n                    \\\"source_kind\\\": ext.source_kind,\\n                    \\\"source\\\": ext.source,\\n                    \\\"extension_root\\\": str(ext.extension_root),\\n                    \\\"auto_update\\\": ext.auto_update,\\n                    \\\"load_status\\\": ext.load_status.value,\\n                }\\n                for ext in rows\\n            ],\\n            \\\"errors\\\": [err.to_dict() for err in all_errors],\\n        }\\n        typer.echo(json.dumps(payload, indent=2, sort_keys=True))\\n        if hard_errors:\\n            raise typer.Exit(code=1)\\n        return\\n\\n    # Print interpreter info up front so an operator who sees an empty\\n    # listing can immediately spot a wrong-venv mismatch between ``lfx``\\n    # and ``langflow run`` without a separate \\\"did my bundle install?\\\"\\n    # debug cycle.\\n    typer.echo(f\\\"python:     {sys.executable}\\\")\\n    typer.echo(f\\\"sys.prefix: {sys.prefix}\\\")\\n    typer.echo(\\\"\\\")\\n\\n    if not rows and not all_errors:\\n        typer.echo(\\\"No installed or seed-directory Extensions discovered.\\\")\\n        return\\n\\n    if rows:\\n        # Compute column widths from the data; cap each so a malicious manifest\\n        # cannot blow up the terminal.  Widths are clamped well above the\\n        # documented identifier limits (64 chars) so normal entries align.\\n        def _w(values: list[str], header: str, *, cap: int = 48) -> int:\\n            return min(cap, max(len(header), *(len(v) for v in values)))\\n\\n        ids = [r.extension_id for r in rows]\\n        versions = [r.version for r in rows]\\n        # A provider-only extension has no component bundle; show a dash.\\n        bundles = [\\\", \\\".join(r.bundle_names) or \\\"\u2014\\\" for r in rows]\\n        slots = [r.namespaced_slot for r in rows]\\n        sources = [r.source_kind for r in rows]\\n        statuses = [r.load_status.value for r in rows]\\n\\n        cols = (\\n            (\\\"ID\\\", _w(ids, \\\"ID\\\")),\\n            (\\\"VERSION\\\", _w(versions, \\\"VERSION\\\", cap=24)),\\n            (\\\"BUNDLE\\\", _w(bundles, \\\"BUNDLE\\\")),\\n            (\\\"SLOT\\\", _w(slots, \\\"SLOT\\\", cap=16)),\\n            (\\\"SOURCE\\\", _w(sources, \\\"SOURCE\\\", cap=12)),\\n            (\\\"STATUS\\\", _w(statuses, \\\"STATUS\\\", cap=12)),\\n        )\\n        header = \\\"  \\\".join(name.ljust(width) for name, width in cols)\\n        typer.echo(header)\\n        for row in rows:\\n            cells = (\\n                row.extension_id,\\n                row.version,\\n                \\\", \\\".join(row.bundle_names) or \\\"\u2014\\\",\\n                row.namespaced_slot,\\n                row.source_kind,\\n                row.load_status.value,\\n            )\\n            line = \\\"  \\\".join(value.ljust(width) for value, (_, width) in zip(cells, cols, strict=False))\\n            typer.echo(line.rstrip())\\n\\n    if all_errors:\\n        if rows:\\n            typer.echo(\\\"\\\", err=True)\\n        for err in all_errors:\\n            typer.echo(format_extension_error(err), err=True)\\n            typer.echo(\\\"\\\", err=True)\\n        if hard_errors:\\n            raise typer.Exit(code=1)\\n\\n\\n@extension_app.command(\\n    name=\\\"reload\\\",\\n    help=\\\"Trigger an atomic-swap reload for an installed Bundle.\\\",\\n)\\ndef reload_command(\\n    extension_id: str | None = typer.Argument(\\n        None,\\n        help=(\\\"ID of the extension whose Bundle should be reloaded (e.g. lfx-arxiv). Omit when passing --all.\\\"),\\n    ),\\n    bundle: str | None = typer.Option(\\n        None,\\n        \\\"--bundle\\\",\\n        \\\"-b\\\",\\n        help=(\\n            \\\"Bundle name to reload.  Optional: when omitted, the bundle \\\"\\n            \\\"name is resolved from the local extension discovery (the \\\"\\n            \\\"same source ``lfx extension list`` uses).\\\"\\n        ),\\n    ),\\n    target: str | None = typer.Option(\\n        None,\\n        \\\"--target\\\",\\n        help=(\\\"Langflow server URL (default: $LANGFLOW_HOST / http://localhost:7860).\\\"),\\n    ),\\n    api_key: str | None = typer.Option(\\n        None,\\n        \\\"--api-key\\\",\\n        help=\\\"API key for the Langflow server (default: $LANGFLOW_API_KEY).\\\",\\n    ),\\n    output_format: str = typer.Option(\\n        \\\"text\\\",\\n        \\\"--format\\\",\\n        \\\"-f\\\",\\n        help=\\\"Output format: text (default) or json.\\\",\\n    ),\\n    *,\\n    reload_all: bool = typer.Option(\\n        False,  # noqa: FBT003 - typer Option requires positional default\\n        \\\"--all\\\",\\n        help=\\\"Reload every locally-discovered Bundle.\\\",\\n    ),\\n) -> None:\\n    \\\"\\\"\\\"POST to the reload endpoint and surface the typed result.\\n\\n    Resolution strategy:\\n        * ``--all`` reloads every Bundle visible to local discovery\\n          (``discover_all_extensions``); ``extension_id`` is ignored.\\n        * Otherwise, ``extension_id`` is required.  If ``--bundle`` is\\n          omitted, the bundle name is looked up from local discovery.\\n        * ``--bundle`` always wins when explicitly passed -- useful when\\n          the local install isn't visible to the running server, or when\\n          you want to target a bundle by name without re-running discovery.\\n\\n    Exit codes:\\n        0 -- reload(s) succeeded.\\n        1 -- one or more reloads failed (broken bundle, source missing,\\n             name mismatch, transport error, or local discovery turned up\\n             nothing for the requested extension).\\n        2 -- argument error (e.g. neither ``extension_id`` nor ``--all``).\\n    \\\"\\\"\\\"\\n    if output_format not in {\\\"text\\\", \\\"json\\\"}:\\n        typer.echo(\\\"Invalid --format. Expected one of: text, json.\\\", err=True)\\n        raise typer.Exit(code=2)\\n\\n    if reload_all:\\n        if extension_id is not None or bundle is not None:\\n            typer.echo(\\n                \\\"extension reload --all does not take an extension id or --bundle; \\\"\\n                \\\"pass only --all to reload every locally-discovered Bundle.\\\",\\n                err=True,\\n            )\\n            raise typer.Exit(code=2)\\n        _reload_all(target=target, api_key=api_key, output_format=output_format)\\n        return\\n\\n    if extension_id is None:\\n        typer.echo(\\n            \\\"extension reload requires an extension id (e.g. `lfx extension reload lfx-arxiv`), \\\"\\n            \\\"or pass --all to reload every locally-discovered Bundle.\\\",\\n            err=True,\\n        )\\n        raise typer.Exit(code=2)\\n\\n    bundle_name = bundle or _resolve_bundle_from_discovery(extension_id)\\n    if bundle_name is None:\\n        raise typer.Exit(code=1)\\n\\n    response = _post_reload(\\n        target=target,\\n        api_key=api_key,\\n        extension_id=extension_id,\\n        bundle_name=bundle_name,\\n    )\\n\\n    if output_format == \\\"json\\\":\\n        typer.echo(json.dumps(response.payload, indent=2, sort_keys=True))\\n        raise typer.Exit(code=response.exit_code())\\n\\n    _render_reload_text(response, extension_id=extension_id, bundle_name=bundle_name)\\n    raise typer.Exit(code=response.exit_code())\\n\\n\\ndef _resolve_bundle_from_discovery(extension_id: str) -> str | None:\\n    \\\"\\\"\\\"Look up the single bundle name for ``extension_id`` via local discovery.\\n\\n    Returns the bundle name on success, or ``None`` and prints a typed\\n    error on stderr when the extension is not locally installed or when\\n    its manifest declares multiple bundles.\\n    \\\"\\\"\\\"\\n    from lfx.extension import discover_all_extensions\\n\\n    extensions, _errors = discover_all_extensions()\\n    matches = [ext for ext in extensions if ext.extension_id == extension_id]\\n    if not matches:\\n        typer.echo(\\n            f\\\"extension reload: no locally-discovered extension {extension_id!r}.\\\\n\\\"\\n            \\\"  - Run `lfx extension list` to see what is installed locally.\\\\n\\\"\\n            \\\"  - If the bundle is installed only on the remote server, \\\"\\n            \\\"pass --bundle <name> explicitly.\\\",\\n            err=True,\\n        )\\n        return None\\n    bundles = sorted({bundle_name for ext in matches for bundle_name in ext.bundle_names})\\n    if len(bundles) > 1:\\n        typer.echo(\\n            f\\\"extension reload: extension {extension_id!r} resolves to multiple bundles \\\"\\n            f\\\"({', '.join(bundles)}); pass --bundle <name> to disambiguate.\\\",\\n            err=True,\\n        )\\n        return None\\n    if not bundles:\\n        typer.echo(\\n            f\\\"extension reload: extension {extension_id!r} does not declare a component bundle; \\\"\\n            \\\"provider-only extensions cannot be reloaded.\\\",\\n            err=True,\\n        )\\n        return None\\n    return bundles[0]\\n\\n\\ndef _post_reload(\\n    *,\\n    target: str | None,\\n    api_key: str | None,\\n    extension_id: str,\\n    bundle_name: str,\\n):\\n    \\\"\\\"\\\"Thin wrapper around :func:`reload_via_http` for symmetry with --all.\\\"\\\"\\\"\\n    from lfx.cli._extension_reload_client import reload_via_http\\n\\n    return reload_via_http(\\n        target=target,\\n        api_key=api_key,\\n        extension_id=extension_id,\\n        bundle_name=bundle_name,\\n    )\\n\\n\\ndef _render_reload_text(response, *, extension_id: str, bundle_name: str) -> None:\\n    \\\"\\\"\\\"Render a single reload response in text mode (success or failure).\\\"\\\"\\\"\\n    from lfx.extension.errors import ExtensionError, format_extension_error\\n\\n    if response.ok:\\n        added = response.payload.get(\\\"components_added\\\") or []\\n        removed = response.payload.get(\\\"components_removed\\\") or []\\n        typer.echo(f\\\"reload: ok extension={extension_id} bundle={bundle_name}\\\")\\n        if added:\\n            typer.echo(f\\\"  added:   {', '.join(added)}\\\")\\n        if removed:\\n            typer.echo(f\\\"  removed: {', '.join(removed)}\\\")\\n        return\\n\\n    # Failure path: render typed errors when present, fall back to status text.\\n    raw_errors = response.payload.get(\\\"errors\\\") or []\\n    if not raw_errors and \\\"detail\\\" in response.payload:\\n        # FastAPI wraps HTTPException bodies in {\\\"detail\\\": {...}}.\\n        detail = response.payload[\\\"detail\\\"]\\n        if isinstance(detail, dict):\\n            raw_errors = [detail]\\n    rendered_any = False\\n    for raw in raw_errors:\\n        if not isinstance(raw, dict):\\n            continue\\n        code = raw.get(\\\"code\\\")\\n        if not code:\\n            continue\\n        try:\\n            err = ExtensionError(\\n                code=code,\\n                message=str(raw.get(\\\"message\\\", \\\"\\\")),\\n                hint=str(raw.get(\\\"hint\\\") or \\\"Run `lfx extension validate` for details.\\\"),\\n                location=raw.get(\\\"location\\\"),\\n                content=raw.get(\\\"content\\\"),\\n            )\\n        except ValueError:\\n            typer.echo(f\\\"error[{code}]: {raw.get('message', '<no message>')}\\\", err=True)\\n            rendered_any = True\\n            continue\\n        typer.echo(format_extension_error(err), err=True)\\n        typer.echo(\\\"\\\", err=True)\\n        rendered_any = True\\n    if not rendered_any:\\n        typer.echo(\\n            f\\\"reload: failed (HTTP {response.status} extension={extension_id} bundle={bundle_name})\\\",\\n            err=True,\\n        )\\n\\n\\ndef _reload_all(*, target: str | None, api_key: str | None, output_format: str) -> None:\\n    \\\"\\\"\\\"Reload every locally-discovered Bundle, aggregating results.\\n\\n    Sequential by design: a parallel sweep would race for the registry's\\n    per-bundle reload lock, and the cost of N sequential POSTs is dominated\\n    by per-bundle import time on the server, not by round-trip latency.\\n\\n    Exits 0 when every reload succeeds (or there were no bundles to reload);\\n    exits 1 if any reload failed.\\n    \\\"\\\"\\\"\\n    from lfx.extension import discover_all_extensions\\n\\n    extensions, _errors = discover_all_extensions()\\n    reload_targets = [(ext.extension_id, bundle_name) for ext in extensions for bundle_name in ext.bundle_names]\\n\\n    if output_format == \\\"json\\\":\\n        results = []\\n        any_failed = False\\n        for extension_id, bundle_name in reload_targets:\\n            response = _post_reload(\\n                target=target,\\n                api_key=api_key,\\n                extension_id=extension_id,\\n                bundle_name=bundle_name,\\n            )\\n            results.append(\\n                {\\n                    \\\"extension_id\\\": extension_id,\\n                    \\\"bundle_name\\\": bundle_name,\\n                    \\\"status\\\": response.status,\\n                    \\\"ok\\\": response.ok,\\n                    \\\"payload\\\": response.payload,\\n                }\\n            )\\n            if not response.ok:\\n                any_failed = True\\n        typer.echo(json.dumps({\\\"results\\\": results}, indent=2, sort_keys=True))\\n        raise typer.Exit(code=1 if any_failed else 0)\\n\\n    if not reload_targets:\\n        typer.echo(\\n            \\\"extension reload --all: no locally-discovered bundles to reload.\\\\n\\\"\\n            \\\"  - Run `lfx extension list` to confirm what is installed.\\\",\\n        )\\n        return\\n\\n    any_failed = False\\n    successes = 0\\n    failures = 0\\n    for extension_id, bundle_name in reload_targets:\\n        response = _post_reload(\\n            target=target,\\n            api_key=api_key,\\n            extension_id=extension_id,\\n            bundle_name=bundle_name,\\n        )\\n        _render_reload_text(\\n            response,\\n            extension_id=extension_id,\\n            bundle_name=bundle_name,\\n        )\\n        if response.ok:\\n            successes += 1\\n        else:\\n            failures += 1\\n            any_failed = True\\n\\n    typer.echo(\\\"\\\")\\n    typer.echo(f\\\"extension reload --all: {successes} ok, {failures} failed.\\\")\\n    if any_failed:\\n        raise typer.Exit(code=1)\\n\\n\\n@extension_app.command(\\n    name=\\\"schema\\\",\\n    help=\\\"Print the JSON Schema for the extension manifest (writeable to disk).\\\",\\n)\\ndef schema_command(\\n    output: str | None = typer.Option(\\n        None,\\n        \\\"--output\\\",\\n        \\\"-o\\\",\\n        help=\\\"Write the schema to this path instead of stdout.\\\",\\n    ),\\n) -> None:\\n    \\\"\\\"\\\"Emit the v1 manifest JSON Schema.\\n\\n    Use to vendor a copy under ``schemas/`` or to confirm the canonical shape\\n    for editor tooling.  The schema's ``$id`` always points at\\n    ``schemas.langflow.org/extension/v1.json``; the release pipeline uploads\\n    this same artifact.\\n    \\\"\\\"\\\"\\n    from lfx.extension.schema import build_schema_json\\n\\n    payload = build_schema_json()\\n    if output:\\n        Path(output).write_text(payload, encoding=\\\"utf-8\\\")\\n        typer.echo(f\\\"Schema written to {output}\\\")\\n    else:\\n        sys.stdout.write(payload)\\n\\n\\n# ---------------------------------------------------------------------------\\n# init\\n# ---------------------------------------------------------------------------\\n\\n\\n@extension_app.command(\\n    name=\\\"init\\\",\\n    help=\\\"Scaffold a basic single-Bundle extension at the given path.\\\",\\n)\\ndef init_command(\\n    target: str = typer.Argument(\\n        ...,\\n        help=(\\n            \\\"Directory to create.  Must NOT already exist as a non-empty \\\"\\n            \\\"directory; ``init`` refuses to overwrite hand-edited code.\\\"\\n        ),\\n    ),\\n    *,\\n    template: str = typer.Option(\\n        \\\"basic\\\",\\n        \\\"--template\\\",\\n        help=(\\n            \\\"Template name.  Only 'basic' is accepted in this milestone; \\\"\\n            \\\"richer templates (full, service, route, multi-bundle, \\\"\\n            \\\"starter-projects) are deferred and refused with a typed error.\\\"\\n        ),\\n    ),\\n    extension_id: str | None = typer.Option(\\n        None,\\n        \\\"--id\\\",\\n        help=(\\n            \\\"Manifest extension id (lowercase-hyphenated).  Defaults to the \\\"\\n            \\\"target directory name with non-id characters cleaned up.\\\"\\n        ),\\n    ),\\n    name: str | None = typer.Option(\\n        None,\\n        \\\"--name\\\",\\n        help=(\\\"Human-readable display name shown in Langflow.  Defaults to the title-cased extension id.\\\"),\\n    ),\\n) -> None:\\n    \\\"\\\"\\\"Create a runnable extension skeleton you can iterate on with ``dev``.\\n\\n    Acceptance criteria for this command:\\n\\n      - ``init <target>`` followed immediately by ``validate <target>``\\n        passes with zero errors.\\n      - The generated test file is a valid pytest module.\\n      - ``--template <anything-other-than-basic>`` fails cleanly with\\n        ``template-deferred-in-this-milestone`` and a non-zero exit.\\n    \\\"\\\"\\\"\\n    from lfx.extension import format_extension_error\\n    from lfx.extension.init_template import (\\n        BASIC_TEMPLATE,\\n        InitOptions,\\n        derive_bundle_name,\\n        derive_display_name,\\n        derive_extension_id,\\n        init_extension,\\n    )\\n\\n    target_path = Path(target).expanduser().resolve()\\n    derived_id = extension_id or derive_extension_id(target_path.name)\\n    options = InitOptions(\\n        target=target_path,\\n        extension_id=derived_id,\\n        bundle_name=derive_bundle_name(derived_id),\\n        display_name=name or derive_display_name(derived_id),\\n        # Pass --template through verbatim; the helper rejects everything\\n        # but BASIC_TEMPLATE with a typed error so the CLI doesn't have\\n        # to know the deferred-template list.\\n        template=template or BASIC_TEMPLATE,\\n    )\\n\\n    result = init_extension(options)\\n    if not result.ok:\\n        for error in result.errors:\\n            typer.echo(format_extension_error(error), err=True)\\n            typer.echo(\\\"\\\", err=True)\\n        raise typer.Exit(code=1)\\n\\n    typer.echo(f\\\"Created extension at {target_path}\\\")\\n    typer.echo(\\\"Next steps:\\\")\\n    typer.echo(f\\\"  lfx extension validate {target_path}\\\")\\n    typer.echo(f\\\"  lfx extension dev {target_path}\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# dev\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _resolve_langflow_executable() -> str | None:\\n    \\\"\\\"\\\"Find the ``langflow`` binary on PATH, if any.\\n\\n    Returns ``None`` when langflow isn't installed; the dev command then\\n    falls back to ``python -m langflow.__main__`` so an author with the\\n    ``lfx`` package alone still gets a usable error message.\\n    \\\"\\\"\\\"\\n    return shutil.which(\\\"langflow\\\")\\n\\n\\n@extension_app.command(\\n    name=\\\"dev\\\",\\n    help=\\\"Register a local extension and launch Langflow with it loaded.\\\",\\n)\\ndef dev_command(\\n    target: str = typer.Argument(\\n        \\\".\\\",\\n        help=(\\n            \\\"Path to the extension root (defaults to the current \\\"\\n            \\\"directory).  Must contain extension.json or \\\"\\n            \\\"[tool.langflow.extension] in pyproject.toml.\\\"\\n        ),\\n    ),\\n    *,\\n    skip_validate: bool = typer.Option(\\n        False,  # noqa: FBT003\\n        \\\"--skip-validate\\\",\\n        help=(\\n            \\\"Skip the pre-launch validate pass.  Useful when you're \\\"\\n            \\\"iterating on a known-broken manifest and want to see the \\\"\\n            \\\"loader's runtime error rather than the static one.\\\"\\n        ),\\n    ),\\n    skip_launch: bool = typer.Option(\\n        False,  # noqa: FBT003\\n        \\\"--skip-launch\\\",\\n        help=(\\n            \\\"Register the extension in the dev registry but don't exec \\\"\\n            \\\"``langflow run``.  Useful for tests and for embedding in \\\"\\n            \\\"external dev-server scripts.\\\"\\n        ),\\n    ),\\n    extra_args: list[str] | None = typer.Argument(\\n        None,\\n        help=\\\"Extra arguments forwarded to ``langflow run`` (after a ``--`` separator).\\\",\\n    ),\\n) -> None:\\n    \\\"\\\"\\\"Register the extension and launch a Langflow dev server.\\n\\n    Flow:\\n        1. Resolve the absolute path of the target extension.\\n        2. (Default) Run ``validate`` and abort on errors.\\n        3. Register the absolute path in the dev registry state file.\\n        4. Print reload instructions.\\n        5. ``exec``-style hand-off to ``langflow run`` (or\\n           ``python -m langflow``) with the env var\\n           ``LANGFLOW_LAZY_LOAD_COMPONENTS=false`` so dev-extensions are\\n           visible in the palette immediately.\\n\\n    AC #4 (\\\"boots Langflow with the new Extension visible in the palette\\n    within 5s\\\") is delivered jointly by this command and the startup\\n    hook in ``langflow.main`` that consults the dev registry.\\n    \\\"\\\"\\\"\\n    from lfx.extension import format_extension_error, register_dev_extension, validate_extension\\n\\n    target_path = Path(target).expanduser().resolve()\\n    if not target_path.is_dir():\\n        typer.echo(f\\\"error: {target_path} is not a directory\\\", err=True)\\n        raise typer.Exit(code=1)\\n\\n    if not skip_validate:\\n        report = validate_extension(target_path)\\n        if not report.ok:\\n            for error in report.errors.errors:\\n                typer.echo(format_extension_error(error), err=True)\\n                typer.echo(\\\"\\\", err=True)\\n            typer.echo(\\n                \\\"Refusing to register an extension that fails validate; re-run with --skip-validate to override.\\\",\\n                err=True,\\n            )\\n            raise typer.Exit(code=1)\\n\\n    entry = register_dev_extension(target_path)\\n    typer.echo(f\\\"Registered dev extension: {entry.path}\\\")\\n    typer.echo(\\\"Reload instructions:\\\")\\n    typer.echo(\\\"  - Edit any file under components/ in the registered directory.\\\")\\n    typer.echo(\\\"  - Click 'Reload' on the bundle header in the Langflow palette.\\\")\\n\\n    if skip_launch:\\n        return\\n\\n    extras = list(extra_args or [])\\n    cmd = _build_langflow_run_argv(extras)\\n    typer.echo(\\\"\\\")\\n    typer.echo(\\\"Launching: \\\" + \\\" \\\".join(shlex.quote(part) for part in cmd))\\n\\n    env = _build_dev_launch_env(os.environ)\\n\\n    # Replace the current process so Ctrl-C in the launched langflow\\n    # propagates without an extra pty/job-control hop.  When ``langflow``\\n    # isn't on PATH we fall back to python -m via subprocess so the\\n    # author still gets a meaningful exit code.\\n    if cmd[0] == sys.executable:\\n        rc = subprocess.run(cmd, env=env, check=False).returncode  # noqa: S603\\n        raise typer.Exit(code=rc)\\n    os.execvpe(cmd[0], cmd, env)  # noqa: S606\\n\\n\\ndef _build_dev_launch_env(base_env: os._Environ[str] | dict[str, str]) -> dict[str, str]:\\n    \\\"\\\"\\\"Build the env dict handed to the launched ``langflow run`` process.\\n\\n    Centralizes the per-flag rationale so the contract is testable in one\\n    place and a missing flag is caught by a focused unit test rather than\\n    only manifesting as a runtime UX gap.\\n\\n    Flags set:\\n        - ``LANGFLOW_LAZY_LOAD_COMPONENTS=false`` (always, overriding the\\n          author's shell): dev components must appear in the palette\\n          eagerly so the AC's 5-second budget holds.\\n        - ``LANGFLOW_ENABLE_EXTENSION_RELOAD=true`` (setdefault): turns on\\n          the in-process Bundle reload route AND the ``/config`` flag the\\n          packaged frontend reads at runtime to surface the palette\\n          Reload button.  ``setdefault`` so an author intentionally\\n          testing the off path can pre-export ``=false``.\\n    \\\"\\\"\\\"\\n    env = dict(base_env)\\n    env[\\\"LANGFLOW_LAZY_LOAD_COMPONENTS\\\"] = \\\"false\\\"\\n    env.setdefault(\\\"LANGFLOW_ENABLE_EXTENSION_RELOAD\\\", \\\"true\\\")\\n    return env\\n\\n\\ndef _build_langflow_run_argv(extra_args: list[str]) -> list[str]:\\n    \\\"\\\"\\\"Build the argv list that exec's ``langflow run``.\\n\\n    Falls back to ``python -m langflow`` when the ``langflow`` binary is\\n    not on PATH so the dev loop still works inside an ``lfx``-only\\n    install (author hits a clear failure mode rather than a confusing\\n    one).\\n    \\\"\\\"\\\"\\n    binary = _resolve_langflow_executable()\\n    if binary is not None:\\n        return [binary, \\\"run\\\", *extra_args]\\n    return [sys.executable, \\\"-m\\\", \\\"langflow\\\", \\\"run\\\", *extra_args]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/_extension_reload_client.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3318b1f42f5f1306150ee44448534f3bdec01fd0cea24d8a6133fb4afa5dc260\",\"content\":\"\\\"\\\"\\\"HTTP client helper for ``lfx extension reload``.\\n\\nKept separate from the typer command so the request/response shape can be\\nunit-tested without spinning up a full CLI invocation.  The CLI command\\nin :mod:`lfx.cli._extension_commands` delegates to :func:`reload_via_http`\\nand is responsible only for argument parsing and rendering.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport os\\nfrom dataclasses import dataclass\\nfrom typing import Any\\n\\nimport httpx\\n\\nDEFAULT_TARGET = \\\"http://localhost:7860\\\"\\n\\\"\\\"\\\"Fallback Langflow server URL when neither ``--target`` nor ``LANGFLOW_HOST`` is set.\\\"\\\"\\\"\\n\\n_HTTP_OK = 200\\n\\\"\\\"\\\"Named constant for the only status code we treat as a success.\\\"\\\"\\\"\\n\\n\\n@dataclass(frozen=True)\\nclass ReloadHttpResponse:\\n    \\\"\\\"\\\"Outcome of a single HTTP reload call.\\n\\n    ``status`` is the HTTP status code (200 on success; 409 for\\n    reload-in-progress; other non-2xx for transport / auth failures).\\n    ``payload`` is the parsed JSON body, or a synthetic ``{\\\"error\\\": ...}``\\n    dict when the response was not JSON.  ``ok`` mirrors the body's ``ok``\\n    field on success-shaped responses, otherwise False.\\n    \\\"\\\"\\\"\\n\\n    status: int\\n    payload: dict[str, Any]\\n    ok: bool\\n\\n    def exit_code(self) -> int:\\n        \\\"\\\"\\\"Map outcome to a CLI exit code (0 success / 1 failure).\\\"\\\"\\\"\\n        return 0 if self.ok else 1\\n\\n\\ndef resolve_target(explicit: str | None) -> str:\\n    \\\"\\\"\\\"Pick the server URL to call.  Precedence: explicit > $LANGFLOW_HOST > default.\\\"\\\"\\\"\\n    if explicit:\\n        return explicit.rstrip(\\\"/\\\")\\n    env_target = os.environ.get(\\\"LANGFLOW_HOST\\\")\\n    if env_target:\\n        return env_target.rstrip(\\\"/\\\")\\n    return DEFAULT_TARGET\\n\\n\\ndef resolve_api_key(explicit: str | None) -> str | None:\\n    \\\"\\\"\\\"Pick the API key to send.  Precedence: explicit > env > None.\\\"\\\"\\\"\\n    if explicit:\\n        return explicit\\n    return os.environ.get(\\\"LANGFLOW_API_KEY\\\")\\n\\n\\ndef reload_via_http(\\n    *,\\n    target: str | None,\\n    api_key: str | None,\\n    extension_id: str,\\n    bundle_name: str,\\n    timeout: float = 30.0,\\n) -> ReloadHttpResponse:\\n    \\\"\\\"\\\"POST a reload request to the Langflow extension dev server.\\n\\n    Returns a :class:`ReloadHttpResponse` that the caller renders.  Network\\n    failures raise no exceptions out of this helper -- they surface as a\\n    synthetic non-2xx response so the CLI can render them with the same\\n    typed-error formatting as server-side failures.\\n    \\\"\\\"\\\"\\n    base = resolve_target(target)\\n    url = f\\\"{base}/api/v1/extensions/{extension_id}/bundles/{bundle_name}/reload\\\"\\n    headers: dict[str, str] = {\\\"Accept\\\": \\\"application/json\\\"}\\n    key = resolve_api_key(api_key)\\n    if key is not None:\\n        headers[\\\"x-api-key\\\"] = key\\n\\n    try:\\n        with httpx.Client(timeout=timeout) as client:\\n            response = client.post(url, headers=headers)\\n    except httpx.RequestError as exc:\\n        # Transport-layer failure: connection refused, DNS, TLS, timeout.\\n        # Use ``reload-transport-error`` so the CLI / log scrapers can\\n        # distinguish \\\"could not reach the server\\\" from \\\"the server\\n        # responded that the source path is missing\\\" -- the latter is\\n        # ``reload-source-missing`` and is a server-side condition.\\n        return ReloadHttpResponse(\\n            status=0,\\n            payload={\\n                \\\"ok\\\": False,\\n                \\\"errors\\\": [\\n                    {\\n                        \\\"code\\\": \\\"reload-transport-error\\\",\\n                        \\\"message\\\": f\\\"Could not reach Langflow server at {url}: {exc}\\\",\\n                        \\\"location\\\": url,\\n                        \\\"hint\\\": (\\n                            \\\"Start the dev server (e.g. `lfx run`) and pass --target / \\\"\\n                            \\\"set LANGFLOW_HOST if it is not on http://localhost:7860.\\\"\\n                        ),\\n                    }\\n                ],\\n            },\\n            ok=False,\\n        )\\n\\n    try:\\n        payload = response.json()\\n        if not isinstance(payload, dict):\\n            payload = {\\\"ok\\\": False, \\\"raw\\\": payload}\\n    except ValueError:\\n        payload = {\\n            \\\"ok\\\": False,\\n            \\\"errors\\\": [\\n                {\\n                    \\\"code\\\": \\\"reload-transport-error\\\",\\n                    \\\"message\\\": f\\\"Server returned non-JSON body (HTTP {response.status_code}): {response.text[:200]}\\\",\\n                    \\\"location\\\": url,\\n                    \\\"hint\\\": \\\"Confirm the URL points at a Langflow server with the v1 API enabled.\\\",\\n                }\\n            ],\\n        }\\n\\n    success_ok = response.status_code == _HTTP_OK and bool(payload.get(\\\"ok\\\"))\\n    return ReloadHttpResponse(status=response.status_code, payload=payload, ok=success_ok)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/_observability_commands.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"38d0e6125c2de7fef31327235f43ded6bb28385efdf3d24bcec53e91505a1b75\",\"content\":\"\\\"\\\"\\\"Observability commands: ``observability doctor``.\\n\\nA sub-app rather than a flat ``lfx doctor``, so the verb stays scoped to telemetry instead of\\nclaiming to check the whole runtime.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport typer\\n\\nobservability_app = typer.Typer(\\n    name=\\\"observability\\\",\\n    help=\\\"Inspect and test the OTLP telemetry pipeline.\\\",\\n    no_args_is_help=True,\\n    add_completion=False,\\n)\\n\\n\\ndef register(app: typer.Typer) -> None:\\n    \\\"\\\"\\\"Mount the ``observability`` sub-app on *app*.\\\"\\\"\\\"\\n    app.add_typer(observability_app, name=\\\"observability\\\", rich_help_panel=\\\"Setup\\\")\\n\\n\\n@observability_app.command(\\n    name=\\\"doctor\\\",\\n    help=\\\"Send a synthetic span, metric and log to the configured OTLP endpoint and report the result.\\\",\\n)\\ndef doctor_command(\\n    timeout: float | None = typer.Option(\\n        None,\\n        \\\"--timeout\\\",\\n        help=(\\n            \\\"Per-export timeout in seconds. Defaults to OTEL_EXPORTER_OTLP_TIMEOUT or the SDK default. \\\"\\n            \\\"An unreachable endpoint consumes the full budget for each signal.\\\"\\n        ),\\n    ),\\n) -> None:\\n    \\\"\\\"\\\"Confirm telemetry actually reaches the backend, instead of trusting a silent exporter.\\\"\\\"\\\"\\n    import math\\n\\n    from rich.console import Console\\n    from rich.markup import escape\\n\\n    from lfx.log.logger import otel_log_bodies_exported\\n    from lfx.observability import db_spans_enabled\\n    from lfx.observability_doctor import FAILED, OK, SKIPPED, run_doctor\\n\\n    # highlight=False: the captured exporter messages are full of URLs and numbers, and rich's\\n    # auto-highlighting turns the one thing the operator needs to read into confetti.\\n    console = Console(highlight=False)\\n\\n    if timeout is not None and not (timeout > 0 and math.isfinite(timeout)):\\n        # The exporters resolve the timeout as `timeout or <env/default>`, so a zero would be\\n        # silently replaced by the default rather than failing fast. nan and inf pass a bare\\n        # `<= 0` check and then fail deep inside the transport as a bogus pipeline error.\\n        console.print(\\\"[red]--timeout must be a finite number greater than 0.[/red]\\\")\\n        raise typer.Exit(2)\\n\\n    report = run_doctor(timeout=timeout)\\n\\n    if report.error:\\n        console.print(f\\\"[red]{escape(report.error)}[/red]\\\")\\n        raise typer.Exit(1)\\n\\n    # Everything below that came from the environment or from a server goes through escape().\\n    # Markup is on, and these strings routinely contain square brackets: an IPv6 endpoint like\\n    # http://[fd00::1]:4318 would otherwise render as http://:4318, silently deleting the address\\n    # in the one tool whose job is naming which end is wrong, and an unbalanced tag in a server's\\n    # reason phrase would abort the whole report with a MarkupError.\\n    console.print(f\\\"service.name: [cyan]{escape(report.service_name)}[/cyan]\\\\n\\\")\\n\\n    marks = {OK: \\\"[green]OK[/green]\\\", FAILED: \\\"[red]FAILED[/red]\\\", SKIPPED: \\\"[yellow]SKIPPED[/yellow]\\\"}\\n    for signal in report.signals:\\n        console.print(f\\\"{marks[signal.status]} {signal.signal}: {escape(signal.detail)}\\\")\\n        # Per signal, because a per-signal header variable replaces the generic one rather than\\n        # adding to it. \\\"traces authenticate, metrics 401\\\" is exactly what this disambiguates.\\n        if signal.header_keys:\\n            console.print(f\\\"    [dim]headers: {escape(', '.join(signal.header_keys))}[/dim]\\\")\\n        for message in signal.exporter_logs:\\n            console.print(f\\\"    [dim]{escape(message)}[/dim]\\\")\\n        # The signals do not carry the same content, and the doctor is where an operator checks\\n        # what they are about to send. Saying it per signal beats a paragraph in a vendor doc.\\n        if signal.signal == \\\"logs\\\" and signal.status != SKIPPED:\\n            if otel_log_bodies_exported():\\n                console.print(\\n                    \\\"    [yellow]message bodies ARE exported (LANGFLOW_OTEL_LOG_BODIES=all): \\\"\\n                    \\\"completions, chat history and provider error text[/yellow]\\\"\\n                )\\n            else:\\n                console.print(\\n                    \\\"    [dim]bodies withheld unless a call site opts in; records keep \\\"\\n                    \\\"severity, scope, callsite, error.type and trace correlation[/dim]\\\"\\n                )\\n        # Volume, for the same reason the logs note exists: an operator sizing a paid APM needs\\n        # to know this before the first bill, not after. Database spans are the bulk of it.\\n        if signal.signal == \\\"traces\\\" and signal.status != SKIPPED:\\n            if db_spans_enabled():\\n                console.print(\\n                    # \\\"enabled\\\", not \\\"are exported\\\": this reads the setting, and it cannot\\n                    # see whether the instrumentor actually attached. _instrument_sqlalchemy\\n                    # swallows an ImportError or a double-instrument, so claiming export\\n                    # here would be a confident lie on exactly the box where it is wrong.\\n                    \\\"    [dim]database span export is enabled. When the instrumentation \\\"\\n                    \\\"attaches, these are most of the volume (~50 spans per flow run). Set \\\"\\n                    \\\"LANGFLOW_OTEL_DB_SPANS=false to send flow and request spans only, at \\\"\\n                    \\\"the cost of losing database latency[/dim]\\\"\\n                )\\n            else:\\n                console.print(\\n                    \\\"    [yellow]database spans are OFF (LANGFLOW_OTEL_DB_SPANS): a slow run \\\"\\n                    \\\"waiting on the database will show no cause[/yellow]\\\"\\n                )\\n\\n    if not report.ok:\\n        raise typer.Exit(1)\\n\\n    if not report.configured:\\n        console.print(\\\"\\\\n[yellow]No OTLP endpoint is configured, so nothing was sent.[/yellow]\\\")\\n        raise typer.Exit(1)\\n    if all(signal.status == SKIPPED for signal in report.signals):\\n        console.print(\\\"\\\\n[yellow]Every signal is disabled, so nothing was sent.[/yellow]\\\")\\n        raise typer.Exit(1)\\n\\n    console.print(\\n        f\\\"\\\\nLook for [cyan]{escape(report.service_name)}[/cyan] items named [cyan]lfx.observability.doctor[/cyan].\\\"\\n    )\\n    # A green result means this process can reach the backend with this configuration. It does\\n    # not mean a separate running server installed its providers: bootstrap declines traces and\\n    # logs when another provider is already present, which only that process can observe.\\n    console.print(\\n        \\\"[dim]Checked configuration and reachability from this process. A running server can \\\"\\n        \\\"still fail to export if something else installed its providers first.[/dim]\\\"\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/_prewarm_commands.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"34255c3f6a2934b23f59d8306ebf3331a98d570221fa9dd3dc84deacbddaff15\",\"content\":\"\\\"\\\"\\\"Pre-warm command: prewarm.\\\"\\\"\\\"\\n\\nimport typer\\n\\n\\ndef register(app: typer.Typer) -> None:\\n    \\\"\\\"\\\"Register the pre-warm command on *app*.\\\"\\\"\\\"\\n\\n    @app.command(\\n        name=\\\"prewarm\\\",\\n        help=\\\"Warm core component imports + execution paths (for snapshot capture)\\\",\\n        rich_help_panel=\\\"Setup\\\",\\n    )\\n    def prewarm_command_wrapper(\\n        flow: list[str] | None = typer.Option(\\n            None,\\n            \\\"--flow\\\",\\n            help=\\\"Flow JSON path to warm by building it (repeatable). Warms exactly that flow's components.\\\",\\n        ),\\n        unsafe_run: bool = typer.Option(\\n            False,\\n            \\\"--unsafe-run-may-leak-connections\\\",\\n            help=(\\n                \\\"DANGER \u2014 only if you know what you're doing. Fully EXECUTES each --flow, firing its REAL \\\"\\n                \\\"side effects (model calls, DB writes, etc.) and leaving live connections. NOT fork-safe: \\\"\\n                \\\"never use before a Gunicorn/preload fork \u2014 Firecracker snapshot/restore only. You must supply \\\"\\n                \\\"required credentials and the flow must be idempotent.\\\"\\n            ),\\n        ),\\n        freeze: bool = typer.Option(\\n            False,\\n            \\\"--freeze\\\",\\n            help=\\\"Run gc.collect()+gc.freeze() afterwards to preserve copy-on-write sharing.\\\",\\n        ),\\n        skip_run: bool = typer.Option(\\n            False,\\n            \\\"--skip-run\\\",\\n            help=\\\"Import only; skip the model-free hermetic warm-up run.\\\",\\n        ),\\n        verbose: bool = typer.Option(\\n            False,\\n            \\\"-v\\\",\\n            \\\"--verbose\\\",\\n            help=\\\"List each imported component and warmed flow.\\\",\\n        ),\\n    ) -> None:\\n        \\\"\\\"\\\"Warm core component imports, the execution machinery, and (optionally) specific flows.\\n\\n        Run this in a long-lived process just before capturing a warm snapshot (or before a\\n        Gunicorn ``--preload`` fork), so the first flow build/run after restore skips the\\n        lazy-import cost. By default nothing is executed with real side effects \u2014 this path is\\n        fork-safe. The ``--unsafe-run-may-leak-connections`` flag fully executes each ``--flow``\\n        (Firecracker only \u2014 never before a fork); see the warning on that flag.\\n        \\\"\\\"\\\"\\n        from lfx.preload import PrewarmError, freeze_heap, prewarm_core_imports, prewarm_flow, teardown_warm_services\\n\\n        failed = False\\n\\n        # One teardown pass after all warming, so per-flow warming doesn't re-instantiate\\n        # what the base layer disposed. --unsafe-run keeps live connections, so skip it.\\n        do_teardown = not unsafe_run\\n\\n        # Base layer: common component imports + model-free execution machinery.\\n        try:\\n            core = prewarm_core_imports(warmup_run=not skip_run, freeze=False, teardown_services=False)\\n        except PrewarmError as exc:\\n            typer.echo(f\\\"prewarm failed: {exc}\\\", err=True)\\n            raise typer.Exit(1) from exc\\n\\n        suffix = \\\" (warm-up run)\\\" if core.warmup_ran else \\\"\\\"\\n        failed_note = f\\\", {len(core.failed)} failed\\\" if core.failed else \\\"\\\"\\n        typer.echo(\\n            f\\\"Pre-warmed: {len(core.imported)} component(s) imported{failed_note}{suffix} in {core.elapsed_s:.3f}s\\\"\\n        )\\n        if verbose:\\n            for component in core.imported:\\n                typer.echo(f\\\"  ok   {component}\\\")\\n        for component, err in core.failed.items():\\n            typer.echo(f\\\"  skip {component}: {err}\\\")\\n\\n        # Per-flow layer: warm exactly the supplied flows (optionally executing them).\\n        for flow_path in flow or []:\\n            fr = prewarm_flow(flow_path, run=unsafe_run, freeze=False, teardown_services=False)\\n            if fr.error:\\n                failed = True\\n                typer.echo(f\\\"  FAIL flow {flow_path}: {fr.error}\\\", err=True)\\n            else:\\n                state = \\\"built+ran\\\" if fr.ran else \\\"built\\\"\\n                typer.echo(f\\\"  flow {flow_path}: {state} in {fr.elapsed_s:.3f}s\\\")\\n            # A run can leave fork-hostile state even when it errors mid-run (and --unsafe-run\\n            # skips teardown), so warn regardless of whether the flow reported an error.\\n            if fr.ghost_threads or fr.ghost_connections:\\n                typer.echo(\\n                    f\\\"    WARNING: run left fork-unsafe state \\\"\\n                    f\\\"(threads={fr.ghost_threads or '[]'}, connections={fr.ghost_connections or '[]'}). \\\"\\n                    f\\\"OK for Firecracker restore; do NOT capture this before a Gunicorn/preload fork.\\\",\\n                    err=True,\\n                )\\n\\n        # Dispose any services warming instantiated so a Gunicorn/preload fork can't\\n        # inherit a real plugin's live pool/socket/thread.\\n        if do_teardown:\\n            try:\\n                teardown_warm_services()\\n            except PrewarmError as exc:\\n                typer.echo(f\\\"prewarm failed: {exc}\\\", err=True)\\n                raise typer.Exit(1) from exc\\n            typer.echo(\\\"Disposed warm services (fork-safe).\\\")\\n\\n        if freeze:\\n            freeze_heap()\\n            typer.echo(\\\"Heap frozen (gc.freeze).\\\")\\n\\n        if failed:\\n            raise typer.Exit(1)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/_remote_commands.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1323b91b655c8a61a41396834c10b65f058a8ff1fa6d6cb4b3dc3e406372cf22\",\"content\":\"\\\"\\\"\\\"Remote commands: status, push, pull, export.\\\"\\\"\\\"\\n\\nimport typer\\n\\n\\ndef register(app: typer.Typer) -> None:\\n    \\\"\\\"\\\"Register remote-stage commands on *app*.\\\"\\\"\\\"\\n\\n    @app.command(\\n        name=\\\"status\\\", help=\\\"Compare local flow files against a remote Langflow instance\\\", rich_help_panel=\\\"Remote\\\"\\n    )\\n    def status_command_wrapper(\\n        flow_paths: list[str] = typer.Argument(\\n            default=None,\\n            help=\\\"Specific flow JSON file(s) to check. Omit to scan --dir (default: flows/).\\\",\\n        ),\\n        env: str | None = typer.Option(\\n            None,\\n            \\\"--env\\\",\\n            \\\"-e\\\",\\n            help=\\\"Environment name from .lfx/environments.yaml. Uses [defaults] if omitted.\\\",\\n        ),\\n        dir_path: str | None = typer.Option(\\n            None,\\n            \\\"--dir\\\",\\n            \\\"-d\\\",\\n            help=\\\"Directory of flow JSON files to compare (default: flows/ in cwd).\\\",\\n        ),\\n        environments_file: str | None = typer.Option(\\n            None,\\n            \\\"--environments-file\\\",\\n            help=\\\"Path to environments config file (.yaml or .toml; overrides default lookup).\\\",\\n        ),\\n        target: str | None = typer.Option(\\n            None,\\n            \\\"--target\\\",\\n            help=\\\"Langflow instance URL (inline override \u2014 skips config file lookup).\\\",\\n        ),\\n        api_key: str | None = typer.Option(\\n            None,\\n            \\\"--api-key\\\",\\n            help=\\\"API key for the Langflow instance (used with --target or to override config).\\\",\\n        ),\\n        show_remote_only: bool = typer.Option(\\n            False,\\n            \\\"--remote-only\\\",\\n            help=\\\"Also list flows that exist on the server but have no local file.\\\",\\n        ),\\n    ) -> None:\\n        \\\"\\\"\\\"Show whether local flow files are in sync, ahead, or missing vs the remote instance.\\\"\\\"\\\"\\n        from lfx.cli.status import status_command\\n\\n        status_command(\\n            dir_path=dir_path,\\n            flow_paths=flow_paths or [],\\n            env=env,\\n            environments_file=environments_file,\\n            target=target,\\n            api_key=api_key,\\n            show_remote_only=show_remote_only,\\n        )\\n\\n    @app.command(\\n        name=\\\"push\\\",\\n        help=\\\"Push flow JSON to a remote Langflow instance (upsert by stable ID)\\\",\\n        rich_help_panel=\\\"Remote\\\",\\n    )\\n    def push_command_wrapper(\\n        flow_paths: list[str] = typer.Argument(\\n            default=None,\\n            help=\\\"Path(s) to flow JSON file(s) to push. Use --dir for a whole directory.\\\",\\n        ),\\n        env: str | None = typer.Option(\\n            None,\\n            \\\"--env\\\",\\n            \\\"-e\\\",\\n            help=\\\"Environment name from .lfx/environments.yaml. Use --target for inline configuration.\\\",\\n        ),\\n        dir_path: str | None = typer.Option(\\n            None,\\n            \\\"--dir\\\",\\n            \\\"-d\\\",\\n            help=\\\"Directory of flow JSON files to push (pushes all *.json files). Defaults to flows/.\\\",\\n        ),\\n        project: str | None = typer.Option(\\n            None,\\n            \\\"--project\\\",\\n            \\\"-p\\\",\\n            help=\\\"Target project name on the remote instance. Created if it does not exist.\\\",\\n        ),\\n        project_id: str | None = typer.Option(\\n            None,\\n            \\\"--project-id\\\",\\n            help=\\\"Target project UUID (alternative to --project).\\\",\\n        ),\\n        environments_file: str | None = typer.Option(\\n            None,\\n            \\\"--environments-file\\\",\\n            help=\\\"Path to environments config file (.yaml or .toml; overrides default lookup).\\\",\\n        ),\\n        target: str | None = typer.Option(\\n            None,\\n            \\\"--target\\\",\\n            help=\\\"Langflow instance URL (inline override \u2014 skips config file lookup).\\\",\\n        ),\\n        api_key: str | None = typer.Option(\\n            None,\\n            \\\"--api-key\\\",\\n            help=\\\"API key for the Langflow instance (used with --target or to override config).\\\",\\n        ),\\n        dry_run: bool = typer.Option(\\n            False,\\n            \\\"--dry-run\\\",\\n            help=\\\"Show what would be pushed without making any changes.\\\",\\n        ),\\n        normalize: bool = typer.Option(\\n            True,\\n            \\\"--normalize/--no-normalize\\\",\\n            help=\\\"Normalize (strip volatile fields, sort keys) before pushing.\\\",\\n        ),\\n        strip_secrets: bool = typer.Option(\\n            True,\\n            \\\"--strip-secrets/--keep-secrets\\\",\\n            help=\\\"Clear password/load_from_db field values before pushing.\\\",\\n        ),\\n    ) -> None:\\n        \\\"\\\"\\\"Push Langflow flows to a remote instance using stable IDs for upsert (lazy-loaded).\\\"\\\"\\\"\\n        from lfx.cli.push import push_command\\n\\n        push_command(\\n            flow_paths=flow_paths or [],\\n            env=env,\\n            dir_path=dir_path,\\n            project=project,\\n            project_id=project_id,\\n            environments_file=environments_file,\\n            target=target,\\n            api_key=api_key,\\n            dry_run=dry_run,\\n            normalize=normalize,\\n            strip_secrets=strip_secrets,\\n        )\\n\\n    @app.command(\\n        name=\\\"pull\\\", help=\\\"Pull flows from a remote Langflow instance to local files\\\", rich_help_panel=\\\"Remote\\\"\\n    )\\n    def pull_command_wrapper(\\n        env: str | None = typer.Option(\\n            None,\\n            \\\"--env\\\",\\n            \\\"-e\\\",\\n            help=\\\"Environment name from .lfx/environments.yaml. Uses [defaults] if omitted.\\\",\\n        ),\\n        output_dir: str | None = typer.Option(\\n            None,\\n            \\\"--output-dir\\\",\\n            \\\"-d\\\",\\n            help=\\\"Directory to write pulled flows into (default: flows/).\\\",\\n        ),\\n        flow_id: str | None = typer.Option(\\n            None,\\n            \\\"--flow-id\\\",\\n            help=\\\"Pull a single flow by UUID.\\\",\\n        ),\\n        project: str | None = typer.Option(\\n            None,\\n            \\\"--project\\\",\\n            \\\"-p\\\",\\n            help=\\\"Pull all flows in a named project.\\\",\\n        ),\\n        project_id: str | None = typer.Option(\\n            None,\\n            \\\"--project-id\\\",\\n            help=\\\"Pull all flows in a project by UUID.\\\",\\n        ),\\n        environments_file: str | None = typer.Option(\\n            None,\\n            \\\"--environments-file\\\",\\n            help=\\\"Path to environments config file (.yaml or .toml; overrides default lookup).\\\",\\n        ),\\n        target: str | None = typer.Option(\\n            None,\\n            \\\"--target\\\",\\n            help=\\\"Langflow instance URL (inline override \u2014 skips config file lookup).\\\",\\n        ),\\n        api_key: str | None = typer.Option(\\n            None,\\n            \\\"--api-key\\\",\\n            help=\\\"API key for the Langflow instance (used with --target or to override config).\\\",\\n        ),\\n        strip_secrets: bool = typer.Option(\\n            True,\\n            \\\"--strip-secrets/--keep-secrets\\\",\\n            help=\\\"Clear password/load_from_db field values (default: strip).\\\",\\n        ),\\n        indent: int = typer.Option(\\n            2,\\n            \\\"--indent\\\",\\n            help=\\\"JSON indentation level.\\\",\\n        ),\\n    ) -> None:\\n        \\\"\\\"\\\"Pull and normalize flows from a remote Langflow instance (lazy-loaded).\\\"\\\"\\\"\\n        from lfx.cli.pull import pull_command\\n\\n        pull_command(\\n            env=env,\\n            output_dir=output_dir,\\n            flow_id=flow_id,\\n            project=project,\\n            project_id=project_id,\\n            environments_file=environments_file,\\n            target=target,\\n            api_key=api_key,\\n            strip_secrets=strip_secrets,\\n            indent=indent,\\n        )\\n\\n    @app.command(\\n        name=\\\"export\\\",\\n        help=\\\"Normalize flow JSON for git (local) or pull from a remote instance\\\",\\n        rich_help_panel=\\\"Remote\\\",\\n    )\\n    def export_command_wrapper(\\n        flow_paths: list[str] = typer.Argument(\\n            default=None,\\n            help=\\\"Path(s) to local flow JSON file(s) to normalize. Omit when using --flow-id or --project-id.\\\",\\n        ),\\n        output: str | None = typer.Option(\\n            None,\\n            \\\"--output\\\",\\n            \\\"-o\\\",\\n            help=\\\"Output file path (single-file local mode only).\\\",\\n        ),\\n        output_dir: str | None = typer.Option(\\n            None,\\n            \\\"--output-dir\\\",\\n            \\\"-d\\\",\\n            help=\\\"Directory to write exported flows into (remote mode or multi-file).\\\",\\n        ),\\n        env: str | None = typer.Option(\\n            None,\\n            \\\"--env\\\",\\n            \\\"-e\\\",\\n            help=\\\"Environment name from .lfx/environments.yaml (required for remote mode unless --target is used).\\\",\\n        ),\\n        flow_id: str | None = typer.Option(\\n            None,\\n            \\\"--flow-id\\\",\\n            help=\\\"Pull and export a single flow by UUID from the remote instance.\\\",\\n        ),\\n        project_id: str | None = typer.Option(\\n            None,\\n            \\\"--project-id\\\",\\n            help=\\\"Pull and export all flows in a project by UUID from the remote instance.\\\",\\n        ),\\n        environments_file: str | None = typer.Option(\\n            None,\\n            \\\"--environments-file\\\",\\n            help=\\\"Path to environments config file (.yaml or .toml; overrides default lookup).\\\",\\n        ),\\n        target: str | None = typer.Option(\\n            None,\\n            \\\"--target\\\",\\n            help=\\\"Langflow instance URL (inline override \u2014 skips config file lookup).\\\",\\n        ),\\n        api_key: str | None = typer.Option(\\n            None,\\n            \\\"--api-key\\\",\\n            help=\\\"API key for the Langflow instance (used with --target or to override config).\\\",\\n        ),\\n        in_place: bool = typer.Option(\\n            False,\\n            \\\"--in-place\\\",\\n            \\\"-i\\\",\\n            help=\\\"Overwrite each input file with its normalized version.\\\",\\n        ),\\n        strip_volatile: bool = typer.Option(\\n            True,\\n            \\\"--strip-volatile/--keep-volatile\\\",\\n            help=\\\"Strip instance-specific fields (updated_at, user_id, folder_id).\\\",\\n        ),\\n        strip_secrets: bool = typer.Option(\\n            True,\\n            \\\"--strip-secrets/--keep-secrets\\\",\\n            help=\\\"Clear values of password/load_from_db template fields.\\\",\\n        ),\\n        code_as_lines: bool = typer.Option(\\n            False,\\n            \\\"--code-as-lines\\\",\\n            help=\\\"Convert code-type template field values to a list of lines.\\\",\\n        ),\\n        strip_node_volatile: bool = typer.Option(\\n            True,\\n            \\\"--strip-node-volatile/--keep-node-volatile\\\",\\n            help=\\\"Strip transient node keys (positionAbsolute, dragging, selected).\\\",\\n        ),\\n        indent: int = typer.Option(\\n            2,\\n            \\\"--indent\\\",\\n            help=\\\"JSON indentation level.\\\",\\n        ),\\n    ) -> None:\\n        \\\"\\\"\\\"Export and normalize Langflow flow JSON for version control (lazy-loaded).\\\"\\\"\\\"\\n        from lfx.cli.export import export_command\\n\\n        export_command(\\n            flow_paths=flow_paths or [],\\n            output=output,\\n            output_dir=output_dir,\\n            env=env,\\n            flow_id=flow_id,\\n            project_id=project_id,\\n            environments_file=environments_file,\\n            target=target,\\n            api_key=api_key,\\n            in_place=in_place,\\n            strip_volatile=strip_volatile,\\n            strip_secrets=strip_secrets,\\n            code_as_lines=code_as_lines,\\n            strip_node_volatile=strip_node_volatile,\\n            indent=indent,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/_running_commands.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3a4e37f08fd3e14a7122f13b2c40048d3c9367c410a2f4824a57b89b47e2a91b\",\"content\":\"\\\"\\\"\\\"Running commands: run, serve.\\\"\\\"\\\"\\n\\nimport typer\\n\\nfrom lfx.cli import _serve_help\\nfrom lfx.upgrade.cli_gate import UpgradeFlowMode\\n\\n\\ndef register(app: typer.Typer) -> None:\\n    \\\"\\\"\\\"Register running-stage commands on *app*.\\\"\\\"\\\"\\n\\n    @app.command(name=\\\"run\\\", help=\\\"Run a flow directly\\\", no_args_is_help=True, rich_help_panel=\\\"Running\\\")\\n    def run_command_wrapper(\\n        script_path: str | None = typer.Argument(\\n            None, help=\\\"Path to the Python script (.py) or JSON flow (.json) containing a graph\\\"\\n        ),\\n        input_value: str | None = typer.Argument(None, help=\\\"Input value to pass to the graph\\\"),\\n        input_value_option: str | None = typer.Option(\\n            None,\\n            \\\"--input-value\\\",\\n            help=\\\"Input value to pass to the graph (alternative to positional argument)\\\",\\n        ),\\n        output_format: str = typer.Option(\\n            \\\"json\\\",\\n            \\\"--format\\\",\\n            \\\"-f\\\",\\n            help=\\\"Output format: json, text, message, or result\\\",\\n        ),\\n        flow_json: str | None = typer.Option(\\n            None,\\n            \\\"--flow-json\\\",\\n            help=\\\"Inline JSON flow content as a string (alternative to script_path)\\\",\\n        ),\\n        *,\\n        stdin: bool = typer.Option(\\n            default=False,\\n            show_default=True,\\n            help=\\\"Read JSON flow content from stdin (alternative to script_path)\\\",\\n        ),\\n        check_variables: bool = typer.Option(\\n            default=True,\\n            show_default=True,\\n            help=\\\"Check global variables for environment compatibility\\\",\\n        ),\\n        check_dependencies: bool = typer.Option(\\n            default=True,\\n            show_default=True,\\n            help=\\\"Preflight the flow's required packages; fail fast with install guidance when any are missing\\\",\\n        ),\\n        verbose: bool = typer.Option(\\n            False,\\n            \\\"-v\\\",\\n            \\\"--verbose\\\",\\n            help=\\\"Show basic progress information\\\",\\n        ),\\n        verbose_detailed: bool = typer.Option(\\n            False,\\n            \\\"-vv\\\",\\n            help=\\\"Show detailed progress and debug information\\\",\\n        ),\\n        verbose_full: bool = typer.Option(\\n            False,\\n            \\\"-vvv\\\",\\n            help=\\\"Show full debugging output including component logs\\\",\\n        ),\\n        timing: bool = typer.Option(\\n            default=False,\\n            show_default=True,\\n            help=\\\"Include detailed timing information in output\\\",\\n        ),\\n        session_id: str | None = typer.Option(\\n            None,\\n            \\\"--session-id\\\",\\n            help=(\\n                \\\"Session ID to attach to the run. \\\"\\n                \\\"Agent and Memory Components will use this to track conversation history.\\\"\\n            ),\\n        ),\\n        upgrade_flow: UpgradeFlowMode | None = typer.Option(\\n            None,\\n            \\\"--upgrade-flow\\\",\\n            help=(\\n                \\\"Component compatibility mode. \\\"\\n                \\\"'check' refuses to run if any component is outdated or blocked. \\\"\\n                \\\"'safe' auto-applies safe upgrades; aborts on breaking or blocked components.\\\"\\n            ),\\n        ),\\n        human_input: bool | None = typer.Option(\\n            None,\\n            \\\"--human-input/--no-human-input\\\",\\n            help=(\\n                \\\"Interactive human-in-the-loop. Default auto-enables it when the flow has a \\\"\\n                \\\"pausing node (e.g. HumanInput) and the terminal is interactive; the run then \\\"\\n                \\\"prompts at each pause. Use --no-human-input to disable. Interactive-session \\\"\\n                \\\"only: checkpoints are in-memory, so a paused run cannot be resumed later or \\\"\\n                \\\"from another process. Non-interactive runs do not pause (a warning is printed).\\\"\\n            ),\\n        ),\\n    ) -> None:\\n        \\\"\\\"\\\"Run a flow directly (lazy-loaded).\\\"\\\"\\\"\\n        from pathlib import Path\\n\\n        from lfx.cli.run import run\\n\\n        # Convert script_path string to Path if provided\\n        script_path_obj = Path(script_path) if script_path else None\\n\\n        run(\\n            script_path=script_path_obj,\\n            input_value=input_value,\\n            input_value_option=input_value_option,\\n            output_format=output_format,\\n            flow_json=flow_json,\\n            stdin=stdin,\\n            check_variables=check_variables,\\n            check_dependencies=check_dependencies,\\n            verbose=verbose,\\n            verbose_detailed=verbose_detailed,\\n            verbose_full=verbose_full,\\n            timing=timing,\\n            session_id=session_id,\\n            upgrade_flow=upgrade_flow,\\n            human_input=human_input,\\n        )\\n\\n    @app.command(name=\\\"serve\\\", help=\\\"Serve a flow as an API\\\", rich_help_panel=\\\"Running\\\")\\n    def serve_command_wrapper(\\n        script_paths: list[str] | None = typer.Argument(\\n            default=None,\\n            help=(\\n                \\\"Path(s) to JSON flow file(s) (.json), Python script(s) (.py), or a directory \\\"\\n                \\\"containing .json files (top-level only, non-recursive). \\\"\\n                \\\"Optional when using --flow-json or --stdin.\\\"\\n            ),\\n        ),\\n        host: str = typer.Option(\\\"127.0.0.1\\\", \\\"--host\\\", \\\"-h\\\", help=\\\"Host to bind the server to\\\"),\\n        port: int = typer.Option(8000, \\\"--port\\\", \\\"-p\\\", help=\\\"Port to bind the server to\\\"),\\n        workers: int = typer.Option(\\n            1,\\n            \\\"--workers\\\",\\n            \\\"-w\\\",\\n            help=\\\"Number of worker processes (gunicorn on Unix, uvicorn on Windows). \\\"\\n            \\\"Use with --flow-dir for multi-worker flow sharing.\\\",\\n        ),\\n        verbose: bool = typer.Option(False, \\\"--verbose\\\", \\\"-v\\\", help=\\\"Show diagnostic output and execution details\\\"),\\n        env_file: str | None = typer.Option(\\n            None,\\n            \\\"--env-file\\\",\\n            help=\\\"Path to the .env file containing environment variables\\\",\\n        ),\\n        log_level: str = typer.Option(\\n            \\\"warning\\\",\\n            \\\"--log-level\\\",\\n            help=\\\"Logging level. One of: debug, info, warning, error, critical\\\",\\n        ),\\n        flow_json: str | None = typer.Option(\\n            None,\\n            \\\"--flow-json\\\",\\n            help=\\\"Inline JSON flow content as a string (alternative to script_paths)\\\",\\n        ),\\n        flow_dir: str | None = typer.Option(\\n            None,\\n            \\\"--flow-dir\\\",\\n            help=_serve_help.FLOW_DIR,\\n        ),\\n        max_requests: int | None = typer.Option(\\n            None,\\n            \\\"--max-requests\\\",\\n            help=_serve_help.MAX_REQUESTS,\\n        ),\\n        timeout: int | None = typer.Option(\\n            None,\\n            \\\"--timeout\\\",\\n            help=_serve_help.TIMEOUT,\\n        ),\\n        *,\\n        stdin: bool = typer.Option(\\n            False,\\n            \\\"--stdin\\\",\\n            help=\\\"Read JSON flow content from stdin (alternative to script_paths)\\\",\\n        ),\\n        check_variables: bool = typer.Option(\\n            True,\\n            \\\"--check-variables/--no-check-variables\\\",\\n            help=\\\"Check global variables for environment compatibility\\\",\\n        ),\\n        upgrade_flow: UpgradeFlowMode | None = typer.Option(\\n            None,\\n            \\\"--upgrade-flow\\\",\\n            help=(\\n                \\\"Component compatibility mode before serving. \\\"\\n                \\\"'check' refuses to serve if any component is outdated or blocked. \\\"\\n                \\\"'safe' auto-applies safe upgrades; aborts on breaking or blocked components.\\\"\\n            ),\\n        ),\\n        no_env_fallback: bool = typer.Option(\\n            False,\\n            \\\"--no-env-fallback/--env-fallback\\\",\\n            help=_serve_help.NO_ENV_FALLBACK,\\n        ),\\n        reset_environ: bool = typer.Option(\\n            False,\\n            \\\"--reset-environ/--no-reset-environ\\\",\\n            help=_serve_help.RESET_ENVIRON,\\n        ),\\n        sync_workers: bool = typer.Option(\\n            False,\\n            \\\"--use-sync-workers/--use-async-workers\\\",\\n            help=_serve_help.SYNC_WORKERS,\\n        ),\\n        identity_mode: str = typer.Option(\\n            \\\"off\\\",\\n            \\\"--identity-mode\\\",\\n            help=(\\n                \\\"Per-user identity forwarding mode. 'off' (default) ignores caller identity. \\\"\\n                \\\"'jwt' verifies a signed JWT (Authorization: Bearer or --identity-jwt-header) and \\\"\\n                \\\"threads its claim as user_id. 'header' trusts a plain gateway header verbatim \\\"\\n                \\\"(weaker; safe only when network policy guarantees the gateway is the sole caller).\\\"\\n            ),\\n        ),\\n        identity_jwt_issuer: str | None = typer.Option(\\n            None,\\n            \\\"--identity-jwt-issuer\\\",\\n            help=\\\"Expected JWT 'iss' (exact match). Required when --identity-mode=jwt.\\\",\\n        ),\\n        identity_jwt_audience: str | None = typer.Option(\\n            None,\\n            \\\"--identity-jwt-audience\\\",\\n            help=\\\"Expected JWT 'aud' (the token's audience must contain it). Required when --identity-mode=jwt.\\\",\\n        ),\\n        identity_jwt_jwks_url: str | None = typer.Option(\\n            None,\\n            \\\"--identity-jwt-jwks-url\\\",\\n            help=\\\"JWKS URL for signing keys. Optional; defaults to OIDC discovery from the issuer.\\\",\\n        ),\\n        identity_claim: str = typer.Option(\\n            \\\"sub\\\",\\n            \\\"--identity-claim\\\",\\n            help=\\\"JWT claim used as the caller identity (user_id). Defaults to 'sub'.\\\",\\n        ),\\n        identity_jwt_header: str = typer.Option(\\n            \\\"Authorization\\\",\\n            \\\"--identity-jwt-header\\\",\\n            help=\\\"Header the JWT is read from in jwt mode (a 'Bearer ' prefix is stripped). Defaults to Authorization.\\\",\\n        ),\\n        identity_header: str = typer.Option(\\n            \\\"X-Consumer-Username\\\",\\n            \\\"--identity-header\\\",\\n            help=\\\"Plain header trusted as identity in header mode. Defaults to X-Consumer-Username.\\\",\\n        ),\\n        identity_jwt_allow_insecure_http: bool = typer.Option(\\n            False,\\n            \\\"--identity-jwt-allow-insecure-http\\\",\\n            help=\\\"Allow plaintext http:// for the JWKS/issuer (dev/test only). HTTPS is required by default.\\\",\\n        ),\\n    ) -> None:\\n        \\\"\\\"\\\"Serve LFX flows as a web API (lazy-loaded).\\\"\\\"\\\"\\n        from pathlib import Path\\n\\n        from lfx.cli.commands import serve_command\\n\\n        env_file_path = Path(env_file) if env_file else None\\n        flow_dir_path = Path(flow_dir) if flow_dir else None\\n\\n        serve_command(\\n            script_paths=script_paths,\\n            host=host,\\n            port=port,\\n            workers=workers,\\n            verbose=verbose,\\n            env_file=env_file_path,\\n            log_level=log_level,\\n            flow_json=flow_json,\\n            flow_dir=flow_dir_path,\\n            stdin=stdin,\\n            check_variables=check_variables,\\n            upgrade_flow=upgrade_flow,\\n            no_env_fallback=no_env_fallback,\\n            max_requests=max_requests,\\n            reset_environ=reset_environ,\\n            sync_workers=sync_workers,\\n            timeout=timeout,\\n            identity_mode=identity_mode,\\n            identity_jwt_issuer=identity_jwt_issuer,\\n            identity_jwt_audience=identity_jwt_audience,\\n            identity_jwt_jwks_url=identity_jwt_jwks_url,\\n            identity_claim=identity_claim,\\n            identity_jwt_header=identity_jwt_header,\\n            identity_header=identity_header,\\n            identity_jwt_allow_insecure_http=identity_jwt_allow_insecure_http,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/_serve_help.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5ab6a496dbf5e4128879852f37b16f50276bb14edc15d439782108b4aba9ed4b\",\"content\":\"\\\"\\\"\\\"Shared ``--help`` text for the multi-line ``lfx serve`` options.\\n\\nThese options are declared twice \u2014 in the lazy CLI wrapper (``_running_commands``) and in\\nthe implementation ``commands.serve_command`` (which is also registered as a standalone\\ntyper command in tests). Defining the substantial help text once here keeps the two from\\ndrifting. Trivial one-line help (host, port, ...) stays inline at each call site.\\n\\nKept dependency-free so importing it never defeats the wrapper's lazy import of the heavy\\n``commands`` module.\\n\\\"\\\"\\\"\\n\\nFLOW_DIR = (\\n    \\\"Directory for filesystem-backed flow storage. \\\"\\n    \\\"All uvicorn workers sharing this path will serve the same flows. \\\"\\n    \\\"Use /tmp/lfx-flows for single-pod sharing or a PVC mount for cross-pod. \\\"\\n    \\\"Defaults to in-memory only when omitted.\\\"\\n)\\n\\nMAX_REQUESTS = (\\n    \\\"Recycle each worker after N requests to bound memory (gunicorn, Unix, --workers > 1). \\\"\\n    \\\"Default: recycle every ~1000 (10% jitter); 0 disables; 1 = every request. Not applied \\\"\\n    \\\"on Windows. Worker hygiene, NOT per-request isolation \u2014 for that use --reset-environ, \\\"\\n    \\\"or --use-sync-workers together with --max-requests 1 (a sync worker alone only prevents \\\"\\n    \\\"in-worker overlap; a warm process still carries os.environ mutations to later requests).\\\"\\n)\\n\\nTIMEOUT = (\\n    \\\"Worker timeout in seconds (gunicorn, Unix, --workers > 1): a worker that does not \\\"\\n    \\\"complete a request within this many seconds is killed and restarted. Raise it for \\\"\\n    \\\"long-running flows, especially with --use-sync-workers (a blocking sync worker cannot \\\"\\n    \\\"heartbeat mid-request). Default: 120. No effect on Windows (uvicorn fallback).\\\"\\n)\\n\\nNO_ENV_FALLBACK = (\\n    \\\"Disable os.environ fallback for credential variables. \\\"\\n    \\\"Variables not supplied via global_vars on each request resolve to None \\\"\\n    \\\"instead of reading from the process environment.\\\"\\n)\\n\\nRESET_ENVIRON = (\\n    \\\"Snapshot os.environ before each flow run and restore it afterward, so a \\\"\\n    \\\"flow's environment mutations (or request-scoped credentials) cannot leak \\\"\\n    \\\"into the next request served by the same warm worker. Off by default.\\\"\\n)\\n\\nSYNC_WORKERS = (\\n    \\\"Use gunicorn's blocking 'sync' worker (Unix, --workers > 1) so the kernel \\\"\\n    \\\"routes each request to an idle worker instead of queueing it behind an \\\"\\n    \\\"in-flight request on a busy async worker. Uses the 'a2wsgi' bridge bundled \\\"\\n    \\\"with lfx on Unix. Off by default (async worker).\\\"\\n)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/_setup_commands.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"97c90e03b7dd5a40d96b2dda327d8f77aade2b660cc1329a38269bf3313fbcd5\",\"content\":\"\\\"\\\"\\\"Setup commands: init, login.\\\"\\\"\\\"\\n\\nimport typer\\n\\n\\ndef register(app: typer.Typer) -> None:\\n    \\\"\\\"\\\"Register setup-stage commands on *app*.\\\"\\\"\\\"\\n\\n    @app.command(name=\\\"init\\\", help=\\\"Scaffold a new Flow DevOps project\\\", rich_help_panel=\\\"Setup\\\")\\n    def init_command_wrapper(\\n        project_dir: str = typer.Argument(\\n            \\\".\\\",\\n            help=\\\"Directory to scaffold (created if it does not exist; default: current directory).\\\",\\n        ),\\n        github_actions: bool = typer.Option(\\n            True,\\n            \\\"--github-actions/--no-github-actions\\\",\\n            help=\\\"Copy GitHub Actions workflow templates into .github/workflows/.\\\",\\n        ),\\n        overwrite: bool = typer.Option(\\n            False,\\n            \\\"--overwrite\\\",\\n            help=\\\"Write files even if the target directory already contains files.\\\",\\n        ),\\n        example: bool = typer.Option(\\n            True,\\n            \\\"--example/--no-example\\\",\\n            help=\\\"Seed flows/ with a hello-world.json starter flow (default: true).\\\",\\n        ),\\n    ) -> None:\\n        \\\"\\\"\\\"Scaffold a Flow DevOps project: flows/, tests/, environments config, and CI templates.\\\"\\\"\\\"\\n        from pathlib import Path\\n\\n        from lfx.cli.init import init_command\\n\\n        init_command(\\n            project_dir=Path(project_dir),\\n            github_actions=github_actions,\\n            overwrite=overwrite,\\n            example=example,\\n        )\\n\\n    @app.command(name=\\\"login\\\", help=\\\"Validate credentials against a remote Langflow instance\\\", rich_help_panel=\\\"Setup\\\")\\n    def login_command_wrapper(\\n        env: str | None = typer.Option(\\n            None,\\n            \\\"--env\\\",\\n            \\\"-e\\\",\\n            help=\\\"Environment name from .lfx/environments.yaml. Uses [defaults] if omitted.\\\",\\n        ),\\n        environments_file: str | None = typer.Option(\\n            None,\\n            \\\"--environments-file\\\",\\n            help=\\\"Path to environments config file (.yaml or .toml; overrides default lookup).\\\",\\n        ),\\n        target: str | None = typer.Option(\\n            None,\\n            \\\"--target\\\",\\n            help=\\\"Langflow instance URL (inline override \u2014 skips config file lookup).\\\",\\n        ),\\n        api_key: str | None = typer.Option(\\n            None,\\n            \\\"--api-key\\\",\\n            help=\\\"API key for the Langflow instance (used with --target or to override config).\\\",\\n        ),\\n    ) -> None:\\n        \\\"\\\"\\\"Test connectivity and authentication for a Langflow environment (lazy-loaded).\\\"\\\"\\\"\\n        from lfx.cli.login import login_command\\n\\n        login_command(\\n            env=env,\\n            environments_file=environments_file,\\n            target=target,\\n            api_key=api_key,\\n        )\\";
